-- Brote — seed de la Academia (El Bosque).
-- GENERADO por scripts/gen-academia-seed.mjs. No editar a mano: se regenera.
--
-- Idempotente: todo va con `on conflict ... do update` y las claves foráneas se
-- resuelven por slug, así que se puede volver a aplicar sobre una base que ya lo
-- tiene y sobre una base vacía, sin cambiar nada más.
--
-- Contenido: 56 fuentes · 4 anillos · 14 ramas ·
-- 105 gajos · 360 hojas · 491 conceptos ·
-- 527 prerrequisitos · 41 misconceptions ·
-- 44 plantillas autoradas · 108 ítems ensamblados.
--
-- DESPUÉS de aplicar esto hay que correr UNA vez:
--     select ac_sembrar_derivados();
-- Está en supabase/migrations/0079_academia_semilla.sql y es la que construye
-- los ítems derivados de CADA concepto. Sin ella solo tendrían ejercicios los
-- conceptos que toca una plantilla autorada, y la mayor parte del árbol quedaría
-- sin nada que servir.

-- ── Fuentes ────────────────────────────────────────────────────────────
insert into ac_fuentes (slug, titulo, organizacion, url, publicado, licencia, contenido) values
  ('iucn-red-list', 'IUCN Red List of Threatened Species', 'IUCN', 'https://www.iucnredlist.org/', '2025', 'Uso con atribución', 'Categorías de la Lista Roja: EX (Extinta), EW (Extinta en Estado Silvestre), CR (En Peligro Crítico), EN (En Peligro), VU (Vulnerable), NT (Casi Amenazada), LC (Preocupación Menor), DD (Datos Insuficientes), NE (No Evaluada). DD significa que no hay información suficiente para evaluar el riesgo: no significa que la especie esté bien.'),
  ('iucn-categorias', 'IUCN Red List Categories and Criteria, versión 3.1', 'IUCN', 'https://portals.iucn.org/library/sites/library/files/documents/RL-2001-001.pdf', '2001', 'Uso con atribución', 'Las categorías de amenaza son En Peligro Crítico, En Peligro y Vulnerable. Una especie puede estar categorizada de forma distinta a nivel global y a nivel nacional: la categorización nacional evalúa la población dentro del país.'),
  ('ipbes-global', 'IPBES Global Assessment on Biodiversity and Ecosystem Services', 'IPBES', 'https://www.ipbes.net/global-assessment', '2019', 'Uso con atribución', 'Alrededor de un millón de especies animales y vegetales están amenazadas de extinción. Los cinco impulsores directos del cambio en la naturaleza, ordenados por impacto: cambio de uso de la tierra y el mar, explotación directa de organismos, cambio climático, contaminación e invasión de especies exóticas.'),
  ('sib-apn', 'SIB — Sistema de Información de Biodiversidad', 'Administración de Parques Nacionales', 'https://sib.gob.ar/', '2025', 'Datos públicos', 'Registros de especies en las áreas protegidas nacionales argentinas, fichas de especie y distribución por área protegida.'),
  ('sarem-2019', 'Categorización de los mamíferos de Argentina según su riesgo de extinción', 'SAREM — Sociedad Argentina para el Estudio de los Mamíferos', 'https://www.scielo.org.ar/scielo.php?script=sci_arttext&pid=S0327-93832022000100657', '2019', 'Acceso abierto', 'La categorización 2019 evaluó 417 especies de mamíferos nativos: 98 quedaron amenazadas (7 En Peligro Crítico, 26 En Peligro, 65 Vulnerables), 40 Casi Amenazadas y 80 con Datos Insuficientes. El 92,7 % de las especies enfrenta al menos una amenaza. Amenazas ordenadas: pérdida y degradación del hábitat (cerca del 80 % de las especies), caza ilegal (26 %), atropellamientos en ruta (22 %) y depredación por perros (22 %), especies invasoras (15 %).'),
  ('aves-argentinas-amenazadas', 'Categorización de las aves de Argentina según su estado de conservación', 'Aves Argentinas / AOP', 'https://www.avesargentinas.org.ar/aves-amenazadas', '2024', 'Uso con atribución', 'Alrededor del 12 % de las aves silvestres de Argentina —113 especies— están amenazadas, frente a 80 especies en la década de 1990.'),
  ('cites', 'Convención sobre el Comercio Internacional de Especies Amenazadas (CITES)', 'CITES', 'https://cites.org/', '2025', 'Documento público', 'CITES regula el comercio internacional de especies mediante tres apéndices. El Apéndice I prohíbe el comercio internacional con fines comerciales; el Apéndice II lo permite bajo permiso; el Apéndice III lista especies protegidas por un país que pide cooperación a los demás.'),
  ('ramsar', 'Convención de Ramsar sobre los Humedales', 'Ramsar', 'https://www.ramsar.org/', '2025', 'Documento público', 'La Convención de Ramsar designa humedales de importancia internacional. La Reserva Ecológica Costanera Sur es sitio Ramsar urbano desde 2005.'),
  ('invasoras-mayds', 'Lista de especies exóticas invasoras de Argentina', 'Ministerio de Ambiente y Desarrollo Sostenible', 'https://www.argentina.gob.ar/ambiente/biodiversidad/exoticas-invasoras/lista', '2024', 'Datos públicos', 'Especies exóticas invasoras registradas en Argentina: castor canadiense, visón americano, ciervo colorado, jabalí europeo, ardilla de vientre rojo, estornino pinto, paloma doméstica, mejillón dorado, caracol gigante africano, mosquito tigre. Entre las plantas: ligustro, mora, acacia negra, rosa mosqueta, gleditsia y tamarisco.'),
  ('red-centros-rescate', 'Red Federal de Centros de Rescate y Rehabilitación de Fauna Silvestre', 'Ministerio de Ambiente y Desarrollo Sostenible', 'https://www.argentina.gob.ar/interior/ambiente/accion/fauna/red-centros-rescate', '2024', 'Documento público', 'La Red Federal articula los centros de rescate y rehabilitación de fauna silvestre del país. Ante un animal silvestre herido corresponde contactar a la autoridad de fauna, no intentar la crianza ni la rehabilitación por cuenta propia.'),
  ('crfs-ecoparque', 'Centro de Rescate de Fauna Silvestre del Ecoparque', 'Gobierno de la Ciudad de Buenos Aires', 'https://buenosaires.gob.ar/ecoparque/programas-de-conservacion/centro-de-rescate-de-fauna-silvestre-crfs', '2025', 'Documento público', 'El Centro de Rescate de Fauna Silvestre del Ecoparque recibe animales silvestres decomisados del tráfico, heridos o entregados voluntariamente, y trabaja en su rehabilitación y derivación.'),
  ('protocolo-fauna-cba', 'Qué hacer si encontrás fauna silvestre', 'Secretaría de Ambiente de Córdoba', 'https://ambiente.cba.gov.ar/que-debes-hacer-si-encontras-fauna-silvestre/', '2024', 'Documento público', 'Ante un animal silvestre herido: no manipularlo sin protección, no darle agua ni comida, colocarlo en una caja de cartón ventilada, oscura y silenciosa, no exhibirlo ni fotografiarlo de cerca, no intentar criarlo, y contactar a la autoridad de fauna. La mayoría de los pichones encontrados en el suelo son volantones que todavía reciben alimento de sus padres: corresponde dejarlos donde están o subirlos a una rama cercana.'),
  ('gcba-cinco-libertades', 'Las 5 libertades de nuestras mascotas', 'Gobierno de la Ciudad de Buenos Aires', 'https://buenosaires.gob.ar/las-5-libertades-de-nuestras-mascotas', '2024', 'Documento público', 'Las cinco libertades del bienestar animal: libre de hambre y sed; libre de incomodidad; libre de dolor, lesión y enfermedad; libre para expresar un comportamiento natural; libre de miedo y angustia.'),
  ('ecoparque-conservacion', 'Ecoparque Buenos Aires — programas de conservación', 'Gobierno de la Ciudad de Buenos Aires', 'https://buenosaires.gob.ar/gcaba_historico/ecoparque/conservacion', '2024', 'Documento público', 'El antiguo Zoológico de Buenos Aires fue transformado en Ecoparque, con programas de conservación, rescate, investigación y educación, y el traslado de animales a santuarios y centros de referencia.'),
  ('rewilding-argentina', 'Fundación Rewilding Argentina — quiénes somos', 'Fundación Rewilding Argentina', 'https://rewildingargentina.org/quienes-somos/', '2025', 'Uso con atribución', 'Proyectos de reintroducción de yaguareté, oso hormiguero, venado de las pampas, lobo gargantilla, pecarí de collar, guacamayo rojo, chuña de patas rojas, ocelote, muitú, tortuga yabotí, paca, ciervo de los pantanos, chinchillón anaranjado y coipo, en Iberá, El Impenetrable, Patagonia y Patagonia Azul. El guacamayo rojo estuvo extinto en Argentina durante más de 150 años y fue reintroducido en Iberá.'),
  ('aves-argentinas', 'Aves Argentinas / Asociación Ornitológica del Plata', 'Aves Argentinas', 'https://www.avesargentinas.org.ar/', '2025', 'Uso con atribución', 'Fundada en 1916, es una de las organizaciones de conservación más antiguas de América. Programas de aves amenazadas (macá tobiano, cardenal amarillo, loro pecho vinoso) y ciencia ciudadana a través de los Clubes de Observadores de Aves (COA), eBird Argentina y el Censo Neotropical de Aves Acuáticas.'),
  ('conicet-carpinchos', 'Carpinchos: científicos y científicas del CONICET reflexionan sobre Nordelta', 'CONICET', 'https://www.conicet.gov.ar/carpinchos-cientificos-y-cientificas-del-conicet-reflexionan-sobre-los-acontecimientos-de-nordelta/', '2021', 'Uso con atribución', 'El carpincho es un roedor herbívoro, social y no agresivo. En Nordelta el barrio se construyó sobre el humedal donde los carpinchos ya vivían: el conflicto es una cuestión de uso del suelo, no una invasión de la fauna.'),
  ('ecorregiones-pba', 'Ecorregiones de la Argentina', 'Ministerio de Ambiente de la Provincia de Buenos Aires', 'https://www.ambiente.gba.gob.ar/nativas/ecorregiones', '2024', 'Documento público', 'Argentina tiene 18 ecorregiones: 15 continentales más Islas del Atlántico Sur, Antártida y Mar Argentino. Entre las continentales: Selva Paranaense, Yungas, Chaco Húmedo, Chaco Seco, Esteros del Iberá, Delta e Islas del Paraná, Espinal, Pampa, Monte de Llanuras y Mesetas, Monte de Sierras y Bolsones, Estepa Patagónica, Bosque Patagónico, Altos Andes, Puna y Campos y Malezales.'),
  ('plantas-nativas', 'Guía de plantas nativas — cuál es tu ecorregión', 'Guía de Plantas Nativas', 'https://nativas.lanacion.com.ar/acerca/cual-es-tu-ecoregion', '2024', 'Uso con atribución', 'Flora nativa rioplatense: ceibo (Erythrina crista-galli, flor nacional), aliso de río (Tessaria integrifolia), sauce criollo (Salix humboldtiana), laurel blanco, curupí, timbó, ombú (Phytolacca dioica, que no es un árbol sino una hierba gigante), tipa, palo borracho (Ceiba speciosa) y algarrobo (Prosopis spp.).'),
  ('ley-bosques-26331', 'Ley 26.331 de Presupuestos Mínimos de Protección Ambiental de los Bosques Nativos', 'Congreso de la Nación Argentina', 'https://www.derecho.uba.ar/academica/derecho-abierto/archivos/Ley-26331.pdf', '2007', 'Norma pública', 'La ley obliga a cada provincia a realizar un Ordenamiento Territorial de Bosques Nativos con tres categorías: categoría I (rojo), sectores de muy alto valor de conservación que no deben transformarse; categoría II (amarillo), de valor medio, con uso sostenible; categoría III (verde), sectores que pueden transformarse. Crea el Fondo Nacional para el Enriquecimiento y la Conservación de los Bosques Nativos.'),
  ('reserva-costanera-sur', 'Reserva Ecológica Costanera Sur', 'Gobierno de la Ciudad de Buenos Aires', 'https://buenosaires.gob.ar/gcaba_historico/vicejefatura/ambiente/reservasecologicas/reserva-ecologica-costanera-sur', '2024', 'Documento público', 'La Reserva Ecológica Costanera Sur ocupa unas 350 hectáreas sobre un relleno hecho con escombros de demoliciones en los años setenta. Los ecosistemas se regeneraron espontáneamente durante décadas de abandono; está protegida desde 1986 y es sitio Ramsar desde 2005. Registra 343 especies de aves, alrededor de un tercio de la avifauna argentina, además de 10 mamíferos y 23 reptiles, incluido el lagarto overo.'),
  ('acumar', 'ACUMAR — Autoridad de Cuenca Matanza Riachuelo', 'ACUMAR', 'https://www.acumar.gob.ar/', '2025', 'Datos públicos', 'ACUMAR es el organismo tripartito (Nación, Provincia de Buenos Aires y Ciudad de Buenos Aires) creado tras el fallo Mendoza de la Corte Suprema en 2008 para el saneamiento de la Cuenca Matanza-Riachuelo, donde viven alrededor de dos millones de personas.'),
  ('acuifero-puelche', 'Hidrogeología de la Ciudad de Buenos Aires', 'Universidad Nacional de La Plata (Auge)', 'https://www.bfa.fcnym.unlp.edu.ar/catalogo/doc_num.php?explnum_id=237', '2004', 'Acceso abierto', 'El acuífero Puelche es la principal reserva de agua subterránea del noreste bonaerense, ubicado bajo el acuífero Pampeano, del que recibe su recarga. Su vulnerabilidad depende de la protección que le da el sedimento superior.'),
  ('nitratos-puelche', 'Contaminación del agua subterránea con nitratos en la provincia de Buenos Aires', 'Fundación Enlaces', 'https://fundacion-enlaces.org/contaminacion-del-agua-subterranea-con-nitratos-en-la-provincia-de-buenos-aires-argentina/', '2023', 'Uso con atribución', 'La contaminación por nitratos del agua subterránea bonaerense se asocia a pozos ciegos, efluentes y fertilizantes. Es una de las causas principales por las que el agua de pozo deja de ser apta para consumo.'),
  ('huella-hidrica', 'Qué es y cómo se mide la huella hídrica', 'Water Footprint Network', 'https://www.waterfootprint.org/', '2024', 'Uso con atribución', 'La huella hídrica se divide en verde (agua de lluvia almacenada en el suelo y consumida por los cultivos), azul (agua superficial y subterránea consumida) y gris (agua necesaria para diluir la contaminación generada). El agua virtual es el agua utilizada para producir un bien, incorporada en él aunque no se vea. Producir un kilo de carne vacuna requiere del orden de 15.000 litros de agua contando toda la cadena; una remera de algodón, alrededor de 2.700 litros.'),
  ('ipcc-ar6', 'IPCC Sixth Assessment Report (AR6)', 'IPCC', 'https://www.ipcc.ch/assessment-report/ar6/', '2021-2023', 'Uso con atribución', 'El efecto invernadero natural mantiene la Tierra habitable; el problema es su intensificación por el aumento de gases de efecto invernadero de origen humano. Los principales son dióxido de carbono, metano, óxido nitroso y gases fluorados. El metano tiene un potencial de calentamiento global mucho mayor que el CO₂ en un horizonte de 100 años, pero permanece menos tiempo en la atmósfera. Una fracción importante del CO₂ emitido permanece en la atmósfera durante siglos.'),
  ('iea-energia', 'IEA — Energy and AI', 'International Energy Agency', 'https://www.iea.org/reports/energy-and-ai/executive-summary', '2025', 'Uso con atribución', 'La IEA proyecta que la demanda eléctrica de los centros de datos se duplique hacia 2030, hasta alrededor de 945 TWh, algo menos del 3 % de la electricidad mundial.'),
  ('carbon-brief', 'Carbon Brief — explicadores y verificación', 'Carbon Brief', 'https://www.carbonbrief.org/', '2025', 'Uso con atribución', 'La huella digital individual está dominada por la fabricación de los dispositivos y por la electricidad de los centros de datos, no por el envío de correos electrónicos. Alargar la vida útil de un teléfono dos años más pesa mucho más que cualquier higiene de correo.'),
  ('icct-ev', 'Life-cycle greenhouse gas emissions of passenger cars', 'ICCT — International Council on Clean Transportation', 'https://theicct.org/wp-content/uploads/2025/07/ID-392-%E2%80%93-Life-cycle-GHG_report_final.pdf', '2025', 'Uso con atribución', 'Los autos eléctricos no tienen emisiones por el caño de escape, pero sí emisiones de ciclo de vida por la fabricación de la batería y por la electricidad de la red. Considerando todo el ciclo de vida emiten sustancialmente menos que un auto de combustión comparable en prácticamente todas las redes eléctricas estudiadas.'),
  ('epa', 'US EPA — explicadores ambientales', 'US Environmental Protection Agency', 'https://www.epa.gov/', '2025', 'Documento público', 'La jerarquía de gestión de residuos ordena las opciones de mayor a menor preferencia: prevención y reducción en origen, reutilización, reciclado y compostaje, recuperación de energía y, por último, tratamiento y disposición final.'),
  ('incendios-delta-2020', 'Incendios en el delta del río Paraná de 2020', 'Registro público (Wikipedia, con fuentes citadas)', 'https://es.wikipedia.org/wiki/Incendios_en_el_delta_del_r%C3%ADo_Paran%C3%A1_de_2020', '2020', 'CC BY-SA', 'Los incendios del delta del Paraná de 2020 arrasaron cientos de miles de hectáreas de humedal y llevaron humo a Rosario y al AMBA. Se convirtieron en el principal impulso político del proyecto de Ley de Humedales, que sigue sin sancionarse.'),
  ('ley-1854-basura-cero', 'Ley 1854 de Gestión Integral de Residuos Sólidos Urbanos (Basura Cero)', 'Legislatura de la Ciudad de Buenos Aires', 'http://www2.cedom.gov.ar/es/legislacion/normas/leyes/ley1854.html', '2005', 'Norma pública', 'La ley Basura Cero establece metas progresivas de reducción del enterramiento de residuos en la Ciudad de Buenos Aires y la separación en origen entre reciclables y no reciclables, con Puntos Verdes, campanas verdes y Centros Verdes operados por cooperativas de recuperadores urbanos.'),
  ('faccyr', 'FACCyR — Federación Argentina de Cartoneros, Carreros y Recicladores', 'FACCyR', 'https://faccyr.org.ar/legislacion/', '2024', 'Uso con atribución', 'Los recuperadores urbanos organizados en cooperativas son parte del sistema formal de reciclado de la Ciudad de Buenos Aires y operan los Centros Verdes. Los proyectos de Ley de Envases con Responsabilidad Extendida del Productor incluyen la inclusión social de recuperadores.'),
  ('rep-envases', 'Ley de Envases y Responsabilidad Extendida del Productor', 'Fundación Metropolitana', 'https://metropolitana.org.ar/idm/ley-de-envases-y-responsabilidad-extendida-del-productor/', '2024', 'Uso con atribución', 'La Responsabilidad Extendida del Productor traslada al fabricante el costo de la gestión del envase una vez terminada su vida útil. El proyecto argentino de Ley de Envases fue presentado en repetidas oportunidades y nunca sancionado.'),
  ('ellen-macarthur', 'Circular economy introduction', 'Ellen MacArthur Foundation', 'https://www.ellenmacarthurfoundation.org/topics/circular-economy-introduction/overview', '2024', 'Uso con atribución', 'La economía circular se apoya en tres principios: eliminar los residuos y la contaminación desde el diseño, mantener los productos y materiales en uso en su mayor valor posible, y regenerar la naturaleza. Distingue ciclos técnicos (materiales que se recuperan) de ciclos biológicos (materiales que vuelven al suelo).'),
  ('global-footprint', 'Ecological Footprint y Earth Overshoot Day', 'Global Footprint Network', 'https://www.footprintnetwork.org/', '2025', 'Uso con atribución', 'El Día de Sobregiro de la Tierra marca la fecha en la que la humanidad consumió todos los recursos que los ecosistemas pueden regenerar en un año. A partir de esa fecha el consumo del año se sostiene sobre stock, no sobre renovación.'),
  ('yale-reciclaje', 'Recycling isn’t the solution to the climate crisis', 'Yale Climate Connections', 'https://yaleclimateconnections.org/2024/09/recycling-isnt-the-solution-to-the-climate-crisis/', '2024', 'Uso con atribución', 'El reciclado es la tercera opción, después de evitar y de reducir. La mayor parte del plástico producido en la historia nunca fue reciclada, y el plástico pierde calidad en cada ciclo de reciclado, por lo que la reducción y el rediseño pesan más que el reciclado.'),
  ('owid-alimentos', 'You want to reduce the carbon footprint of your food? Focus on what you eat, not whether it is local', 'Our World in Data', 'https://ourworldindata.org/food-choice-vs-eating-local', '2024', 'CC BY', 'El transporte representa una fracción pequeña de las emisiones de la mayoría de los alimentos. Qué se come pesa mucho más que la distancia que recorrió. La carne vacuna genera del orden de 27 kg de CO₂ equivalente por kilo producido; las legumbres, cerca de 0,9 kg por kilo.'),
  ('owid-impactos-alimentos', 'Environmental impacts of food production', 'Our World in Data', 'https://ourworldindata.org/environmental-impacts-of-food', '2024', 'CC BY', 'La producción de alimentos ocupa cerca de la mitad de la tierra habitable del planeta y es responsable de alrededor de un cuarto de las emisiones globales de gases de efecto invernadero. Alrededor de un tercio de los alimentos producidos en el mundo se pierde o se desperdicia.'),
  ('fao', 'FAO / FAOSTAT', 'FAO — Organización de las Naciones Unidas para la Alimentación y la Agricultura', 'https://www.fao.org/faostat/', '2025', 'Datos públicos', 'Datos de alimentación, uso de la tierra, pesca (informe SOFIA) y bosques (evaluación FRA) por país y por producto.')
on conflict (slug) do update set titulo = excluded.titulo, organizacion = excluded.organizacion, url = excluded.url,
  publicado = excluded.publicado, licencia = excluded.licencia, contenido = excluded.contenido;
insert into ac_fuentes (slug, titulo, organizacion, url, publicado, licencia, contenido) values
  ('inta', 'INTA — Instituto Nacional de Tecnología Agropecuaria', 'INTA', 'https://www.argentina.gob.ar/inta', '2025', 'Documento público', 'El INTA publica calendarios estacionales de frutas y verduras, materiales de agroecología, suelos y el programa ProHuerta de huertas familiares, escolares y comunitarias.'),
  ('milla-201', 'La pesca ilegal en la milla 201 del Mar Argentino', 'Chequeado', 'https://chequeado.com/el-explicador/la-pesca-ilegal-en-la-milla-201-del-mar-argentino-perdidas-millonarias-e-impacto-en-los-recursos-argentinos/', '2023', 'Uso con atribución', 'Frente al límite de la Zona Económica Exclusiva argentina, en la llamada milla 201, opera una flota internacional de pesca de altura sobre recursos que migran desde aguas argentinas. El área conocida como Agujero Azul concentra buena parte de esa actividad.'),
  ('unep', 'UNEP — Programa de las Naciones Unidas para el Medio Ambiente', 'UNEP', 'https://www.unep.org/', '2025', 'Uso con atribución', 'La gran mayoría de la basura marina se origina en tierra y llega al mar a través de ríos, desagües y viento. Los cinco impulsores de la crisis de la naturaleza son el cambio de uso de la tierra y el mar, la explotación directa, el cambio climático, la contaminación y las especies invasoras.'),
  ('ley-27621-eai', 'Ley 27.621 de Educación Ambiental Integral', 'Congreso de la Nación Argentina', 'https://www.argentina.gob.ar/normativa/nacional/ley-27621-350594/texto', '2021', 'Norma pública', 'La ley establece la educación ambiental integral como obligatoria y transversal en todos los niveles y crea la Estrategia Nacional de Educación Ambiental Integral. Sus principios incluyen el abordaje holístico, el respeto y valor de la biodiversidad, la equidad, la perspectiva de género, el respeto por la diversidad cultural y los saberes de los pueblos indígenas, la participación ciudadana, la perspectiva histórica, la educación en valores y el derecho a un ambiente sano.'),
  ('ley-22421-fauna', 'Ley 22.421 de Conservación de la Fauna Silvestre', 'Congreso de la Nación Argentina', 'https://www.argentina.gob.ar/normativa', '1981', 'Norma pública', 'La ley declara de interés público la fauna silvestre y su protección, y regula la caza, el transporte, el comercio y la exportación. Es la base de la fiscalización contra el tráfico de fauna, complementada por la Ley 14.346 de maltrato animal, de 1954.'),
  ('ley-25675-ambiente', 'Ley 25.675 General del Ambiente', 'Congreso de la Nación Argentina', 'https://www.argentina.gob.ar/normativa', '2002', 'Norma pública', 'Ley marco de presupuestos mínimos. Establece los principios de congruencia, prevención, precautorio, equidad intergeneracional, progresividad, responsabilidad, subsidiariedad, sustentabilidad, solidaridad y cooperación, además de la evaluación de impacto ambiental y el seguro ambiental.'),
  ('ley-25831-info', 'Ley 25.831 de Régimen de Libre Acceso a la Información Pública Ambiental', 'Congreso de la Nación Argentina', 'https://www.argentina.gob.ar/normativa', '2003', 'Norma pública', 'Garantiza el derecho de acceso a la información ambiental que esté en poder del Estado. El acceso es libre y gratuito, y no hace falta acreditar razones ni interés determinado para pedirla.'),
  ('escazu', 'Acuerdo de Escazú (Ley 27.566)', 'Congreso de la Nación Argentina / CEPAL', 'https://www.argentina.gob.ar/normativa', '2020', 'Norma pública', 'El Acuerdo de Escazú garantiza los derechos de acceso a la información ambiental, la participación pública en las decisiones ambientales y el acceso a la justicia ambiental, e incluye obligaciones de protección para las personas defensoras de derechos humanos en asuntos ambientales.'),
  ('unesco-ods', 'Education for Sustainable Development Goals: Learning Objectives', 'UNESCO', 'https://unesdoc.unesco.org/ark:/48223/pf0000247444', '2017', 'CC BY-SA', 'UNESCO define, para cada Objetivo de Desarrollo Sostenible, objetivos de aprendizaje cognitivos, socioemocionales y conductuales, y ocho competencias transversales: pensamiento sistémico, anticipatorio, normativo, estratégico, colaboración, pensamiento crítico, autoconciencia y resolución integrada de problemas.'),
  ('naaee-guidelines', 'K–12 Environmental Education: Guidelines for Excellence', 'NAAEE', 'https://naaee.org/programs/guidelines-excellence', '2019', 'Uso con atribución', 'Cuatro ejes: habilidades de indagación, análisis e interpretación; procesos y sistemas ambientales; habilidades para comprender y abordar problemas ambientales; y responsabilidad personal y cívica, que incluye el reconocimiento de la propia eficacia y capacidad de acción.'),
  ('gbif', 'GBIF — Global Biodiversity Information Facility', 'GBIF', 'https://www.gbif.org/', '2025', 'CC BY', 'GBIF agrega registros georreferenciados de presencia de especies publicados con el estándar Darwin Core, que define los campos mínimos de un registro: qué se observó, dónde, cuándo y quién lo registró.'),
  ('argentinat', 'ArgentiNat — iNaturalist Argentina', 'ArgentiNat / iNaturalist', 'https://www.argentinat.org/', '2025', 'CC BY-NC', 'ArgentiNat permite registrar observaciones de especies con foto y ubicación; las identificaciones son verificadas por la comunidad y los registros de calidad investigativa se publican en GBIF.'),
  ('ebird', 'eBird Argentina', 'Cornell Lab of Ornithology / Aves Argentinas', 'https://ebird.org/region/AR', '2025', 'Uso con atribución', 'eBird recopila listados de aves con fecha, lugar y esfuerzo de observación. La Reserva Ecológica Costanera Sur es uno de los hotspots más registrados de la Argentina.'),
  ('chequeado', 'Chequeado — verificación de datos', 'Chequeado', 'https://chequeado.com/', '2025', 'Uso con atribución', 'Chequeado verifica afirmaciones públicas en Argentina, incluidas las ambientales, y publica el método y las fuentes de cada verificación.'),
  ('ecoansiedad-review', 'Eco-anxiety in children: a scoping review', 'Frontiers in Psychology', 'https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2022.872544/full', '2022', 'CC BY', 'La preocupación y la ansiedad son las emociones más reportadas en la infancia frente a la crisis ambiental, junto con el miedo y también la esperanza. Los adolescentes muestran más pesimismo que los niños. Son factores protectores la agencia, el afrontamiento centrado en el sentido, la esperanza y la participación en la acción colectiva. Se recomienda acompañar cada contenido sobre problemas con soluciones accionables y enfatizar la responsabilidad colectiva por sobre la individual.'),
  ('ncse-ozono', 'Misconception Monday: the ozone hole', 'National Center for Science Education', 'https://ncse.ngo/misconception-monday-oh-no-ozone-hole', '2016', 'Uso con atribución', 'El agotamiento de la capa de ozono y el calentamiento global son dos problemas distintos. El primero se debe a los CFC, ocurre en la estratósfera y afecta la radiación ultravioleta que llega a la superficie; el segundo se debe a los gases de efecto invernadero, ocurre en la tropósfera y atrapa calor. Es la confusión más persistente de la enseñanza de temas ambientales.')
on conflict (slug) do update set titulo = excluded.titulo, organizacion = excluded.organizacion, url = excluded.url,
  publicado = excluded.publicado, licencia = excluded.licencia, contenido = excluded.contenido;

-- ── Anillos ────────────────────────────────────────────────────────────
insert into ac_anillos (n, nombre_es, descripcion_es, rubrica) values
  (1, 'Reconocer', 'Nombrar las cosas y saber cuáles son. El primer anillo del tronco.', 'Nivel cognitivo: reconocer e identificar. El ítem pide nombrar, distinguir o clasificar algo concreto y observable. Una sola idea por ítem. Sin cadenas causales de más de un paso. Vocabulario cotidiano.'),
  (2, 'Explicar', 'Por qué pasa lo que pasa, y qué se relaciona con qué.', 'Nivel cognitivo: explicar y relacionar. El ítem pide una causa, un mecanismo o una relación entre dos cosas. Se admiten cadenas causales de dos o tres pasos. Se puede pedir comparar dos casos.'),
  (3, 'Decidir', 'Comparar opciones reales con números reales y elegir.', 'Nivel cognitivo: comparar y decidir. El ítem presenta dos o más opciones legítimas con costos y beneficios distintos y pide elegir con un criterio explícito. Los números son reales y llevan su fuente. Nunca hay una única opción obviamente buena.'),
  (4, 'Sistemas', 'Efectos de segundo orden, compensaciones y consecuencias no buscadas.', 'Nivel cognitivo: sistemas y compensaciones. El ítem trabaja efectos de segundo orden, rebotes, externalidades o conflictos entre objetivos legítimos. Se admite que la respuesta correcta sea "depende de X" cuando X está explicitado.')
on conflict (n) do update set nombre_es = excluded.nombre_es, descripcion_es = excluded.descripcion_es, rubrica = excluded.rubrica;

