  ('energia', false, 'Energía y CO₂', 'De dónde sale la luz que usás y cuánto pesa cada kilovatio.', 3),
  ('movilidad', false, 'Movilidad', 'Cómo te movés, cuánto cuesta cada kilómetro y quién más viaja con vos.', 4),
  ('plantas', false, 'Plantas y Verde Urbano', 'Nativas, exóticas e invasoras, y lo que un árbol hace por una cuadra.', 5),
  ('animales', false, 'Animales y Vida Silvestre', 'La rama más profunda del bosque: quiénes son, cómo se sostienen y cómo se cuidan.', 6),
  ('alimentacion', false, 'Alimentación', 'Lo que comés pesa más que la distancia que recorrió.', 7),
