  ('digital', false, 'Digital y Tecnología', 'La nube es física, y tu celular pesa más de lo que parece.', 9),
  ('comunidad', false, 'Comunidad', 'Lo que se decide entre varios: reclamos, audiencias y derechos ambientales.', 10),
  ('agua_azul', false, 'Océanos y Ríos', 'El Mar Argentino, el Río de la Plata y todo lo que llega desde tierra.', 11),
  ('aire_suelo', false, 'Aire y Suelo', 'Lo que respirás y lo que pisás, que son dos sistemas y no uno.', 12),
  ('ciencia', false, 'Ciencia Ciudadana', 'Cómo se sabe lo que se sabe, y cómo sumar tus propios datos.', 13)
on conflict (slug) do update set es_tronco = excluded.es_tronco, nombre_es = excluded.nombre_es,
