  ('digital.consumir-tecnologia', 'digital', 2, 'Consumir tecnología', 'Comprar menos, elegir mejor y reclamar que dure.', 'ShoppingBag', '{"teen","adult"}'::text[], 6, 'aprobado', 'semilla'),
  ('digital.medir-lo-digital', 'digital', 2, 'Medir lo digital', 'Cómo se calcula una huella que no se ve.', 'Gauge', '{"teen","adult"}'::text[], 7, 'aprobado', 'semilla'),
  ('energia.kwh-y-factura', 'energia', 1, 'Lo que mide la boleta', 'Qué es un kWh, qué dice la factura de luz y qué consume de verdad tu casa.', 'Zap', '{"kid","teen","adult"}'::text[], 1, 'aprobado', 'semilla'),
  ('energia.la-casa-que-abriga', 'energia', 1, 'La casa que abriga', 'Antes de cambiar el equipo, tapar por dónde se escapa el calor.', 'Thermometer', '{"kid","teen","adult"}'::text[], 2, 'aprobado', 'semilla'),
  ('energia.elegir-sin-adivinar', 'energia', 1, 'Elegir sin adivinar', 'La etiqueta A–G, la cuenta de servilleta y la trampa del rebote.', 'Tag', '{"kid","teen","adult"}'::text[], 3, 'aprobado', 'semilla'),
  ('energia.de-donde-sale-la-luz', 'energia', 1, 'De dónde sale la luz', 'La mezcla que hay detrás del enchufe argentino, y qué emite cada kWh.', 'PlugZap', '{"kid","teen","adult"}'::text[], 4, 'aprobado', 'semilla'),
  ('energia.la-red-que-respira', 'energia', 2, 'La red que respira', 'La demanda sube y baja todo el día: ahí se juega el partido de las renovables.', 'Activity', '{"teen","adult"}'::text[], 5, 'aprobado', 'semilla'),
  ('energia.el-gas-y-sus-debates', 'energia', 2, 'El gas y sus debates', 'La fuente que sostiene la matriz argentina, con sus discusiones abiertas.', 'Flame', '{"teen","adult"}'::text[], 6, 'aprobado', 'semilla'),
  ('energia.contar-el-carbono', 'energia', 2, 'Contar el carbono', 'Cómo se mide una huella de energía y qué hacés después con el número.', 'Gauge', '{"teen","adult"}'::text[], 7, 'aprobado', 'semilla'),
  ('movilidad.la-piramide', 'movilidad', 1, 'La pirámide de la movilidad', 'Quién va primero cuando se reparte una calle.', 'Footprints', '{"kid","teen","adult"}'::text[], 1, 'aprobado', 'semilla'),
  ('movilidad.aire-que-respiramos', 'movilidad', 1, 'El aire que respiramos', 'Lo que sale del tránsito y no se ve.', 'Wind', '{"kid","teen","adult"}'::text[], 2, 'aprobado', 'semilla'),
  ('movilidad.ciudad-que-se-camina', 'movilidad', 1, 'La ciudad que se camina', 'Cómo está hecha una calle en la que cualquiera puede cruzar.', 'TrafficCone', '{"kid","teen","adult"}'::text[], 3, 'aprobado', 'semilla'),
  ('movilidad.ir-todos-juntos', 'movilidad', 1, 'Ir todos juntos', 'Colectivo, tren y subte: el sistema que sostiene el AMBA.', 'Bus', '{"kid","teen","adult"}'::text[], 4, 'aprobado', 'semilla'),
  ('movilidad.autos-y-corriente', 'movilidad', 2, 'Autos, baterías y corriente', 'Qué cambia y qué no cuando el auto se enchufa.', 'BatteryCharging', '{"kid","teen","adult"}'::text[], 5, 'aprobado', 'semilla'),
  ('movilidad.mas-asfalto-mas-autos', 'movilidad', 2, 'Más asfalto, más autos', 'Por qué ensanchar la avenida no destraba nada.', 'Route', '{"teen","adult"}'::text[], 6, 'aprobado', 'semilla'),
  ('movilidad.vuelos-y-envios', 'movilidad', 2, 'Vuelos y envíos', 'Lo que viaja lejos: aviones, paquetes y la cuenta que no se ve.', 'Plane', '{"teen","adult"}'::text[], 7, 'aprobado', 'semilla'),
  ('plantas.como-vive-una-planta', 'plantas', 1, 'Cómo vive una planta', 'Se hace su propia comida con luz y aire, y abajo tiene socios.', 'Leaf', '{"kid","teen","adult"}'::text[], 1, 'aprobado', 'semilla'),
  ('plantas.nativas-y-exoticas', 'plantas', 1, 'Nativas, exóticas e invasoras', 'De acá, de allá, y las que se van de mambo.', 'Flower2', '{"kid","teen","adult"}'::text[], 2, 'aprobado', 'semilla'),
  ('plantas.el-arbol-de-tu-cuadra', 'plantas', 1, 'El árbol de tu cuadra', 'Sombra, lluvia y unos grados menos: lo que hace mientras no lo mirás.', 'Trees', '{"kid","teen","adult"}'::text[], 3, 'aprobado', 'semilla'),
  ('plantas.huerta-y-semillas', 'plantas', 1, 'Huerta y semillas', 'Un cajón, sol unas horas, y tierra que vuelve a ser tierra.', 'Carrot', '{"kid","teen","adult"}'::text[], 4, 'aprobado', 'semilla'),
  ('plantas.pastizal-y-monte', 'plantas', 2, 'Pastizal y monte', 'Los ecosistemas de acá, los que casi nadie llama ecosistemas.', 'Wheat', '{"kid","teen","adult"}'::text[], 5, 'aprobado', 'semilla'),
  ('plantas.invasoras-y-restauracion', 'plantas', 2, 'Invasoras y restauración', 'Las tres que ya conocés de vista, y qué se hace después de sacarlas.', 'Sprout', '{"kid","teen","adult"}'::text[], 6, 'aprobado', 'semilla'),
  ('plantas.bosques-y-ley', 'plantas', 2, 'Bosques y ley', 'Qué dice la Ley de Bosques, qué es el OTBN y de qué color es tu parcela.', 'Scale', '{"teen","adult"}'::text[], 7, 'aprobado', 'semilla'),
  ('residuos.separar-en-origen', 'residuos', 1, 'Separar en origen', 'Lo que decidís en la cocina define si el material se recicla o no.', 'Trash2', '{"kid","teen","adult"}'::text[], 1, 'aprobado', 'semilla'),
  ('residuos.la-escalera', 'residuos', 1, 'La escalera de decisiones', 'Reciclar está en el medio de la lista. Arriba hay cosas que rinden más.', 'ListOrdered', '{"kid","teen","adult"}'::text[], 2, 'aprobado', 'semilla'),
  ('residuos.compost-en-casa', 'residuos', 1, 'Compost en casa', 'Cáscaras, yerba y hojas secas pueden volver a ser tierra en tu balcón.', 'Sprout', '{"kid","teen","adult"}'::text[], 3, 'aprobado', 'semilla'),
  ('residuos.a-donde-va', 'residuos', 1, 'A dónde va lo que tirás', 'El camión, el relleno, el líquido, el gas y el río.', 'Truck', '{"kid","teen","adult"}'::text[], 4, 'aprobado', 'semilla'),
  ('residuos.los-plasticos', 'residuos', 2, 'Los plásticos por dentro', 'Los numeritos, las capas y las palabras que prometen de más.', 'Package', '{"kid","teen","adult"}'::text[], 5, 'aprobado', 'semilla'),
  ('residuos.quien-recicla', 'residuos', 2, 'Quién recicla en serio', 'Cartoneros, cooperativas y las reglas que deciden quién paga.', 'Users', '{"kid","teen","adult"}'::text[], 6, 'aprobado', 'semilla'),
  ('residuos.circular', 'residuos', 2, 'De lineal a circular', 'Que el material vuelva a entrar en vez de terminar enterrado.', 'Recycle', '{"kid","teen","adult"}'::text[], 7, 'aprobado', 'semilla')
