insert into ac_gajos (slug, rama_slug, anillo, titulo_es, bajada_es, icono, age_groups, sort_order, status, origen) values
  ('tronco.sistemas-vivos', 'tronco', 1, 'Sistemas vivos', 'Nada está solo: todo lo que vive está enganchado con otra cosa.', 'Sprout', '{"kid","teen","adult"}'::text[], 1, 'aprobado', 'semilla'),
  ('tronco.leer-numeros', 'tronco', 1, 'Leer un número ambiental', 'Un número sin unidad y sin fuente no dice nada. Con las dos, dice todo.', 'Ruler', '{"kid","teen","adult"}'::text[], 2, 'aprobado', 'semilla'),
  ('tronco.como-se-sabe', 'tronco', 1, 'Cómo se sabe lo que se sabe', 'Observar, medir, dudar y volver a medir. También sirve para el WhatsApp familiar.', 'Microscope', '{"kid","teen","adult"}'::text[], 3, 'aprobado', 'semilla'),
  ('tronco.donde-pesa', 'tronco', 2, 'Dónde pesa tu acción', 'Qué mueve la aguja de verdad, y dónde deja de moverla.', 'Scale', '{"kid","teen","adult"}'::text[], 4, 'aprobado', 'semilla'),
  ('tronco.reglas-del-juego', 'tronco', 2, 'Las reglas del juego', 'Quién decide, con qué ley y dónde entrás vos.', 'Landmark', '{"kid","teen","adult"}'::text[], 5, 'aprobado', 'semilla')
