-- ── Conceptos ──────────────────────────────────────────────────────────
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('agua.ciclo_agua', 'agua', 'El agua da vueltas', 'El agua no se gasta ni se fabrica: se evapora, forma nubes, llueve, corre y vuelve a empezar. Siempre es la misma agua cambiando de lugar.', 'El agua que tomás hoy ya pasó por un río, por una nube y por otros seres vivos muchísimas veces antes.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.dulce_es_poca', 'agua', 'Casi toda el agua es salada', 'La mayor parte del agua del planeta es salada, y del poco de agua dulce que hay, buena parte está congelada o guardada bajo tierra.', 'El agua dulce fácil de usar —ríos, lagos, napas accesibles— es una porción chica del total.', (select id from ac_fuentes where slug = 'unep'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.cuenca_hidrografica', 'agua', 'Qué es una cuenca', 'Una cuenca es todo el territorio cuya lluvia termina drenando al mismo río, y por eso el agua se gestiona por cuenca y no por barrio ni por provincia.', 'La cuenca no respeta los límites del mapa político: eso es justamente lo que la vuelve difícil de gobernar.', (select id from ac_fuentes where slug = 'acumar'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.cuenca_matanza_riachuelo', 'agua', 'La cuenca donde vivís', 'La cuenca Matanza-Riachuelo atraviesa la Ciudad de Buenos Aires y varios municipios del conurbano, así que su saneamiento lo coordina un organismo interjurisdiccional: ACUMAR.', 'Nación, Provincia y Ciudad comparten la misma agua, y por eso tuvieron que sentarse en la misma mesa.', (select id from ac_fuentes where slug = 'acumar'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.rejilla_llega_al_rio', 'agua', 'La rejilla de la esquina es el río', 'Lo que queda en la calle —basura, aceite, restos de lavado— entra por la rejilla al desagüe pluvial y sale sin tratamiento en un arroyo o en el río.', 'El desagüe de lluvia y la cloaca son dos redes distintas: solo una termina en una planta de tratamiento.', (select id from ac_fuentes where slug = 'acumar'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.rio_de_la_plata_fuente', 'agua', 'El río que te da de tomar', 'La mayor parte del agua potable del AMBA se toma del Río de la Plata, se potabiliza en grandes plantas y viaja por la red hasta las casas.', 'La planta General San Martín, en Palermo, es una de las que abastecen a la Ciudad y al conurbano.', (select id from ac_fuentes where slug = 'acuifero-puelche'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.potabilizacion', 'agua', 'Cómo se limpia el agua', 'Potabilizar es una secuencia: coagulación y floculación para que la suciedad se junte en grumos, sedimentación para que caiga, filtración para lo que quedó y cloración para desinfectar.', 'Cada paso saca algo distinto; ninguno alcanza solo.', (select id from ac_fuentes where slug = 'epa'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.cloro_residual', 'agua', 'El gustito a cloro', 'Queda un resto de cloro en el agua a propósito: es lo que la mantiene desinfectada durante todo el viaje por los caños hasta tu canilla.', 'Si el sabor te molesta, dejá la jarra tapada un rato en la heladera y se va solo.', (select id from ac_fuentes where slug = 'epa'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.agua_de_red_controlada', 'agua', 'El agua de red se controla', 'El agua de red se trata y se analiza de forma periódica, y esos resultados son información pública que cualquiera puede consultar.', 'La diferencia con una botella no es la confianza que da el envase: es que acá hay un control que se puede leer.', (select id from ac_fuentes where slug = 'acumar'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.perdidas_y_medicion', 'agua', 'El agua que se pierde en el camino', 'Una parte del agua potabilizada nunca llega a una canilla: se pierde en fugas de la red y en las instalaciones de cada casa, y sin medición es difícil saber dónde.', 'Un tanque que rebalsa y una canilla que gotea entran en la misma cuenta que un caño roto en la calle.', (select id from ac_fuentes where slug = 'acuifero-puelche'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.napa_freatica', 'agua', 'La napa que está más arriba', 'Debajo del suelo hay agua guardada entre los granos de arena: la primera capa, la freática, es la más cercana a la superficie y la más fácil de contaminar.', 'No es un río subterráneo ni una laguna: es agua ocupando los huecos del sedimento.', (select id from ac_fuentes where slug = 'acuifero-puelche'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.acuifero_puelche', 'agua', 'El Puelche', 'El Puelche es el acuífero más usado del norte bonaerense: está más profundo que la freática y lo separa de ella una capa de arcilla que lo protege en parte.', 'Ese techo de arcilla es la razón por la que el Puelche aguantó tanto, y también la razón por la que un pozo mal hecho lo pone en riesgo.', (select id from ac_fuentes where slug = 'acuifero-puelche'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.sobreexplotacion', 'agua', 'Sacar más rápido de lo que entra', 'Un acuífero se recarga con la lluvia que se infiltra; si se extrae más rápido que esa recarga, el nivel baja y puede entrar agua salada o contaminada en su lugar.', null, (select id from ac_fuentes where slug = 'acuifero-puelche'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.nitratos_napas', 'agua', 'Nitratos donde no se ven', 'Los nitratos que llegan de fertilizantes, pozos ciegos y efluentes se disuelven en el agua subterránea sin cambiarle el color, el olor ni el sabor: solo un análisis los detecta.', 'Que el agua de un pozo se vea limpia dice poco: eso es observación, y acá hace falta medición.', (select id from ac_fuentes where slug = 'nitratos-puelche'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua.pozo_ciego_y_pozo_de_agua', 'agua', 'El pozo ciego y el pozo de agua', 'En los barrios sin cloacas conviven dos pozos en el mismo terreno: uno entrega el agua y el otro recibe los desechos, y cuando están cerca la freática pasa de uno al otro.', 'Por eso la llegada de la red de agua y cloaca a un barrio es una medida de salud, no solo de comodidad.', (select id from ac_fuentes where slug = 'nitratos-puelche'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua.agua_virtual', 'agua', 'El agua virtual', 'La mayor parte del agua que consumís no sale de tu canilla: se usó para producir lo que comés, lo que vestís y lo que comprás.', 'Es agua que ya se gastó antes de que el producto llegue a tu casa.', (select id from ac_fuentes where slug = 'huella-hidrica'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.huella_hidrica', 'agua', 'La huella hídrica', 'La huella hídrica de un producto es toda el agua que hizo falta para producirlo, sumada a lo largo de la cadena entera y no solo en el último paso.', null, (select id from ac_fuentes where slug = 'huella-hidrica'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.huella_verde_azul_gris', 'agua', 'Verde, azul y gris', 'La huella hídrica se separa en tres: verde es la lluvia que aprovecha el cultivo, azul es el agua de río o de napa que se extrae, y gris es la que haría falta para diluir la contaminación generada.', 'Sumarlas en un solo número grande esconde justo lo que importa: de dónde salió cada litro.', (select id from ac_fuentes where slug = 'huella-hidrica'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua.un_litro_no_vale_igual', 'agua', 'Un litro no vale lo mismo en todos lados', 'El mismo litro pesa distinto según de dónde salga: sacarlo de una cuenca con lluvia de sobra no es lo mismo que sacarlo de una zona donde el agua ya escasea.', null, (select id from ac_fuentes where slug = 'huella-hidrica'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua.grises_y_negras', 'agua', 'Aguas grises y aguas negras', 'El agua que sale de tu casa no es toda igual: las grises vienen de la ducha, el lavarropas y la pileta de la cocina; las negras vienen del inodoro y necesitan tratamiento sí o sí.', 'Separarlas permite reutilizar las grises para riego o para el inodoro.', (select id from ac_fuentes where slug = 'epa'), 2, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.depuracion_etapas', 'agua', 'Las etapas de una planta cloacal', 'El tratamiento cloacal va por etapas: el primario separa sólidos, el secundario usa bacterias que se comen la materia orgánica y el terciario, cuando existe, saca nutrientes y desinfecta.', 'Muchas plantas llegan hasta el secundario: el terciario es más caro y es el que cuida al río de los nutrientes.', (select id from ac_fuentes where slug = 'epa'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.eutrofizacion', 'agua', 'Demasiados nutrientes', 'Cuando al agua le llegan muchos nutrientes de cloacas o de fertilizantes, las algas se multiplican, tapan la luz y al descomponerse consumen el oxígeno que los peces necesitan.', 'Es el mismo mecanismo en una laguna del conurbano y en un tramo del río.', (select id from ac_fuentes where slug = 'epa'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.floraciones_cianobacterias', 'agua', 'Cuando el agua se pone verde', 'Con calor y muchos nutrientes aparecen floraciones de cianobacterias que pintan el agua de verde y pueden producir toxinas, y por eso a veces se recomienda no bañarse ni dejar entrar a las mascotas.', 'Si ves el agua verde, espesa o con espuma, no te metas y avisale a una persona adulta.', (select id from ac_fuentes where slug = 'epa'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.fallo_mendoza', 'agua', 'El fallo que creó ACUMAR', 'En 2008 la Corte Suprema falló en la causa Mendoza y ordenó a la Nación, la Provincia y la Ciudad sanear la cuenca Matanza-Riachuelo: de ahí salen ACUMAR y su plan de saneamiento.', 'Lo empezaron vecinas y vecinos de la cuenca: el derecho a un ambiente sano se puede reclamar y a veces se gana.', (select id from ac_fuentes where slug = 'acumar'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.humedal_esponja', 'agua', 'Los humedales son esponjas', 'Un humedal absorbe el agua de las crecidas, la suelta despacio y de paso la filtra: hace gratis buena parte del trabajo de una obra hidráulica.', 'También guarda carbono y sostiene una cantidad enorme de fauna.', (select id from ac_fuentes where slug = 'ramsar'), 2, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.suelo_impermeable', 'agua', 'Suelo que no deja pasar', 'Cada superficie que se cubre con cemento o asfalto es lluvia que ya no se infiltra: esa agua corre por la calle y llega toda junta y al mismo tiempo al desagüe.', 'El problema no es solo cuánta agua cae, sino qué tan rápido llega abajo.', (select id from ac_fuentes where slug = 'epa'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.arroyos_entubados', 'agua', 'Los arroyos que siguen ahí', 'Debajo de la Ciudad siguen corriendo arroyos entubados como el Maldonado, el Vega y el Medrano: cambió la superficie, pero el agua sigue buscando el mismo camino bajo.', 'Por eso las zonas que se anegan suelen coincidir con los cauces viejos.', (select id from ac_fuentes where slug = 'acuifero-puelche'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.suds_verde', 'agua', 'Hacerle lugar al agua', 'Jardines de lluvia, veredas permeables, terrazas verdes y zanjas con plantas hacen que parte de la lluvia se infiltre donde cae, en vez de correr toda junta al mismo caño.', 'Un cantero abierto en tu vereda o un patio con tierra en vez de cemento juegan en el mismo equipo que una obra grande.', (select id from ac_fuentes where slug = 'epa'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.derecho_al_agua', 'agua', 'El agua es un derecho', 'El acceso al agua segura y al saneamiento está reconocido como un derecho humano y es una meta acordada entre países: no es un servicio opcional ni un premio.', 'Por eso el reclamo por cloacas o por agua de red en un barrio es un reclamo de derechos, no un pedido de favor.', (select id from ac_fuentes where slug = 'unesco-ods'), 2, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.caudal_ecologico', 'agua', 'El río también necesita su parte', 'El caudal ecológico es el agua que hay que dejar correr para que el río y su humedal sigan funcionando: cuando se reparte un río, ese caudal es uno de los usuarios.', null, (select id from ac_fuentes where slug = 'ramsar'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua.estres_hidrico', 'agua', 'Estrés hídrico', 'Una región tiene estrés hídrico cuando la demanda se acerca al agua disponible: no es que no haya agua, es que casi toda ya está comprometida.', 'El promedio anual puede verse cómodo y el verano no serlo: el estrés se juega en el momento y en el lugar.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua.desalinizacion_energia', 'agua', 'Sacarle la sal al mar', 'Desalinizar es técnicamente posible, pero pide mucha energía y deja una salmuera concentrada que hay que devolver a algún lado: es una solución cara, no una canilla infinita.', 'Cuidar la cuenca y arreglar las pérdidas casi siempre entrega más agua por peso invertido.', (select id from ac_fuentes where slug = 'unep'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.rio_de_la_plata_estuario', 'agua_azul', 'El estuario más ancho del mundo', 'El Río de la Plata es un estuario: el lugar donde el agua dulce de los ríos se encuentra con la salada del mar y se mezcla.', null, (select id from ac_fuentes where slug = 'ramsar'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.turbidez_natural', 'agua_azul', 'El color marrón es sedimento', 'El Río de la Plata es marrón porque arrastra sedimento de toda la cuenca, no porque esté sucio. Turbio y contaminado no son lo mismo.', null, (select id from ac_fuentes where slug = 'ramsar'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.el_parana_y_la_bajante', 'agua_azul', 'El Paraná y la bajante', 'El Paraná tuvo una bajante histórica que dejó al descubierto el fondo en tramos enteros y afectó el transporte, la pesca y las tomas de agua.', null, (select id from ac_fuentes where slug = 'incendios-delta-2020'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.cianobacterias_balneario', 'agua_azul', 'Cuando cierran la playa', 'Las floraciones de cianobacterias pueden hacer que el agua no sea apta para bañarse: si el agua está verde y con olor, no se entra ni se deja entrar a las mascotas.', null, (select id from ac_fuentes where slug = 'acumar'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.que_es_un_humedal', 'agua_azul', 'Qué es un humedal', 'Un humedal es un terreno donde el agua manda: se inunda y se seca de forma cíclica, y esa dinámica es la que sostiene todo lo que vive ahí.', null, (select id from ac_fuentes where slug = 'ramsar'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.lo_que_hace_un_humedal', 'agua_azul', 'Lo que hace un humedal', 'Amortigua crecidas, filtra agua, guarda carbono y sostiene una biodiversidad enorme. Todo eso lo hace gratis y sin que nadie lo administre.', null, (select id from ac_fuentes where slug = 'ramsar'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.delta_e_islas', 'agua_azul', 'El Delta e Islas del Paraná', 'Es un mosaico de islas, arroyos y bosque ribereño que llega hasta el Río de la Plata, y es el humedal más cercano a la mayor concentración urbana del país.', null, (select id from ac_fuentes where slug = 'ecorregiones-pba'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.reserva_ramsar_urbana', 'agua_azul', 'Un sitio Ramsar en la ciudad', 'La Reserva Ecológica Costanera Sur ocupa unas 350 hectáreas sobre un relleno de escombros y es sitio Ramsar desde 2005: registra 343 especies de aves.', 'Es la mejor historia local de "si la dejás, vuelve".', (select id from ac_fuentes where slug = 'reserva-costanera-sur'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.ley_de_humedales', 'agua_azul', 'La ley que no sale', 'El proyecto de Ley de Humedales se presentó una y otra vez desde 2013 y nunca se sancionó, aunque los grandes incendios lo vuelven a poner en agenda cada vez.', null, (select id from ac_fuentes where slug = 'incendios-delta-2020'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.origen_terrestre', 'agua_azul', 'De dónde viene la basura marina', 'La gran mayoría de la basura que hay en el mar se generó en tierra y llegó por ríos, desagües y viento.', null, (select id from ac_fuentes where slug = 'unep'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.rio_como_cinta', 'agua_azul', 'El río como cinta transportadora', 'Un río recoge lo que cae en toda su cuenca: por eso una cuenca mal gestionada se convierte en un caño que descarga al mar.', null, (select id from ac_fuentes where slug = 'unep'), 1, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.microplasticos_mar', 'agua_azul', 'Microplásticos', 'El plástico grande se fragmenta con el sol y el oleaje hasta quedar en trozos diminutos que ya no se pueden recoger.', null, (select id from ac_fuentes where slug = 'unep'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.redes_fantasma', 'agua_azul', 'Redes fantasma', 'Las redes de pesca perdidas siguen atrapando fauna durante años. Es la excepción real al origen terrestre de la basura marina.', null, (select id from ac_fuentes where slug = 'unep'), 2, 0.4, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('agua_azul.plataforma_ancha', 'agua_azul', 'Una plataforma muy ancha', 'La plataforma continental argentina es una de las más extensas del mundo: mar poco profundo, con luz llegando al fondo y mucha vida.', null, (select id from ac_fuentes where slug = 'milla-201'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.confluencia', 'agua_azul', 'Malvinas y Brasil se encuentran', 'La corriente fría de Malvinas y la cálida de Brasil se cruzan frente a Mar del Plata, y ese encuentro genera una zona de altísima productividad.', null, (select id from ac_fuentes where slug = 'milla-201'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.fauna_marina_emblema', 'agua_azul', 'Quiénes viven ahí', 'La ballena franca austral, el pingüino de Magallanes, el lobo marino, la tonina overa y la franciscana son fauna marina característica de la costa argentina.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.areas_marinas_protegidas', 'agua_azul', 'Áreas marinas protegidas', 'Argentina tiene áreas marinas protegidas —Namuncurá–Banco Burdwood y Yaganes entre ellas— donde se restringen actividades para dejar recuperar el fondo y las poblaciones.', null, (select id from ac_fuentes where slug = 'milla-201'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.zee_y_milla_201', 'agua_azul', 'La milla 201', 'Justo afuera de la Zona Económica Exclusiva argentina opera una flota internacional sobre recursos que migran desde aguas argentinas, en un área sin regulación efectiva.', null, (select id from ac_fuentes where slug = 'milla-201'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.pesca_de_arrastre', 'agua_azul', 'Pesca de arrastre', 'Arrastrar una red por el fondo captura mucho, y de paso destruye la estructura del fondo, que tarda años en rearmarse.', null, (select id from ac_fuentes where slug = 'fao'), 2, 0.4, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('agua_azul.bycatch', 'agua_azul', 'Captura incidental', 'Los albatros y petreles se enganchan en las líneas de pesca. Las líneas espantapájaros son una solución barata que reduce mucho esas muertes.', null, (select id from ac_fuentes where slug = 'aves-argentinas-amenazadas'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('agua_azul.cuota_y_talla', 'agua_azul', 'Cuota, talla y veda', 'Una pesquería se administra con tres perillas: cuánto se puede sacar, de qué tamaño mínimo y en qué época no se pesca.', null, (select id from ac_fuentes where slug = 'fao'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.sellos_de_pesca', 'agua_azul', 'Los sellos de pesca', 'Un sello de pesca sostenible dice que alguien externo auditó la pesquería. Vale lo que valga su auditoría, así que conviene saber quién certifica.', null, (select id from ac_fuentes where slug = 'fao'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.oceano_regulador', 'agua_azul', 'El océano regula el clima', 'El mar absorbe una parte enorme del calor extra y del CO₂ que emitimos: sin ese amortiguador, el calentamiento en superficie sería mucho mayor.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.bomba_biologica', 'agua_azul', 'La bomba biológica', 'El plancton captura carbono en la superficie y parte de él se hunde al morir: es un mecanismo que baja carbono al fondo del mar durante siglos.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.acidificacion', 'agua_azul', 'Acidificación', 'Cuando el mar absorbe CO₂ su química cambia y se vuelve más ácido, lo que dificulta que los organismos con caparazón o esqueleto calcáreo los formen.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.tratado_alta_mar', 'agua_azul', 'El Tratado de Alta Mar', 'Más allá de las zonas nacionales el mar era tierra de nadie. El acuerdo BBNJ crea el marco para proteger áreas en aguas internacionales.', null, (select id from ac_fuentes where slug = 'unep'), 3, 0.8, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.urbanizar_humedales', 'agua_azul', 'Construir sobre humedal', 'Rellenar un humedal para urbanizar traslada el agua a otro lado: la crecida no desaparece, se muda al vecino.', null, (select id from ac_fuentes where slug = 'ramsar'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.hidrovia', 'agua_azul', 'La Hidrovía', 'Mantener el Paraná navegable para buques grandes requiere dragado permanente, y ese dragado modifica el fondo, los sedimentos y los ambientes ribereños.', null, (select id from ac_fuentes where slug = 'incendios-delta-2020'), 3, 0.8, '{"teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('agua_azul.erosion_costera', 'agua_azul', 'La costa se mueve', 'Las playas ganan y pierden arena todo el tiempo. Construir muy cerca del agua interrumpe ese movimiento y suele acelerar la erosión.', null, (select id from ac_fuentes where slug = 'ecorregiones-pba'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('agua_azul.restaurar_costa', 'agua_azul', 'Devolverle lugar al agua', 'Recuperar humedales y dejar franjas sin construir suele ser más barato y más duradero que levantar defensas de hormigón cada vez más altas.', null, (select id from ac_fuentes where slug = 'ramsar'), 3, 0.9, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.composicion_atmosfera', 'aire_suelo', 'De qué está hecho el aire', 'El aire es casi todo nitrógeno y oxígeno. Los gases que regulan la temperatura son una fracción muy chica, y por eso cambiarlos un poco cambia mucho.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.efecto_invernadero_natural', 'aire_suelo', 'La frazada que ya estaba', 'El efecto invernadero natural mantiene el planeta habitable: sin él, la Tierra sería demasiado fría para la vida que conocemos.', 'El efecto invernadero no es el problema. Es la vida.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.efecto_intensificado', 'aire_suelo', 'Cuando la frazada engorda', 'El problema no es que exista el efecto invernadero, sino que aumentó mucho la cantidad de gases que lo producen, y entonces se atrapa más calor del que solía.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.gei_principales', 'aire_suelo', 'Los gases que abrigan', 'Los principales son dióxido de carbono, metano, óxido nitroso y los gases fluorados. No pesan igual ni duran lo mismo en la atmósfera.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.metano_vs_co2', 'aire_suelo', 'Metano y CO₂ no son lo mismo', 'El metano calienta mucho más por molécula pero permanece bastante menos tiempo; el CO₂ calienta menos por molécula y se queda siglos.', 'Por eso bajar metano da alivio rápido y bajar CO₂ es lo que decide el largo plazo.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.capa_de_ozono', 'aire_suelo', 'Qué hace la capa de ozono', 'La capa de ozono está en la estratósfera y filtra buena parte de la radiación ultravioleta que llega a la superficie.', null, (select id from ac_fuentes where slug = 'ncse-ozono'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.cfc_y_montreal', 'aire_suelo', 'Los CFC y el Protocolo de Montreal', 'Cuando se identificó que ciertos gases industriales destruían el ozono, se acordó dejarlos de fabricar, y la capa empezó a recuperarse.', 'Es el mejor caso conocido de un problema ambiental global que se atacó y funcionó.', (select id from ac_fuentes where slug = 'ncse-ozono'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.ozono_troposferico', 'aire_suelo', 'El ozono de abajo, que sí molesta', 'A nivel del suelo el ozono no protege: se forma con el sol a partir de los contaminantes del tránsito y es irritante para las vías respiratorias.', null, (select id from ac_fuentes where slug = 'epa'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.dos_problemas_dos_soluciones', 'aire_suelo', 'Dos problemas, dos soluciones', 'Confundirlos lleva a la conclusión equivocada: dejar de usar aerosoles no baja las emisiones de CO₂, y bajar el CO₂ no arregla el ozono.', null, (select id from ac_fuentes where slug = 'ncse-ozono'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.material_particulado', 'aire_suelo', 'PM2.5 y PM10', 'Son partículas tan chicas que no se ven ni se filtran en la nariz. Las de 2,5 micrones llegan hasta lo más profundo del pulmón.', null, (select id from ac_fuentes where slug = 'epa'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.fuentes_amba', 'aire_suelo', 'De dónde sale en el AMBA', 'Las fuentes principales son el tránsito, la industria, la quema de residuos y, en episodios, la quema de pastizales del Delta.', null, (select id from ac_fuentes where slug = 'acumar'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.humo_del_delta', 'aire_suelo', 'El humo del Delta', 'Los incendios del delta del Paraná de 2020 arrasaron cientos de miles de hectáreas de humedal y llevaron humo hasta Rosario y el AMBA.', null, (select id from ac_fuentes where slug = 'incendios-delta-2020'), 1, 0, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('aire_suelo.inversion_termica', 'aire_suelo', 'Inversión térmica', 'En ciertas noches frías y sin viento se forma una tapa de aire cálido arriba que impide que el aire de abajo se mezcle, y todo lo emitido queda a nivel del suelo.', null, (select id from ac_fuentes where slug = 'epa'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.aire_interior', 'aire_suelo', 'El aire de adentro', 'Cocinar, calefaccionar mal ventilado o usar ciertos productos de limpieza puede dejar el aire de una casa peor que el de la calle.', 'Ventilar cruzado unos minutos es la medida más barata que existe.', (select id from ac_fuentes where slug = 'epa'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.perfil_y_horizontes', 'aire_suelo', 'El perfil del suelo', 'Si cortás el suelo verticalmente ves capas distintas: arriba la materia orgánica, después el suelo mineral, después la roca en camino de deshacerse.', null, (select id from ac_fuentes where slug = 'inta'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.materia_organica', 'aire_suelo', 'La materia orgánica', 'Es lo que le da al suelo su color oscuro, su capacidad de retener agua y su fertilidad. Se construye en décadas y se pierde en pocas temporadas.', null, (select id from ac_fuentes where slug = 'inta'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.suelo_pampeano', 'aire_suelo', 'El suelo pampeano', 'La Pampa tiene uno de los suelos más fértiles del mundo, formado bajo miles de años de pastizal con raíces profundas.', null, (select id from ac_fuentes where slug = 'ecorregiones-pba'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.carbono_del_suelo', 'aire_suelo', 'El suelo guarda carbono', 'Hay más carbono almacenado en los suelos del mundo que en toda la vegetación: cuidar el suelo es una política climática, no solo agrícola.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.erosion', 'aire_suelo', 'Erosión hídrica y eólica', 'Un suelo sin cobertura vegetal se lo lleva el agua o el viento, y lo primero que se va es justo la capa superior, que es la fértil.', null, (select id from ac_fuentes where slug = 'inta'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.compactacion', 'aire_suelo', 'Compactación', 'El paso repetido de maquinaria pesada aplasta los poros del suelo: entra menos aire, entra menos agua y las raíces no pueden bajar.', null, (select id from ac_fuentes where slug = 'inta'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.salinizacion', 'aire_suelo', 'Salinización', 'Regar mal en zonas secas deja sales que el agua no alcanza a lavar, y con el tiempo el suelo deja de servir para cultivar.', null, (select id from ac_fuentes where slug = 'fao'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.siembra_directa', 'aire_suelo', 'Siembra directa: alcances y límites', 'No arar reduce la erosión y ayuda a conservar materia orgánica, pero por sí sola no resuelve la compactación ni la dependencia de agroquímicos.', null, (select id from ac_fuentes where slug = 'inta'), 3, 0.8, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.desertificacion', 'aire_suelo', 'Desertificación', 'Es la degradación acumulada de tierras en zonas secas hasta que pierden su capacidad productiva, y en la Argentina afecta a buena parte del territorio.', null, (select id from ac_fuentes where slug = 'fao'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.que_es_un_pasivo', 'aire_suelo', 'Qué es un pasivo ambiental', 'Es la contaminación que queda en un sitio después de que la actividad que la generó terminó, y que alguien va a tener que pagar o convivir con ella.', null, (select id from ac_fuentes where slug = 'acumar'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.metales_pesados', 'aire_suelo', 'Metales pesados', 'Plomo, cromo y mercurio no se degradan: se quedan en el suelo y en el sedimento, y pueden pasar al agua o a los cultivos.', null, (select id from ac_fuentes where slug = 'acumar'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('aire_suelo.riachuelo_curtiembres', 'aire_suelo', 'El caso del Riachuelo', 'En la Cuenca Matanza-Riachuelo conviven décadas de vertidos industriales con barrios enteros: el saneamiento es tan social como técnico.', null, (select id from ac_fuentes where slug = 'acumar'), 2, 0.6, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('aire_suelo.biorremediacion', 'aire_suelo', 'Biorremediación y fitorremediación', 'Hay bacterias y plantas que degradan o acumulan contaminantes. Funcionan, son baratas y son lentas: no reemplazan a evitar el vertido.', null, (select id from ac_fuentes where slug = 'inta'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.indice_calidad_aire', 'aire_suelo', 'El índice de calidad del aire', 'Resume varios contaminantes en un solo número con colores. Es útil para decidir si salir a correr, y esconde cuál de todos es el que está alto.', null, (select id from ac_fuentes where slug = 'epa'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.donde_esta_la_estacion', 'aire_suelo', 'Dónde está la estación importa', 'Una estación de monitoreo mide donde está: en una avenida da distinto que en un parque a tres cuadras, y las dos mediciones son correctas.', null, (select id from ac_fuentes where slug = 'acumar'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.promedio_y_pico', 'aire_suelo', 'Promedio anual y pico horario', 'Un promedio anual bueno puede convivir con picos que enferman: para salud importan las dos cosas, y son dos límites distintos.', null, (select id from ac_fuentes where slug = 'epa'), 3, 0.8, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('aire_suelo.liquenes_indicadores', 'aire_suelo', 'Los líquenes como medidores', 'Los líquenes son muy sensibles a la contaminación del aire: mirar cuáles crecen en los troncos de una cuadra da una lectura sin instrumentos.', null, (select id from ac_fuentes where slug = 'argentinat'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.grupos_de_alimentos', 'alimentacion', 'Cómo se arma un plato', 'Las guías alimentarias argentinas ordenan la comida en grupos y proponen que las verduras y frutas ocupen alrededor de la mitad del plato diario.', 'No es una lista de prohibiciones: es una proporción. Lo que cambia el conjunto es qué ocupa más lugar, no qué desaparece.', (select id from ac_fuentes where slug = 'fao'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.ultraprocesados', 'alimentacion', 'Qué es un ultraprocesado', 'Un ultraprocesado no es cualquier alimento envasado: es una formulación industrial armada con ingredientes y aditivos que no tenés en tu cocina.', 'Un paquete de arroz está procesado. Una galletita rellena está ultraprocesada. La diferencia es cuánto se rearmó el alimento, no si viene en bolsa.', (select id from ac_fuentes where slug = 'fao'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.octogonos_negros', 'alimentacion', 'Los octógonos negros', 'La ley argentina de etiquetado frontal obliga a poner octógonos negros en el frente del envase cuando un producto tiene exceso de azúcares, sodio, grasas o calorías.', 'El octógono no dice "no lo comas": dice "acá hay exceso". Es información puesta justo donde se decide, en la góndola.', (select id from ac_fuentes where slug = 'fao'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.comer_es_una_decision_ambiental', 'alimentacion', 'Comer es una decisión ambiental', 'Cada comida conecta tu mesa con un suelo, un agua y un clima: el sistema alimentario es una de las mayores presiones humanas sobre el ambiente.', 'Lo bueno de eso es la frecuencia. Es una decisión que volvés a tomar dos o tres veces por día, así que hay muchísimas oportunidades de mejorarla.', (select id from ac_fuentes where slug = 'owid-impactos-alimentos'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.estacionalidad', 'alimentacion', 'Cada cosa a su tiempo', 'Cada fruta y verdura tiene su temporada: en temporada rinde más, cuesta menos y necesita menos invernadero, cámara de frío y viaje.', 'En el AMBA el invierno es de cítricos, zapallo y hojas verdes; el verano, de tomate, durazno y ciruela. Fijate en la verdulería qué está barato: eso suele ser lo que está de estación.', (select id from ac_fuentes where slug = 'inta'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.cinturon_horticola', 'alimentacion', 'La quinta del conurbano', 'Buena parte de la verdura fresca que se come en el AMBA se produce en el propio conurbano, en las quintas del cinturón hortícola bonaerense.', 'La Plata, Florencio Varela y Berazategui abastecen las verdulerías de la ciudad todos los días. El campo está más cerca de lo que parece.', (select id from ac_fuentes where slug = 'inta'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.agricultura_familiar', 'alimentacion', 'Agricultura familiar', 'La agricultura familiar produce una parte importante de los alimentos frescos que llegan a las mesas argentinas, en unidades chicas y con trabajo de la propia familia.', 'Las ferias de la agricultura familiar acortan la cadena: quien produce y quien compra se ven la cara. De esa idea sale la palabra soberanía alimentaria.', (select id from ac_fuentes where slug = 'inta'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.comercio_justo', 'alimentacion', 'Comercio justo', 'El comercio justo es un acuerdo sobre el precio y las condiciones de trabajo de quien produce, no una promesa sobre el sabor del producto.', 'Es una de las pocas etiquetas que habla de personas y no de nutrientes. Como toda certificación, vale lo que valga quien la controla.', (select id from ac_fuentes where slug = 'unesco-ods'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.desperdicio_un_tercio', 'alimentacion', 'Un tercio en el camino', 'Alrededor de un tercio de los alimentos que se producen en el mundo nunca llegan a comerse.', 'Cuando se tira comida se tira además todo lo que hizo falta para producirla: agua, suelo, trabajo y combustible.', (select id from ac_fuentes where slug = 'fao'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.donde_se_pierde', 'alimentacion', 'En qué eslabón se pierde', 'La comida se pierde a lo largo de toda la cadena —campo, transporte, góndola— y también se desperdicia en la última etapa, adentro de las casas.', 'Saber en qué eslabón pasa es lo que decide qué conviene hacer: en casa se resuelve planificando la compra, en el campo con logística y frío.', (select id from ac_fuentes where slug = 'fao'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.fechas_de_vencimiento', 'alimentacion', 'Las dos fechas del envase', '"Consumir antes de" es una fecha de seguridad; "consumir preferentemente antes de" es una fecha de calidad, y muchos alimentos siguen estando buenos después.', 'Confundirlas manda a la basura comida en buen estado. Con carne, pescado y lácteos frescos, en cambio, la fecha manda: ahí no se improvisa.', (select id from ac_fuentes where slug = 'fao'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.compostaje_de_comida', 'alimentacion', 'De la cáscara a la tierra', 'Los restos de comida son una de las fracciones más pesadas de la basura doméstica, y compostados dejan de ser basura para volver a ser tierra.', 'En CABA la ley Basura Cero apunta justamente a sacar del enterramiento ese tipo de material. Un balde con tapa en la cocina alcanza para arrancar.', (select id from ac_fuentes where slug = 'ley-1854-basura-cero'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.huella_por_alimento', 'alimentacion', 'No todo pesa igual', 'El impacto ambiental cambia muchísimo de un alimento a otro: por kilo, los de origen animal pesan bastante más que los vegetales.', 'Es la diferencia más grande de toda la rama. Antes de afinar detalles, conviene mirar qué grupo de alimentos ocupa el plato.', (select id from ac_fuentes where slug = 'owid-impactos-alimentos'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.transporte_es_poco', 'alimentacion', 'Los kilómetros pesan poco', 'En la mayoría de los alimentos el transporte explica una porción chica de las emisiones: el grueso se genera en la producción, antes de que el alimento se suba a un camión.', 'La excepción son los pocos alimentos que viajan en avión, algo raro y caro. Casi todo lo demás viaja en barco o camión, que mueven mucha carga con poco combustible por kilo.', (select id from ac_fuentes where slug = 'owid-alimentos'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.que_comes_vs_donde', 'alimentacion', 'Qué comés antes que de dónde viene', 'Para bajar la huella de tu comida, cambiar qué comés mueve mucho más el número que cambiar de dónde viene.', 'No es que lo local no importe: es que la palanca grande está en el tipo de alimento. Empezá por ahí y después afiná.', (select id from ac_fuentes where slug = 'owid-alimentos'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.local_igual_sirve', 'alimentacion', 'Comprar cerca igual sirve', 'Comprar cerca tiene ventajas reales —dinero que queda en el barrio, verdura más fresca, variedades que no aguantan el viaje— aunque no sea la palanca climática principal.', 'Un argumento puede ser flojo para una cosa y bueno para otra. Eso no lo vuelve mentira: lo vuelve preciso.', (select id from ac_fuentes where slug = 'owid-alimentos'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.agua_y_tierra_del_plato', 'alimentacion', 'Además de emitir, ocupa', 'La comida no solo emite gases: también ocupa tierra y usa agua, y a escala mundial el sistema alimentario es el principal usuario de las dos cosas.', 'Por eso una decisión alimentaria se mide en varias unidades a la vez, y a veces lo mejor para una no es lo mejor para otra.', (select id from ac_fuentes where slug = 'owid-impactos-alimentos'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.metano_enterico', 'alimentacion', 'El metano de la digestión', 'Las vacas, ovejas y cabras producen metano al digerir pasto, y el metano es un gas de efecto invernadero potente que dura pocas décadas en la atmósfera.', 'Potente y de vida corta a la vez: por eso bajarlo se nota rápido en la temperatura, al revés del CO₂, que se queda muchísimo más tiempo.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.pastizal_vs_feedlot', 'alimentacion', 'Pasto o corral', 'La misma vaca deja huellas distintas según cómo se críe: a pasto sobre pastizal, a corral con grano, o combinando las dos etapas, como es habitual en Argentina.', 'A corral se engorda más rápido y con menos metano por kilo, pero se necesita grano, y ese grano ocupa tierra en otro lado. No hay una respuesta única.', (select id from ac_fuentes where slug = 'inta'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.pastizal_guarda_carbono', 'alimentacion', 'El carbono que vive abajo', 'El pastizal pampeano guarda la mayor parte de su carbono bajo tierra, en raíces y suelo, y sostiene pastos y aves que no viven en ningún otro lado.', 'Ganadería sobre pastizal bien manejado es una de las pocas maneras de que ese ecosistema siga existiendo en vez de convertirse en cultivo.', (select id from ac_fuentes where slug = 'inta'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.carne_en_argentina', 'alimentacion', 'La carne acá', 'En Argentina la carne es alimento, trabajo, exportación y también identidad, así que la discusión no se resuelve con un sí o un no.', 'Las preguntas útiles son otras: cuánta, cada cuánto, criada dónde y a costa de qué. Con esas cuatro se avanza más que con una consigna.', (select id from ac_fuentes where slug = 'inta'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.flexitariana', 'alimentacion', 'Menos veces, no nunca', 'No hace falta dejar la carne para bajar la huella de lo que comés: bajar la frecuencia ya mueve el número, y ahí está la mayor parte del efecto.', 'En eso se apoyan las dietas flexitarianas: menos veces por semana, no nunca más. Es un cambio que la gente sostiene en el tiempo, y sostenerlo es lo que cuenta.', (select id from ac_fuentes where slug = 'owid-impactos-alimentos'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.soja_y_frontera', 'alimentacion', 'La frontera que se corrió', 'La soja empujó la frontera agrícola argentina hacia el norte, y buena parte de esa producción sale del país como alimento para animales.', 'Cuando comés pollo o cerdo, en gran medida estás comiendo grano. Ese grano ocupó tierra en algún lado, y ese lado tiene nombre.', (select id from ac_fuentes where slug = 'fao'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.desmonte_chaco', 'alimentacion', 'La Ley de Bosques y el Chaco', 'La Ley de Bosques obligó a cada provincia a zonificar sus bosques nativos y frenó parte del desmonte, pero en el Chaco el desmonte continúa, sobre todo el ilegal.', 'La ley existe y sirve; lo que se discute es cómo se aplica y cómo se recategorizan las zonas. Ahí hay lugar concreto para participación pública y acceso a la información.', (select id from ac_fuentes where slug = 'ley-bosques-26331'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('alimentacion.agroquimicos_distancias', 'alimentacion', 'Las distancias de aplicación', 'Las aplicaciones de agroquímicos cerca de casas y escuelas están reguladas por normas provinciales y ordenanzas municipales que fijan distancias mínimas.', 'El principio precautorio de la ley ambiental argentina es lo que sostiene esos límites: cuando hay riesgo de daño grave y falta certeza, se actúa igual.', (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.agroecologia', 'alimentacion', 'Producir con el ecosistema', 'La agroecología produce apoyándose en procesos del propio ecosistema —rotaciones, cultivos de cobertura, control biológico— para depender menos de insumos comprados.', 'No es una idea de escritorio: el INTA acompaña experiencias agroecológicas en todo el país, incluidas quintas del cinturón hortícola bonaerense.', (select id from ac_fuentes where slug = 'inta'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.merluza_y_cuota', 'alimentacion', 'Cuánto se puede sacar', 'La merluza común es la pesquería más importante del Mar Argentino y se administra con cuotas: cuánto se puede pescar por año y quién puede hacerlo.', 'La cuota existe para que la pesca no se coma su propio stock. Funciona si el número está bien puesto y si alguien controla que se cumpla.', (select id from ac_fuentes where slug = 'fao'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('alimentacion.milla_201', 'alimentacion', 'La milla 201', 'Justo afuera de la zona económica exclusiva argentina, en lo que se conoce como la milla 201, se concentra cada año una flota extranjera enorme pescando en aguas internacionales.', 'Ahí no rige la cuota argentina, y los peces no saben de líneas en el mapa. Es tanto un problema de gobernanza como de pesca.', (select id from ac_fuentes where slug = 'milla-201'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.sellos_pesca', 'alimentacion', 'Qué promete un sello', 'Un sello de pesca sostenible es una certificación de un tercero sobre cómo se pescó, no una opinión de la marca sobre sí misma.', 'La vieira patagónica es una de las pesquerías argentinas que consiguió ese tipo de certificación. Un sello vale lo que valga la auditoría que tiene detrás.', (select id from ac_fuentes where slug = 'fao'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('alimentacion.acuicultura', 'alimentacion', 'Criar en vez de pescar', 'Alrededor de la mitad del pescado que se come en el mundo ya no se pesca: se cría, en agua dulce o en el mar.', 'La acuicultura saca presión del mar salvaje, pero trae sus propios temas: con qué se alimenta a los peces, qué sale con el agua y dónde se instalan las jaulas.', (select id from ac_fuentes where slug = 'fao'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.ser_vivo', 'animales', 'Qué hace que algo esté vivo', 'Un ser vivo nace, usa energía, responde a lo que pasa alrededor, crece y deja descendencia. Una piedra no hace nada de eso.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -1.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.vertebrados_invertebrados', 'animales', 'Con columna y sin columna', 'Los vertebrados tienen columna vertebral; los invertebrados no. La enorme mayoría de los animales del planeta son invertebrados.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cinco_clases', 'animales', 'Las cinco clases de vertebrados', 'Peces, anfibios, reptiles, aves y mamíferos. Cada grupo tiene su forma de respirar, de reproducirse y de manejar la temperatura.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.artropodos', 'animales', 'Artrópodos: el grupo más numeroso', 'Insectos, arácnidos, crustáceos y miriápodos comparten esqueleto externo y patas articuladas. Son el grupo con más especies del planeta.', 'Los insectos tienen seis patas; las arañas, ocho.', (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.moluscos', 'animales', 'Moluscos', 'Caracoles, babosas, almejas y pulpos: cuerpo blando, muchas veces con concha, y un papel enorme en ríos y mares.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.metamorfosis', 'animales', 'Metamorfosis completa e incompleta', 'Algunos insectos pasan por huevo, larva, pupa y adulto —como la mariposa—; otros nacen parecidos al adulto y solo van creciendo, como la langosta.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.oviparo_viviparo', 'animales', 'Ovíparo, vivíparo y ovovivíparo', 'Poner huevos, gestar dentro del cuerpo, o incubar los huevos adentro hasta que nacen: tres formas distintas de traer crías al mundo.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.ectotermo_endotermo', 'animales', '"Sangre fría" es un mal nombre', 'Un ectotermo regula su temperatura con el ambiente —por eso una lagartija se asolea— y un endotermo la genera por dentro. Nada de eso implica que la sangre esté fría.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.habitat_vs_nicho', 'animales', 'Hábitat y nicho', 'El hábitat es la dirección: dónde vive. El nicho es el oficio: qué come, cuándo sale, con quién compite y qué papel cumple.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.tipos_de_alimentacion', 'animales', 'Quién come qué', 'Herbívoros comen plantas, carnívoros comen animales, omnívoros las dos cosas, detritívoros restos, y carroñeros lo que ya estaba muerto.', 'Los últimos dos son los que mantienen limpio el sistema.', (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.camuflaje', 'animales', 'Camuflaje', 'Parecerse al fondo es la forma más común de no ser visto, y funciona tanto para no ser comido como para poder cazar.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.mimetismo_aposematismo', 'animales', 'Imitar y advertir', 'El mimetismo es parecerse a otra especie para aprovechar su fama; el aposematismo es lo contrario: colores llamativos que avisan "no me comas".', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.huellas_y_rastros', 'animales', 'Huellas y rastros', 'Casi nunca ves al animal, pero sí lo que dejó: huellas, plumas, madrigueras, restos de comida o egagrópilas. Leer rastros es la forma más accesible de conocer la fauna de un lugar.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cantos', 'animales', 'Cantos y llamadas', 'Muchas aves y anfibios se identifican antes por el oído que por la vista: el canto marca territorio, busca pareja y avisa peligro.', null, (select id from ac_fuentes where slug = 'ebird'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.actividad_dia_noche', 'animales', 'De día, de noche y en el medio', 'Diurno, nocturno o crepuscular: repartirse las horas es una de las maneras más elegantes de que dos especies no compitan por lo mismo.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.nombre_comun_confunde', 'animales', 'El nombre común cambia de pueblo en pueblo', 'La misma especie puede tener cinco nombres distintos según la región, y el mismo nombre puede referirse a especies diferentes.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.nomenclatura_binomial', 'animales', 'Dos palabras, un solo animal', 'El nombre científico tiene género y especie, y es el mismo en todo el mundo: un carpincho es Hydrochoerus hydrochaeris en cualquier idioma.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.jerarquia_linneana', 'animales', 'Las cajas dentro de cajas', 'Dominio, reino, filo, clase, orden, familia, género y especie: cada nivel agrupa al anterior, y cuanto más abajo, más parecidos son entre sí.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.arbol_filogenetico', 'animales', 'El árbol de parentesco', 'Un árbol filogenético muestra quién comparte antepasado con quién: agrupa por historia evolutiva, no por parecido.', 'Por eso un delfín está más cerca de una vaca que de un tiburón.', (select id from ac_fuentes where slug = 'sib-apn'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.especie_biologica', 'animales', 'Qué es una especie', 'La definición más usada es la de poblaciones que se cruzan entre sí y dejan descendencia fértil, y tiene excepciones conocidas.', null, (select id from ac_fuentes where slug = 'sib-apn'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cadena_vs_red', 'animales', 'Cadena o red', 'Una cadena trófica es una línea simple; en la realidad casi todos comen varias cosas y son comidos por varias, así que es una red.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.niveles_troficos', 'animales', 'Los niveles tróficos', 'Productores, consumidores primarios, secundarios y terciarios, y descomponedores cerrando el circuito.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.regla_del_diez', 'animales', 'La regla del 10 %', 'De un nivel al siguiente se transmite alrededor de una décima parte de la energía: por eso hay muchísimos herbívoros y muy pocos grandes depredadores.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.descomponedores', 'animales', 'Los que cierran el ciclo', 'Hongos, bacterias e invertebrados del suelo devuelven los nutrientes al sistema. Sin ellos, todo se detendría bajo una pila de restos.', null, (select id from ac_fuentes where slug = 'inta'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.bioacumulacion', 'animales', 'Bioacumulación', 'Algunas sustancias no se eliminan y se van juntando en el cuerpo de un organismo a lo largo de su vida.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.biomagnificacion', 'animales', 'Biomagnificación', 'Como cada nivel se come muchos individuos del anterior, esas sustancias se concentran cada vez más a medida que se sube en la red trófica.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.relaciones_interespecificas', 'animales', 'Las formas de convivir', 'Mutualismo (ganan los dos), comensalismo (uno gana y al otro le da igual), parasitismo (uno gana a costa del otro), competencia y depredación.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.polinizacion', 'animales', 'Polinización', 'Muchísimas plantas necesitan que un animal lleve el polen de una flor a otra: es un mutualismo del que depende buena parte de lo que comemos.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.polinizadores_nativos', 'animales', 'Los polinizadores nativos', 'Además de la abeja de miel están las abejas sin aguijón como la yateí y los abejorros nativos, que polinizan plantas que la abeja europea no toca.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.bombus_dahlbomii', 'animales', 'El abejorro patagónico', 'El Bombus dahlbomii, el abejorro nativo más grande de la Patagonia, retrocedió fuertemente tras la introducción de abejorros europeos para polinización comercial.', null, (select id from ac_fuentes where slug = 'invasoras-mayds'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.zoocoria', 'animales', 'Semillas que viajan en animales', 'Muchos frutos existen para que un animal se los coma y deje la semilla lejos: sin esos animales, la planta no se dispersa.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.murcielagos_urbanos', 'animales', 'Los murciélagos de tu barrio', 'Los murciélagos urbanos de Buenos Aires son insectívoros: comen miles de mosquitos por noche y se orientan por ecolocalización con una precisión extraordinaria.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.sapos_y_aranas', 'animales', 'Sapos y arañas trabajan gratis', 'Los sapos y las arañas de casa son depredadores de insectos: donde están ellos hay menos mosquitos, moscas y cucarachas.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.especie_clave', 'animales', 'Especie clave', 'Es la que tiene un efecto sobre el ecosistema mucho mayor que su abundancia: si se va, el sistema se reorganiza entero.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cascada_trofica', 'animales', 'Cascada trófica', 'Cuando cambia el nivel de arriba, el efecto baja por toda la red: sacar un depredador puede terminar cambiando la vegetación.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.top_down_bottom_up', 'animales', 'Desde arriba o desde abajo', 'Un sistema puede estar controlado por los depredadores (top-down) o por la disponibilidad de alimento y nutrientes (bottom-up). Casi siempre es una mezcla.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.ingenieros_del_ecosistema', 'animales', 'Ingenieros del ecosistema', 'Algunas especies modifican físicamente el ambiente y crean hábitat para otras: el carpincho abre caminos en el humedal, el tuco-tuco airea el suelo.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.paraguas_bandera', 'animales', 'Paraguas, bandera e indicadora', 'Una especie paraguas protege a muchas otras si se protege su territorio; una bandera moviliza apoyo; una indicadora avisa cómo está el ambiente.', 'El yaguareté es las tres cosas a la vez.', (select id from ac_fuentes where slug = 'rewilding-argentina'), 2, 0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.especies_indicadoras', 'animales', 'Bichos que miden el ambiente', 'Los líquenes, los anfibios y los macroinvertebrados de arroyo son sensibles a la contaminación: encontrarlos o no dice cómo está el lugar.', null, (select id from ac_fuentes where slug = 'argentinat'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.que_es_migrar', 'animales', 'Qué es migrar', 'Es moverse de forma regular entre dos zonas, siguiendo la comida o el clima, y volver. No es lo mismo que dispersarse una vez.', null, (select id from ac_fuentes where slug = 'aves-argentinas'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.playero_rojizo', 'animales', 'El playero rojizo', 'Viaja entre Tierra del Fuego y el Ártico canadiense todos los años, y depende de unos pocos sitios de descanso donde recupera peso.', null, (select id from ac_fuentes where slug = 'aves-argentinas-amenazadas'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.samborombon', 'animales', 'La bahía de Samborombón', 'Es una parada clave para chorlos y playeros migratorios: un humedal costero bonaerense del que depende gente que vuela medio continente.', null, (select id from ac_fuentes where slug = 'aves-argentinas'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.ballena_franca', 'animales', 'La ballena franca austral', 'Usa Península Valdés como área de cría y se alimenta mucho más al sur: su recuperación es uno de los grandes casos de éxito de conservación del país.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.eslabon_debil', 'animales', 'Una ruta vale lo que su eslabón más débil', 'Si se degrada un solo sitio de descanso, toda la ruta migratoria falla, aunque el resto esté perfecto.', null, (select id from ac_fuentes where slug = 'aves-argentinas'), 2, 0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.aves_porteñas', 'animales', 'Las aves que ya conocés', 'Hornero, benteveo, calandria, chingolo, zorzal, torcaza y cotorra son parte del paisaje sonoro de cualquier barrio del AMBA.', 'El hornero es el ave nacional argentina.', (select id from ac_fuentes where slug = 'ebird'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.rapaces_urbanas', 'animales', 'Las rapaces de la ciudad', 'Caranchos, chimangos, gavilanes mixtos y lechucitas vizcacheras viven y cazan dentro del área metropolitana.', null, (select id from ac_fuentes where slug = 'ebird'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.mamiferos_urbanos', 'animales', 'Mamíferos que no ves', 'La comadreja overa, el coipo y varios murciélagos viven en el AMBA. Son casi todos nocturnos, y por eso pasan desapercibidos.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.lagarto_overo', 'animales', 'El lagarto overo', 'Es el reptil más grande que vas a ver en la Reserva Ecológica: come de todo, toma sol para regular su temperatura y no es agresivo si lo dejás tranquilo.', null, (select id from ac_fuentes where slug = 'reserva-costanera-sur'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cotorra_es_nativa', 'animales', 'La cotorra es nativa', 'La cotorra (Myiopsitta monachus) es una especie nativa argentina, aunque sea abundante y a veces conflictiva. La paloma doméstica, el gorrión y el estornino son las introducidas.', null, (select id from ac_fuentes where slug = 'invasoras-mayds'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.sinantropia', 'animales', 'Especies que aprendieron a vivir con nosotros', 'Algunas especies prosperan justo donde hay gente, porque encuentran comida constante y pocos depredadores. Se las llama sinantrópicas.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.no_alimentar', 'animales', 'No se alimenta fauna silvestre', 'Darles de comer los vuelve dependientes, los junta en grupos donde se contagian enfermedades, les da una dieta que no les corresponde y los acostumbra a la gente.', 'Y esa costumbre casi siempre termina mal para el animal.', (select id from ac_fuentes where slug = 'protocolo-fauna-cba'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.volanton_vs_pichon', 'animales', 'Volantón y pichón no son lo mismo', 'Un volantón ya tiene plumas y está aprendiendo a volar: sus padres lo siguen alimentando en el suelo. Un pichón sin plumas sí necesita ayuda.', 'Ante un volantón, lo correcto es dejarlo donde está o subirlo a una rama cercana y alejar a las mascotas.', (select id from ac_fuentes where slug = 'protocolo-fauna-cba'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.animal_herido_que_hacer', 'animales', 'Si encontrás un animal silvestre herido', 'No lo manipules sin protección, no le des agua ni comida, ponelo en una caja de cartón ventilada, oscura y silenciosa, no lo muestres ni lo fotografíes de cerca, y contactá a la autoridad de fauna.', 'Si sos chico, la parte que te toca es avisarle a una persona adulta: la caja y el llamado los hace ella.', (select id from ac_fuentes where slug = 'protocolo-fauna-cba'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.centros_de_rescate', 'animales', 'A quién se llama', 'La Red Federal de Centros de Rescate articula los centros del país, y en la Ciudad de Buenos Aires funciona el Centro de Rescate de Fauna Silvestre del Ecoparque.', null, (select id from ac_fuentes where slug = 'red-centros-rescate'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.viboras_no_atacan', 'animales', 'Las serpientes no atacan', 'Una serpiente muerde para defenderse, no para agredir. La mayoría de las especies argentinas no son venenosas, y la respuesta correcta es alejarse.', 'Matarlas además es ilegal cuando la especie está protegida.', (select id from ac_fuentes where slug = 'ley-22421-fauna'), 1, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.apex_no_cazan_gente', 'animales', 'Los grandes depredadores evitan a la gente', 'Pumas, yaguaretés y tiburones esquivan a las personas. Los encuentros graves son rarísimos comparados con el miedo que les tenemos.', 'Y son especies clave: sacarlos desarma la estructura trófica entera.', (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.carpincho_quien_es', 'animales', 'Quién es el carpincho', 'Es el roedor vivo más grande del mundo: herbívoro, semiacuático y muy social. Vive en grupos y necesita agua cerca.', null, (select id from ac_fuentes where slug = 'conicet-carpinchos'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('animales.carpincho_ingeniero', 'animales', 'Lo que hace en el humedal', 'Al pastar y moverse abre caminos y mantiene abiertos espacios de agua: modifica el ambiente de un modo que otras especies aprovechan.', null, (select id from ac_fuentes where slug = 'conicet-carpinchos'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.nordelta', 'animales', 'Nordelta, al revés de como se cuenta', 'El barrio se construyó sobre el humedal donde los carpinchos ya vivían. No es una invasión de fauna: es un conflicto de uso del suelo.', null, (select id from ac_fuentes where slug = 'conicet-carpinchos'), 1, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.conflicto_es_de_uso', 'animales', 'Casi todo conflicto con fauna es de uso del suelo', 'Cuando un animal "aparece donde no debería", casi siempre lo que se movió fue el límite de lo construido, no el animal.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.biodiversidad_tres_niveles', 'animales', 'Biodiversidad en tres niveles', 'Diversidad genética dentro de una especie, diversidad de especies y diversidad de ecosistemas. Perder cualquiera de las tres empobrece el sistema.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.categorias_uicn', 'animales', 'Las categorías de la Lista Roja', 'EX, EW, CR, EN, VU, NT, LC, DD y NE. Las tres categorías de amenaza son En Peligro Crítico, En Peligro y Vulnerable.', null, (select id from ac_fuentes where slug = 'iucn-categorias'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.dd_no_es_esta_bien', 'animales', 'DD no significa "está bien"', 'Datos Insuficientes quiere decir que no sabemos. Algunas especies DD están entre las más comprometidas justamente porque nadie las evaluó.', null, (select id from ac_fuentes where slug = 'iucn-red-list'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.nacional_vs_global', 'animales', 'Nacional y global no coinciden', 'Una especie puede estar en Preocupación Menor a nivel mundial y En Peligro en la Argentina, porque acá su población es chica o está en el borde de su distribución.', null, (select id from ac_fuentes where slug = 'iucn-categorias'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.sarem_numeros', 'animales', 'Los mamíferos argentinos, en números', 'La categorización de SAREM de 2019 evaluó 417 especies de mamíferos nativos: 98 quedaron amenazadas y el 92,7 % enfrenta al menos una amenaza.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.aves_amenazadas_ar', 'animales', 'Las aves argentinas amenazadas', 'Alrededor del 12 % de las aves silvestres del país —113 especies— están amenazadas, frente a 80 en la década de 1990.', null, (select id from ac_fuentes where slug = 'aves-argentinas-amenazadas'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.perdida_de_habitat', 'animales', 'La amenaza número uno', 'La pérdida y degradación del hábitat afecta a cerca del 80 % de los mamíferos argentinos: está muy por encima de cualquier otra causa.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.3, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.fragmentacion', 'animales', 'Fragmentación y efecto borde', 'Partir un ambiente en pedazos aislados es peor que perder la misma superficie de una sola vez: quedan poblaciones chicas, separadas y con más borde expuesto.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.atropellamientos', 'animales', 'Atropellamientos en ruta', 'El 22 % de los mamíferos argentinos está afectado por atropellamientos: para varias especies es una de las principales causas de muerte.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.4, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.perros_y_gatos', 'animales', 'Perros y gatos domésticos', 'La depredación por perros afecta al 22 % de los mamíferos argentinos, un peso comparable al de los atropellamientos. Los gatos con acceso al exterior impactan sobre todo a las aves.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.especies_invasoras', 'animales', 'Especies exóticas invasoras', 'El castor en Tierra del Fuego, el visón americano, el jabalí, el ciervo colorado y el mejillón dorado están entre las que más transforman ambientes en la Argentina.', null, (select id from ac_fuentes where slug = 'invasoras-mayds'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.soltar_no_es_liberar', 'animales', 'Soltar una mascota no es liberarla', 'Es abandono, y además introduce especies y enfermedades. Tortugas, peces y conejos soltados "en la naturaleza" suelen morir o convertirse en un problema ecológico.', null, (select id from ac_fuentes where slug = 'invasoras-mayds'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.sintiencia', 'animales', 'Sentir es la base', 'Los animales sintientes pueden experimentar dolor, miedo y bienestar. Ese es el punto de partida de todo lo que sigue.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cinco_libertades', 'animales', 'Las cinco libertades', 'Libre de hambre y sed; libre de incomodidad; libre de dolor, lesión y enfermedad; libre para expresar comportamiento natural; libre de miedo y angustia.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cuidado_basico', 'animales', 'Lo que implica en la práctica', 'Identificación, vacunación antirrábica, desparasitación, paseo con correa, recolección de heces y no abandonar. Todo eso es parte de las cinco libertades, no un extra.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.castracion', 'animales', 'Castración', 'Es la herramienta ética de control poblacional: evita camadas que terminan en la calle y reduce varios problemas de salud.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.adoptar', 'animales', 'Adoptar antes que comprar', 'Adoptar le da lugar a un animal que ya existe y necesita hogar, en vez de generar demanda de una camada nueva.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.gato_puertas_adentro', 'animales', 'El gato, mejor adentro', 'Un gato con acceso libre al exterior caza aves y pequeños mamíferos aunque esté bien alimentado, y además vive menos.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.cinco_dominios', 'animales', 'De las cinco libertades a los cinco dominios', 'El modelo más nuevo no se conforma con evitar el sufrimiento: evalúa también si el animal tiene experiencias positivas.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 3, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.no_es_mascota', 'animales', 'Loros, tortugas y monos no son mascotas', 'La fauna silvestre tiene necesidades de espacio, dieta y comportamiento que una casa no puede cubrir, y en la Argentina su tenencia está regulada por ley.', null, (select id from ac_fuentes where slug = 'ley-22421-fauna'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.comprar_es_demanda', 'animales', 'Comprar no rescata: genera demanda', 'Cada animal comprado le avisa al circuito que hay mercado. Lo que corresponde es denunciar, no comprar.', null, (select id from ac_fuentes where slug = 'ley-22421-fauna'), 2, 0.4, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.cardenal_amarillo', 'animales', 'El cardenal amarillo', 'Está En Peligro y su principal amenaza es directamente el tráfico como ave de jaula, por su canto.', null, (select id from ac_fuentes where slug = 'aves-argentinas-amenazadas'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.cites', 'animales', 'CITES', 'Regula el comercio internacional de especies con tres apéndices: el I prohíbe el comercio con fines comerciales, el II lo permite bajo permiso y el III lista especies protegidas por un país.', null, (select id from ac_fuentes where slug = 'cites'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.leyes_fauna_ar', 'animales', 'Las leyes que aplican acá', 'La Ley 22.421 declara de interés público la conservación de la fauna y regula caza, transporte y comercio; la Ley 14.346 penaliza el maltrato animal.', null, (select id from ac_fuentes where slug = 'ley-22421-fauna'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.como_denunciar', 'animales', 'Cómo se denuncia', 'Se avisa a la autoridad de fauna con lugar, fecha y foto si se puede sacar sin exponerse. No hay que intentar rescatar por cuenta propia.', null, (select id from ac_fuentes where slug = 'red-centros-rescate'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.rewilding', 'animales', 'Qué es el rewilding', 'Es devolver a un ecosistema las especies que perdió, para que vuelvan a cumplir su función, y no solo para que estén.', null, (select id from ac_fuentes where slug = 'rewilding-argentina'), 3, 0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.etapas_reintroduccion', 'animales', 'Las etapas de una reintroducción', 'Cría, corral de presuelta para que aprendan el lugar, liberación, y monitoreo por años. Saltearse una etapa es perder los animales.', null, (select id from ac_fuentes where slug = 'rewilding-argentina'), 3, 0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.guacamayo_rojo', 'animales', 'El guacamayo rojo volvió', 'Estuvo extinto en la Argentina por más de 150 años y fue reintroducido en Iberá: hoy vuelve a volar sobre los esteros.', null, (select id from ac_fuentes where slug = 'rewilding-argentina'), 3, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.yaguarete_ibera', 'animales', 'El yaguareté en Iberá', 'Es Monumento Natural Nacional y está En Peligro Crítico en la Argentina, con núcleos en Selva Paranaense, Yungas y Chaco, más las reintroducciones de Iberá y El Impenetrable.', null, (select id from ac_fuentes where slug = 'rewilding-argentina'), 3, 0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.ex_situ_in_situ', 'animales', 'Ex situ e in situ', 'Conservar in situ es proteger a la especie donde vive; ex situ es hacerlo fuera, en centros de cría. La segunda tiene sentido como apoyo de la primera, no como reemplazo.', null, (select id from ac_fuentes where slug = 'ecoparque-conservacion'), 3, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.corredores_y_pasafaunas', 'animales', 'Corredores y pasafaunas', 'Conectar parches de ambiente permite que las poblaciones se mezclen; un pasafauna sobre una ruta reduce atropellamientos y reconecta lo que la ruta separó.', null, (select id from ac_fuentes where slug = 'sarem-2019'), 2, 0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.zoologicos_debate', 'animales', 'Zoológicos: el debate', 'Instituciones como el Ecoparque o Temaikèn hacen cría, rescate e investigación reales. La discusión ética sobre el cautiverio también es real, y las dos cosas conviven.', 'Acá no hay veredicto: hay un debate con argumentos de los dos lados.', (select id from ac_fuentes where slug = 'ecoparque-conservacion'), 3, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('animales.ecoparque', 'animales', 'Del Zoológico al Ecoparque', 'El antiguo Zoológico de Buenos Aires se transformó en Ecoparque, con programas de conservación y el traslado de animales a santuarios y centros de referencia.', null, (select id from ac_fuentes where slug = 'ecoparque-conservacion'), 3, 0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('animales.uso_sustentable', 'animales', 'Uso sustentable: el caso del yacaré', 'El Proyecto Yacaré usó el aprovechamiento regulado para darle valor a la especie y a su humedal, y las poblaciones se recuperaron. Es un modelo que se discute y que en este caso funcionó.', null, (select id from ac_fuentes where slug = 'sib-apn'), 3, 0.9, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.animales_de_produccion', 'animales', 'Animales de producción', 'El bienestar en los sistemas productivos —espacio, transporte, faena— es un campo con normas propias y con discusión abierta sobre cuánto alcanzan.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 3, 0.8, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.tres_erres_experimentacion', 'animales', 'Las 3R de la experimentación', 'Reemplazar el uso de animales cuando se puede, reducir la cantidad al mínimo necesario y refinar los procedimientos para que sufran menos.', null, (select id from ac_fuentes where slug = 'gcba-cinco-libertades'), 3, 0.8, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('animales.one_health', 'animales', 'Una sola salud', 'La salud humana, la animal y la de los ecosistemas son el mismo problema: la mayoría de las enfermedades emergentes vienen de ese cruce.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 3, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.registro_completo', 'ciencia', 'Qué, dónde, cuándo y quién', 'Una observación sirve como dato cuando dice qué se vio, dónde, cuándo y quién la registró. Sin esos cuatro campos es una anécdota.', null, (select id from ac_fuentes where slug = 'gbif'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.darwin_core', 'ciencia', 'Darwin Core', 'Es el estándar que define esos campos mínimos para que un registro hecho en Berazategui se pueda combinar con uno hecho en Noruega.', null, (select id from ac_fuentes where slug = 'gbif'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.foto_testigo', 'ciencia', 'La foto testigo', 'Una foto convierte tu identificación en algo que otra persona puede revisar: por eso los registros con imagen valen más que los que solo tienen un nombre.', null, (select id from ac_fuentes where slug = 'argentinat'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.esfuerzo_de_observacion', 'ciencia', 'Cuánto miraste también es dato', 'Anotar cuánto tiempo estuviste buscando cambia todo: "cero golondrinas en dos horas" dice algo; "cero golondrinas" no dice nada.', null, (select id from ac_fuentes where slug = 'ebird'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.que_es_ciencia_ciudadana', 'ciencia', 'Qué es la ciencia ciudadana', 'Es investigación real hecha con datos que aporta cualquiera: la escala que consigue un grupo grande de personas no la consigue ningún equipo solo.', null, (select id from ac_fuentes where slug = 'argentinat'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.argentinat', 'ciencia', 'ArgentiNat', 'Cargás una foto con fecha y lugar, la comunidad ayuda a identificarla, y si alcanza consenso el registro pasa a calidad investigativa y llega a GBIF.', null, (select id from ac_fuentes where slug = 'argentinat'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.ebird_y_coas', 'ciencia', 'eBird y los COA', 'Los Clubes de Observadores de Aves de Aves Argentinas salen a campo con protocolo y cargan sus listados en eBird: la Reserva Ecológica es uno de los sitios más registrados del país.', null, (select id from ac_fuentes where slug = 'ebird'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.censos_coordinados', 'ciencia', 'Los censos coordinados', 'Cuando mucha gente cuenta lo mismo el mismo día —como en el Censo Neotropical de Aves Acuáticas— se obtiene una foto simultánea imposible de conseguir de otra forma.', null, (select id from ac_fuentes where slug = 'aves-argentinas'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.gbif_agrega', 'ciencia', 'Dónde termina tu registro', 'GBIF junta registros de todo el mundo publicados con el mismo estándar, y ahí es donde tu observación de una plaza puede entrar en un estudio.', null, (select id from ac_fuentes where slug = 'gbif'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.bioindicadores', 'ciencia', 'Bichos que miden', 'Algunos organismos solo viven donde se cumplen ciertas condiciones: encontrarlos —o no— dice cómo está el ambiente sin necesidad de un laboratorio.', 'Los líquenes indican calidad de aire; los macroinvertebrados, calidad de agua.', (select id from ac_fuentes where slug = 'argentinat'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.camaras_trampa', 'ciencia', 'Cámaras trampa', 'Una cámara que se dispara con el movimiento registra fauna esquiva sin que nadie esté presente, y de noche.', null, (select id from ac_fuentes where slug = 'sib-apn'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.bioacustica', 'ciencia', 'Escuchar en vez de mirar', 'Grabar el paisaje sonoro permite identificar especies por su canto, incluso las que nunca se dejan ver.', null, (select id from ac_fuentes where slug = 'sib-apn'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.edna', 'ciencia', 'ADN ambiental', 'Un litro de agua de un arroyo lleva rastros de ADN de casi todo lo que pasó por ahí: se puede saber qué especies hay sin ver ni capturar ninguna.', null, (select id from ac_fuentes where slug = 'gbif'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.teledeteccion', 'ciencia', 'Mirar desde arriba', 'Las imágenes satelitales permiten seguir el desmonte, los incendios o la sequía en el tiempo, y comparar el mismo lugar entre dos fechas.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.ejes_y_escalas', 'ciencia', 'Mirá los ejes', 'Un eje que no arranca en cero, o una escala logarítmica sin avisar, cambian por completo la forma de una curva sin cambiar un solo dato.', null, (select id from ac_fuentes where slug = 'chequeado'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.serie_vs_punto', 'ciencia', 'Una serie, no un punto', 'Un dato aislado casi nunca significa algo: lo que informa es la serie, porque muestra si eso es lo normal o la excepción.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.barras_de_error', 'ciencia', 'Las barras de error', 'Una barra de error dice cuánta confianza hay en el número. Un dato con barras es más honesto que uno sin ellas, no menos confiable.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.muestreo_y_sesgo', 'ciencia', 'A quién mediste', 'Si la muestra no representa a la población, el resultado describe a la muestra y a nadie más. En ciencia ciudadana el sesgo típico es medir donde es cómodo llegar.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.revision_por_pares', 'ciencia', 'Revisión por pares', 'Antes de publicarse, un trabajo lo revisan especialistas que no participaron. No garantiza que sea correcto: garantiza que pasó por un filtro.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.preprint', 'ciencia', 'Preprint', 'Un preprint es un trabajo publicado antes de la revisión: es útil para ir rápido y hay que leerlo sabiendo que todavía no pasó el filtro.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('ciencia.replica', 'ciencia', 'Que se pueda repetir', 'Un resultado vale más cuando otro equipo, con otros datos, llega a lo mismo. La réplica es lo que separa un hallazgo de una casualidad.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.atribucion_climatica', 'ciencia', 'Cómo se sabe que es nuestro', 'La atribución compara lo que se observa con modelos que corren con y sin emisiones humanas: la diferencia entre esos dos mundos es la evidencia.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 3, 0.9, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.escenarios_ssp', 'ciencia', 'Los escenarios no son predicciones', 'Un escenario climático dice "si pasa esto, entonces aquello". No predice el futuro: describe consecuencias de decisiones que todavía no se tomaron.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 3, 0.8, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.fabricar_duda', 'ciencia', 'Fabricar duda', 'No hace falta convencer a nadie de lo contrario: alcanza con instalar que "todavía se discute" para frenar cualquier decisión.', null, (select id from ac_fuentes where slug = 'chequeado'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.cherry_picking', 'ciencia', 'Elegir el pedacito que conviene', 'Recortar una serie larga justo donde la curva hace lo que uno quiere es la técnica más común y la más fácil de detectar: pedí la serie completa.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.falso_equilibrio', 'ciencia', 'Falso equilibrio', 'Poner a dos personas a discutir de igual a igual sugiere que la evidencia está repartida mitad y mitad, aunque no lo esté.', null, (select id from ac_fuentes where slug = 'chequeado'), 2, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.como_verificar', 'ciencia', 'Cómo verificar en cinco minutos', 'Buscá la fuente primaria, fijate la fecha, mirá si alguien independiente lo verificó y preguntate a quién le conviene que lo creas.', null, (select id from ac_fuentes where slug = 'chequeado'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.pregunta_investigable', 'ciencia', 'Una pregunta investigable', 'Una buena pregunta se puede responder con algo que puedas medir. "¿Está mal el río?" no; "¿cuántos macroinvertebrados hay por muestra en estos dos puntos?" sí.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.variable_y_control', 'ciencia', 'Variable y control', 'Para saber si algo influye hay que compararlo contra un caso igual donde eso no pasa. Sin control, no sabés si el cambio lo causó lo que vos hiciste.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.precision_vs_exactitud', 'ciencia', 'Precisión y exactitud', 'Precisión es que las mediciones se parezcan entre sí; exactitud es que se parezcan al valor real. Se puede ser muy preciso y estar sistemáticamente equivocado.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('ciencia.mostrar_resultados', 'ciencia', 'Mostrar lo que encontraste', 'Un resultado se comunica con el método adelante: qué mediste, cómo, cuántas veces y qué no pudiste controlar. Eso es lo que lo vuelve creíble.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.bien_comun', 'comunidad', 'El bien común', 'Hay cosas que no son de nadie en particular y son de todos a la vez: el aire, una plaza, el agua de un río.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -1.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.tragedia_de_los_comunes', 'comunidad', 'La tragedia de los comunes', 'Si cada persona usa un recurso compartido pensando solo en su propio beneficio, el recurso se agota aunque a nadie le convenga que se agote.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.ostrom', 'comunidad', 'Y cómo se evita', 'La tragedia no es inevitable: las comunidades que se ponen reglas propias, se controlan entre sí y pueden sancionar, gestionan recursos comunes durante generaciones.', 'Es el trabajo por el que Elinor Ostrom ganó el Nobel de Economía.', (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.reglas_que_funcionan', 'comunidad', 'Reglas que funcionan', 'Una regla ambiental funciona cuando quienes la cumplen participaron en escribirla, la pueden monitorear y ven que a quien no la cumple le pasa algo.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.quien_hace_que', 'comunidad', 'Quién hace qué', 'La recolección, el arbolado y el alumbrado suelen ser municipales o comunales; el agua y las cloacas, de una empresa o ente; los parques nacionales, de Nación. Saber a quién le corresponde es la mitad del reclamo.', null, (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.como_se_reclama', 'comunidad', 'Cómo se hace un reclamo', 'Un reclamo sirve más cuando tiene lugar exacto, fecha, foto y número de seguimiento: eso lo vuelve rastreable y comparable con otros.', 'En la Ciudad de Buenos Aires ese canal es el 147.', (select id from ac_fuentes where slug = 'ley-25831-info'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.comuna_y_junta', 'comunidad', 'La comuna y su junta', 'En la Ciudad de Buenos Aires las comunas tienen juntas comunales electas, con reuniones abiertas donde se pueden llevar temas del barrio.', null, (select id from ac_fuentes where slug = 'ley-25831-info'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.presupuesto_participativo', 'comunidad', 'Presupuesto participativo', 'Algunos municipios dejan que los vecinos decidan en qué se gasta una parte del presupuesto, y ahí entran plazas, arbolado y separación de residuos.', null, (select id from ac_fuentes where slug = 'ley-25831-info'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.acceso_informacion_25831', 'comunidad', 'La Ley 25.831', 'Cualquier persona puede pedirle al Estado información ambiental, sin explicar para qué la quiere y sin acreditar ningún interés.', null, (select id from ac_fuentes where slug = 'ley-25831-info'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.escazu_tres_derechos', 'comunidad', 'Los tres derechos de Escazú', 'El Acuerdo de Escazú garantiza tres cosas juntas: acceso a la información ambiental, participación en las decisiones y acceso a la justicia.', null, (select id from ac_fuentes where slug = 'escazu'), 1, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.defensores_ambientales', 'comunidad', 'Quienes defienden el ambiente', 'Escazú es el primer acuerdo del mundo con obligaciones específicas de protección para las personas que defienden derechos humanos en asuntos ambientales.', null, (select id from ac_fuentes where slug = 'escazu'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('comunidad.datos_abiertos', 'comunidad', 'Datos abiertos', 'Organismos como ACUMAR publican sus mediciones en portales abiertos: cualquiera puede bajar la serie y mirarla por su cuenta.', null, (select id from ac_fuentes where slug = 'acumar'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.huerta_comunitaria', 'comunidad', 'La huerta comunitaria', 'Una huerta compartida produce comida, pero sobre todo produce vecinos que se conocen: es de las formas más rápidas de armar red en un barrio.', null, (select id from ac_fuentes where slug = 'inta'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.compost_comunitario', 'comunidad', 'Compostaje comunitario', 'Una compostera de manzana o de edificio saca del relleno la fracción más pesada de la basura y devuelve tierra a las macetas del barrio.', null, (select id from ac_fuentes where slug = 'ley-1854-basura-cero'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.cooperativas_recuperadores', 'comunidad', 'Las cooperativas de recuperadores', 'En la Ciudad de Buenos Aires los Centros Verdes los operan cooperativas de recuperadores urbanos: son parte del sistema formal de reciclado, no algo aparte.', null, (select id from ac_fuentes where slug = 'faccyr'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.jornadas_de_limpieza', 'comunidad', 'Las jornadas de limpieza', 'Una limpieza de costa o de plaza sirve el doble si además se registra qué se encontró: eso convierte una tarde de trabajo en un dato.', null, (select id from ac_fuentes where slug = 'unep'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.audiencia_publica', 'comunidad', 'La audiencia pública', 'Antes de aprobar obras o normas de impacto ambiental hay instancias donde cualquiera puede inscribirse y exponer. Lo que se dice queda registrado y hay que responderlo.', 'No es vinculante, y eso también es parte de entenderla.', (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.evaluacion_impacto', 'comunidad', 'Evaluación de impacto ambiental', 'Un proyecto grande tiene que estimar sus impactos antes de hacerse, y ese estudio es público: es el documento sobre el que se discute en la audiencia.', null, (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.amparo_ambiental', 'comunidad', 'El amparo ambiental', 'Cuando un daño ambiental afecta a un colectivo, la ley permite que alguien reclame en nombre de todos: el bien afectado es común, así que la legitimación también.', null, (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 2, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.fallo_mendoza_caso', 'comunidad', 'El fallo Mendoza como caso testigo', 'En 2008 la Corte Suprema ordenó sanear la Cuenca Matanza-Riachuelo y creó una autoridad tripartita para hacerlo: ACUMAR nació de una sentencia.', null, (select id from ac_fuentes where slug = 'acumar'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.quien_pone_el_cuerpo', 'comunidad', 'Quién pone el cuerpo', 'Los basurales, las industrias contaminantes y las zonas inundables casi nunca están donde vive quien decide: el costo ambiental suele caer sobre los barrios más pobres.', null, (select id from ac_fuentes where slug = 'acumar'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('comunidad.pueblos_indigenas_consulta', 'comunidad', 'Consulta previa, libre e informada', 'Cuando un proyecto afecta territorios de pueblos indígenas, el Convenio 169 de la OIT exige consultarlos antes, con información completa y sin presión.', null, (select id from ac_fuentes where slug = 'ley-27621-eai'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.saberes_locales', 'comunidad', 'Los saberes que ya estaban', 'La Ley 27.621 incorpora explícitamente los saberes de los pueblos indígenas a la educación ambiental: no como folclore, como conocimiento.', null, (select id from ac_fuentes where slug = 'ley-27621-eai'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.asambleas_socioambientales', 'comunidad', 'Las asambleas socioambientales', 'En la Argentina hay una tradición larga de asambleas vecinales que se organizan alrededor de un conflicto ambiental concreto y sostienen el reclamo por años.', null, (select id from ac_fuentes where slug = 'escazu'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.un_pedido_concreto', 'comunidad', 'Un pedido concreto', 'Una campaña necesita un pedido que alguien identificable pueda conceder: "más conciencia" no se puede firmar, "tres cestos en la plaza" sí.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.mapeo_colectivo', 'comunidad', 'Mapeo colectivo', 'Marcar entre varios lo que pasa en un territorio —basurales, faltantes de arbolado, zonas que se inundan— produce evidencia que antes no existía.', null, (select id from ac_fuentes where slug = 'argentinat'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.alianzas', 'comunidad', 'Escuela, barrio y municipio', 'Las campañas que prosperan suelen combinar tres actores: quien tiene el problema, quien tiene la legitimidad y quien tiene la firma.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.eficacia_colectiva', 'comunidad', 'La eficacia colectiva', 'Sentir que un grupo puede lograr algo es lo que sostiene la acción en el tiempo, y es el mejor antídoto que se conoce contra la angustia ambiental.', 'La investigación sobre eco-ansiedad es clara: la agencia y la acción colectiva protegen; el discurso de catástrofe paraliza.', (select id from ac_fuentes where slug = 'ecoansiedad-review'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('comunidad.sentir_y_seguir', 'comunidad', 'Que te importe está bien', 'Preocuparse por esto es una respuesta razonable, no un problema personal. Nombrarlo, compartirlo y hacer algo concreto con otros es lo que lo vuelve llevadero.', null, (select id from ac_fuentes where slug = 'ecoansiedad-review'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.necesidad_vs_deseo', 'consumo', 'Necesidad y deseo no son lo mismo', 'Una necesidad es algo que te falta para vivir bien; un deseo es algo que querés tener. Separar las dos cosas antes de comprar es la decisión ambiental más barata que existe.', 'No se trata de no desear nada. Se trata de saber cuál de las dos está manejando el changuito.', (select id from ac_fuentes where slug = 'unesco-ods'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.publicidad_y_deseo', 'consumo', 'El ciclo del deseo', 'La publicidad no vende solo objetos: fabrica ganas nuevas cada temporada, y esas ganas se apagan al poco tiempo de comprar.', 'Reconocer el ciclo —ganas, compra, alivio corto, ganas nuevas— no te vuelve inmune, pero te da un segundo de ventaja.', (select id from ac_fuentes where slug = 'unesco-ods'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.la_compra_evitada', 'consumo', 'La compra que no hacés', 'Lo que no se fabrica no gasta materiales, agua ni energía: por eso, en la jerarquía de decisiones, la opción de menor impacto casi siempre es la compra que no llegás a hacer.', 'Reciclar viene tercero. Primero está no necesitarlo, y después usar menos.', (select id from ac_fuentes where slug = 'yale-reciclaje'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.usar_lo_que_ya_tenes', 'consumo', 'Lo que ya está en tu casa', 'El objeto con menos huella suele ser el que ya tenés: cada vez que alargás su uso, evitás que se fabrique otro.', 'Vale para la campera del año pasado, la mochila que te queda del hermano y el celular que todavía anda.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.vida_util', 'consumo', 'Cuánto sirve de verdad', 'La vida útil es cuánto tiempo un objeto sirve de verdad; no siempre coincide con lo que dura la garantía, ni con lo que dura de moda.', null, (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.obsolescencia_programada', 'consumo', 'Diseñado para durar poco', 'Hay productos pensados para fallar o quedar desactualizados a los pocos años: una vida útil corta no siempre es mala suerte, a veces es diseño.', 'La contracara también existe: hay fábricas que compiten justamente por durar, y eso se puede elegir.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.obsolescencia_percibida', 'consumo', 'Anda bien, pero parece viejo', 'La obsolescencia percibida no rompe nada: te convence de que lo que tenés quedó viejo aunque funcione perfecto.', 'Cambia el color, el borde o el nombre del modelo. El aparato es el mismo.', (select id from ac_fuentes where slug = 'unesco-ods'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.costo_por_uso', 'consumo', 'El precio dividido por los usos', 'Dividí el precio por la cantidad de veces que lo vas a usar: ese número compara dos productos mucho mejor que el número de la etiqueta.', 'Una campera cara que usás cientos de veces puede salir menos por uso que una barata que usás tres.', (select id from ac_fuentes where slug = 'unesco-ods'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.derecho_a_reparar', 'consumo', 'Derecho a reparar', 'El derecho a reparar es que quien compra algo pueda arreglarlo: con repuestos disponibles, manuales abiertos y alguien más que el service oficial.', 'Un objeto que se abre con un destornillador común vive mucho más que uno pegado.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.fast_fashion', 'consumo', 'Moda rápida', 'La moda rápida saca colecciones nuevas todo el tiempo y a precio bajo: se compra más ropa, se la usa menos veces y se la descarta antes.', null, (select id from ac_fuentes where slug = 'unep'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.microfibras_lavado', 'consumo', 'Lo que suelta el lavarropas', 'Cada lavado de una prenda sintética suelta microfibras plásticas diminutas que se van con el agua por la cloaca.', 'Lavar con la carga llena y menos seguido suelta menos fibras, y de paso gasta menos agua.', (select id from ac_fuentes where slug = 'unep'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.ropa_segunda_mano', 'consumo', 'Ropa que sigue circulando', 'Una prenda que pasa a otra persona —feria americana, intercambio con amigas, herencia entre primos— sigue dando servicio sin que se fabrique una nueva.', 'Un intercambio de ropa con tu curso o tu edificio mueve decenas de prendas en una tarde.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.trazabilidad_ropa', 'consumo', 'Quién hizo tu remera', 'Casi ninguna etiqueta cuenta en qué taller y en qué condiciones se cosió la prenda: la trazabilidad es poder seguir esa cadena hasta el principio.', 'Preguntarle a la marca dónde se cose es una pregunta legítima y barata.', (select id from ac_fuentes where slug = 'unep'), 1, -0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.talleres_textiles_amba', 'consumo', 'El precio que no está en la etiqueta', 'En el AMBA se documentaron talleres textiles clandestinos donde se cose ropa en condiciones de trabajo forzado: parte de lo que abarata una prenda pasa por ahí.', 'Hay marcas que publican su lista de talleres. Que se pueda pedir esa lista ya cambia algo aguas arriba.', (select id from ac_fuentes where slug = 'chequeado'), 1, -0.2, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('consumo.huella_ecologica', 'consumo', 'La huella ecológica', 'La huella ecológica estima cuánta superficie de planeta hace falta para sostener una forma de vivir, y la compara con la superficie que hay disponible.', 'Es una estimación, no una balanza exacta. Sirve para comparar, no para retar a nadie.', (select id from ac_fuentes where slug = 'global-footprint'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.dia_de_sobregiro', 'consumo', 'El Día de Sobregiro de la Tierra', 'El Día de Sobregiro de la Tierra es la fecha en la que la humanidad ya usó todo lo que el planeta regenera en un año; lo que sigue se toma prestado.', 'Cada país tiene su propia fecha, y la fecha se mueve: es un número que se puede empujar para adelante.', (select id from ac_fuentes where slug = 'global-footprint'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.huella_de_materiales', 'consumo', 'Los kilos que no ves', 'Detrás de cada objeto hay materiales que nunca aparecen en la caja: lo que se extrajo, se movió y se descartó para poder fabricarlo.', 'Por eso un objeto chico puede arrastrar una mochila enorme de materiales.', (select id from ac_fuentes where slug = 'unep'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.cambiar_material_no_alcanza', 'consumo', 'Cambiar el material no arregla el descartable', 'Si un objeto se sigue usando una sola vez, cambiarle el material lo mejora poco: lo que más pesa es cuántas veces se usa antes de tirarlo.', 'Por eso la bolsa que gana no es la de tal o cual material, sino la que volvés a llevar en la mochila decenas de veces.', (select id from ac_fuentes where slug = 'unep'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.greenwashing', 'consumo', 'Qué es el greenwashing', 'Greenwashing es cuando una marca invierte más en parecer sustentable que en serlo, y la comunicación tapa lo que el producto no cambió.', null, (select id from ac_fuentes where slug = 'unep'), 2, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.pecados_del_greenwashing', 'consumo', 'Las costuras de una promesa verde', 'Los anuncios verdes engañosos se repiten en pocas formas: el falso trade-off, la falta de prueba, la vaguedad, la irrelevancia, la mentira, el sello inventado y el "mal menor".', 'La vaguedad es la más común: "ecológico", "natural" o "verde" no dicen nada si no aclaran respecto de qué.', (select id from ac_fuentes where slug = 'unep'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('consumo.sellos_y_certificaciones', 'consumo', 'El sello y quién lo firma', 'Un sello vale por quién lo audita: hay certificaciones con criterios públicos y control de un tercero independiente, y hay dibujitos verdes que la marca se puso sola.', 'Buscá el nombre del que certifica. Si no aparece, ya sabés bastante.', (select id from ac_fuentes where slug = 'unep'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.promesas_a_futuro', 'consumo', 'Prometer para dentro de veinte años', 'Una promesa de neutralidad para dentro de décadas no cambia lo que se emite hoy, y compensar en otro lado no es lo mismo que dejar de emitir.', 'La pregunta útil es corta: ¿qué baja este año, y quién lo verifica?', (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.consumo_colaborativo', 'consumo', 'Compartir en vez de duplicar', 'Muchos objetos que compramos se usan unas pocas horas al año: compartirlos, prestarlos o alquilarlos da el mismo servicio con muchas menos cosas fabricadas.', 'El taladro es el ejemplo clásico: se compra para hacer unos pocos agujeros.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.biblioteca_de_objetos', 'consumo', 'Una biblioteca, pero de cosas', 'Una biblioteca de objetos presta herramientas, ollas grandes o carpas como una biblioteca presta libros: una sola compra le sirve a todo un barrio.', 'Se arranca simple: una lista compartida en el grupo del edificio o del curso ya es una.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.servitizacion', 'consumo', 'Producto como servicio', 'Cuando pagás por el uso y no por el objeto, el fabricante sigue siendo el dueño: le conviene que dure, que se pueda reparar y que después vuelva.', 'Es el modelo de las bicis y los monopatines de alquiler, y también el de alquilar herramientas grandes.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.suficiencia', 'consumo', '¿Cuánto alcanza?', 'La suficiencia es preguntarse cuánto alcanza en vez de cuánto se puede: no es privarse, es elegir la cantidad que hace falta.', 'Minimalismo y decrecimiento no son sinónimos: uno habla de tu casa, el otro discute el tamaño de una economía.', (select id from ac_fuentes where slug = 'unesco-ods'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.economia_circular', 'consumo', 'Los tres principios', 'La economía circular propone tres cosas a la vez: eliminar residuos y contaminación desde el diseño, mantener productos y materiales en uso, y regenerar la naturaleza.', 'No es reciclar más: es diseñar para que el residuo no aparezca, y reciclar cuando ya no queda otra.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, -0.1, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.ciclos_tecnico_y_biologico', 'consumo', 'Dos ciclos que no se mezclan', 'En el ciclo biológico los materiales vuelven a la tierra y se compostan; en el técnico circulan entre productos sin degradarse. Un objeto que pega los dos y no se puede separar arruina los dos caminos.', 'El envase de papel con película plástica es el caso típico.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.cadena_de_suministro', 'consumo', 'La cadena detrás del objeto', 'Entre la mina y la góndola hay una cadena larga de países, fábricas y transportes; la trazabilidad es poder ver esa cadena en vez de imaginarla.', null, (select id from ac_fuentes where slug = 'unep'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('consumo.minerales_de_conflicto', 'consumo', 'Minerales en zonas de conflicto', 'Parte de los minerales que llevan los aparatos electrónicos se extrae en zonas con conflicto armado, y esa venta puede financiar a los grupos que pelean.', 'Por eso alargar la vida de un celular no es solo ahorro: es demanda de extracción que no se pide.', (select id from ac_fuentes where slug = 'unep'), 2, 0.6, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('digital.que_es_un_centro_de_datos', 'digital', 'Qué es un centro de datos', 'Un centro de datos es un galpón lleno de computadoras encendidas todo el día, con su propio sistema de refrigeración y su propia conexión eléctrica.', 'Cuando algo "está en la nube", está ahí.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -1.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.la_electricidad_de_la_nube', 'digital', 'La electricidad de la nube', 'La IEA proyecta que la demanda eléctrica de los centros de datos se duplique hacia 2030, hasta alrededor de 945 TWh: algo menos del 3 % de la electricidad mundial.', 'Es mucho y es poco a la vez, y las dos cosas importan para decidir dónde poner el esfuerzo.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.refrigerar_cuesta', 'digital', 'Refrigerar también cuesta', 'Una parte importante de la energía de un centro de datos no se va en calcular: se va en sacarle el calor a las máquinas que calculan.', null, (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.pue', 'digital', 'PUE: cuánta energía se va en lo que no calcula', 'El PUE compara toda la energía que entra a un centro de datos con la que llega efectivamente a los servidores. Cuanto más cerca de 1, menos se pierde en refrigeración y pérdidas.', null, (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.carbono_embebido', 'digital', 'El carbono que ya viene adentro', 'En un celular, la mayor parte de la huella de carbono se generó fabricándolo, no usándolo.', 'Extraer los minerales, refinarlos, fabricar los chips y armarlo pesan más que años de uso.', (select id from ac_fuentes where slug = 'carbon-brief'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.alargar_la_vida_util', 'digital', 'Alargar la vida útil es la acción digital más fuerte', 'Como el grueso del impacto está en la fabricación, usar el mismo teléfono dos años más pesa mucho más que cualquier ahorro durante el uso.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.reparar_y_bateria', 'digital', 'La batería es lo primero que se muere', 'En muchos dispositivos lo que falla primero es la batería, y cambiarla cuesta una fracción de lo que cuesta —en plata y en materiales— comprar uno nuevo.', null, (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.raee', 'digital', 'RAEE: la basura electrónica', 'Los residuos de aparatos eléctricos y electrónicos tienen metales valiosos y también sustancias peligrosas: no van al tacho común.', null, (select id from ac_fuentes where slug = 'unep'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.mineria_urbana', 'digital', 'Minería urbana', 'Recuperar metales de aparatos viejos suele requerir menos energía que extraerlos de una mina, y evita abrir una mina nueva.', null, (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.minerales_criticos', 'digital', 'Litio, cobalto y compañía', 'Los aparatos electrónicos dependen de minerales cuya extracción tiene costos ambientales y sociales concretos en los lugares donde se saca.', null, (select id from ac_fuentes where slug = 'unep'), 2, 0.5, '{"teen","adult"}'::text[], true, 'aprobado'),
  ('digital.el_email_no_es_el_problema', 'digital', 'El correo no es el problema', 'La huella de un correo individual es despreciable frente a la fabricación de dispositivos y a la electricidad de los centros de datos.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.streaming_y_resolucion', 'digital', 'Streaming: la resolución y la red', 'Mirar en resolución más baja y por wifi en vez de datos móviles reduce el consumo asociado, aunque el efecto por hora sigue siendo modesto.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 1, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.datos_zombis', 'digital', 'Datos zombis', 'Muchos archivos guardados en la nube no se abren nunca más, pero se siguen replicando y ocupando espacio encendido.', null, (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.modo_oscuro', 'digital', 'El modo oscuro (y su tamaño real)', 'En pantallas OLED el modo oscuro ahorra algo de energía, pero es un efecto chico: sirve como ejemplo de escala, no como estrategia.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.brecha_digital', 'digital', 'La brecha digital', 'No todo el mundo tiene la misma conexión ni los mismos dispositivos, y eso cambia quién puede estudiar, trabajar o hacer un trámite.', null, (select id from ac_fuentes where slug = 'unesco-ods'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('digital.donde_se_instalan', 'digital', 'Dónde se instalan los centros de datos', 'Un centro de datos necesita electricidad barata, agua para refrigerar y terreno: esas tres cosas hacen que su instalación sea una discusión local.', null, (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.diseno_web_liviano', 'digital', 'Diseño web sostenible', 'Una página liviana carga más rápido, gasta menos batería y funciona en conexiones peores: la eficiencia y el acceso van juntos.', null, (select id from ac_fuentes where slug = 'unesco-ods'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.derecho_a_desconectar', 'digital', 'Desconectar también cuenta', 'El diseño que empuja a usar más —notificaciones, autoplay, rachas— tiene un costo de atención, y decidir cuándo apagar es parte de un uso consciente.', null, (select id from ac_fuentes where slug = 'unesco-ods'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.entrenar_vs_usar', 'digital', 'Entrenar y usar no cuestan igual', 'Entrenar un modelo grande concentra un gasto energético alto una vez; usarlo gasta poco por consulta pero se multiplica por millones de consultas.', null, (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.agua_de_refrigeracion', 'digital', 'El agua de refrigerar', 'Muchos centros de datos usan agua para refrigerar, y eso los pone a competir por un recurso local que puede estar bajo estrés.', null, (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.cripto_pow_pos', 'digital', 'Proof-of-work y proof-of-stake', 'Algunas criptomonedas gastan energía a propósito para validar transacciones; otras cambiaron ese mecanismo por uno que consume órdenes de magnitud menos.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.eficiencia_y_rebote', 'digital', 'Chips más eficientes, más cómputo', 'Cada generación de chips calcula más por vatio, y sin embargo el consumo total crece: la eficiencia abarata el cómputo y se usa más.', 'Es el efecto rebote, aplicado a la informática.', (select id from ac_fuentes where slug = 'iea-energia'), 3, 0.9, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.obsolescencia_de_software', 'digital', 'Cuando lo que caduca es el software', 'Un aparato que funciona perfecto puede quedar inutilizable porque dejó de recibir actualizaciones: la obsolescencia no siempre es del hardware.', null, (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.reacondicionado', 'digital', 'Reacondicionado', 'Comprar un dispositivo reacondicionado evita toda la huella de fabricar uno nuevo, que es justamente donde está el grueso del impacto.', null, (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.derecho_a_reparar_tec', 'digital', 'Que se pueda abrir', 'Un aparato reparable necesita tornillos en vez de pegamento, repuestos disponibles y manuales públicos. Eso se decide en el diseño, no después.', null, (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.huella_de_la_compra', 'digital', 'La compra que no hiciste', 'En tecnología, la decisión con más impacto sigue siendo no comprar: ningún modelo nuevo, por eficiente que sea, compensa la fabricación evitada.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 3, 0.8, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.alcances_de_una_empresa_tec', 'digital', 'Los alcances de una tecnológica', 'Buena parte de las emisiones de una empresa tecnológica no están en sus oficinas: están en la fabricación de lo que vende y en la energía de terceros.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.energia_renovable_contratada', 'digital', 'Comprar renovable no es consumir renovable', 'Una empresa puede comprar certificados de energía renovable y seguir tomando electricidad de una red que en ese momento quema gas: coincidir en tiempo y lugar es lo difícil.', null, (select id from ac_fuentes where slug = 'iea-energia'), 3, 0.9, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.transparencia_de_datos', 'digital', 'Lo que no se publica', 'Muchas cifras de consumo digital son estimaciones: cuando una empresa no publica sus datos, la incertidumbre es parte del resultado y hay que decirlo.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('digital.comparar_con_algo', 'digital', 'Comparar con algo conocido', 'Un número digital solo significa algo comparado con otro: "el 3 % de la electricidad mundial" dice mucho más que "945 TWh".', null, (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.energia_vs_potencia', 'energia', 'Potencia y energía no son lo mismo', 'La potencia (kW) dice qué tan rápido consume un aparato; la energía (kWh) dice cuánto consumió en total, y es lo que se cobra.', 'Un aparato de mucha potencia usado un ratito puede gastar menos energía que uno chiquito prendido todo el día.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -1.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.el_kwh_cotidiano', 'energia', 'Cuánto es un kWh', 'Un kilovatio hora es un aparato de 1000 watts funcionando una hora: con esa sola unidad se mide toda la energía eléctrica de una casa.', 'Tener el kWh agarrado te deja comparar dos aparatos sin discutir de memoria.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.leer_la_factura', 'energia', 'Leer la boleta de luz', 'La factura de luz muestra los kWh consumidos en un período: comparar ese número con el mismo período del año pasado dice mucho más que mirar el total en pesos.', 'En el AMBA la boleta la emiten Edenor o Edesur. El precio se mueve por tarifas y subsidios; los kWh cuentan lo que pasó adentro de tu casa.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.consumo_fantasma', 'energia', 'El consumo fantasma', 'Muchos aparatos siguen tomando un poco de electricidad mientras están apagados o en espera: es un consumo real, aunque chico.', 'La lucecita roja del televisor y el cargador sin celular son el ejemplo clásico.', (select id from ac_fuentes where slug = 'epa'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.donde_esta_el_grueso', 'energia', 'Dónde está el grueso', 'En una casa, la climatización, el agua caliente y la heladera se llevan la mayor parte de la energía; los aparatos en espera son una porción chica.', 'Saber esto te deja empezar por lo que mueve la aguja en vez de por lo que se ve más.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.envolvente', 'energia', 'La envolvente', 'Paredes, techo, ventanas y puertas son la envolvente de una casa: por ahí entra y sale el calor, y una casa bien aislada necesita mucha menos energía para estar cómoda.', 'El techo suele ser el lugar donde más se gana aislando, porque el calor sube.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.puente_termico', 'energia', 'Puentes térmicos', 'Hay puntos donde el calor cruza la envolvente mucho más rápido que en el resto —marcos de ventana, encuentros de losa, rendijas— y ahí se va buena parte de lo que gastás en climatizar.', 'Un burlete en la puerta y una cortina pesada de noche son la versión barata de arreglar esto.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.termostato_24_20', 'energia', '24 en verano, 20 en invierno', 'Poner el aire en 24 °C en verano y la calefacción en 20 °C en invierno deja la casa cómoda y consume bastante menos que llevar el equipo a temperaturas extremas.', 'Cada grado que le pedís de más al equipo se paga en kWh todos los días de la temporada.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.agua_caliente', 'energia', 'El agua caliente', 'Calentar agua es uno de los usos más grandes de una casa: el termotanque mantiene un tanque caliente todo el día, el calefón calienta solo cuando abrís la canilla y la bomba de calor entrega varias veces más calor que la electricidad que consume.', 'Por eso una ducha más corta y un termotanque bien aislado compiten en serio con cambiar las lámparas.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.led_vs_incandescente', 'energia', 'LED, halógena, incandescente', 'Una lámpara LED da la misma luz que una incandescente usando una fracción de la electricidad, y además dura mucho más.', 'La incandescente se calienta porque buena parte de la energía se le va en calor en vez de en luz.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.etiqueta_eficiencia', 'energia', 'La etiqueta A–G', 'Los electrodomésticos que se venden en Argentina llevan una etiqueta de eficiencia energética con letras de la A a la G: la A consume menos que la G para hacer el mismo trabajo.', 'La etiqueta también trae un consumo estimado en kWh: ese es el número comparable entre dos modelos.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.cuenta_de_servilleta', 'energia', 'La cuenta de servilleta', 'Potencia por horas de uso te da los kWh: con esa cuenta estimás lo que consume cualquier aparato sin tener que creerle a nadie.', 'No busques precisión: buscá el orden de magnitud, que es lo que decide si algo importa o no.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.rebote_energetico', 'energia', 'El rebote', 'Cuando un equipo se vuelve más eficiente da ganas de usarlo más, y parte de lo ahorrado se va en ese uso extra.', 'No es un argumento contra mejorar el equipo: es un motivo para mirar los kWh después del cambio.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.orden_de_las_decisiones', 'energia', 'Primero no gastar', 'En energía el orden que más rinde es: no gastar lo que no hace falta, después usar mejor lo que ya tenés, después cambiar el equipo y recién ahí generar.', 'Es el mismo orden que usan los planes de mitigación: evitar, mejorar, reemplazar.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.matriz_electrica_ar', 'energia', 'La matriz eléctrica argentina', 'La electricidad argentina se genera con una mezcla: sobre todo centrales térmicas a gas, más hidroeléctricas, nuclear y una porción creciente de eólica y solar.', 'Cuando enchufás algo no estás tomando de una sola fuente: estás tomando de esa mezcla, tal como esté en ese momento.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.factor_emision_red', 'energia', 'Cuánto emite un kWh', 'Cada kWh que tomás de la red trae emisiones asociadas según con qué se generó, y ese número —gramos de CO₂ por kWh— cambia según el país, la hora y la estación.', 'Por eso la misma heladera "emite" distinto en dos países, y por eso electrificar rinde más a medida que la red se limpia.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.25, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.nuclear_bajas_emisiones', 'energia', 'La nuclear y el CO₂', 'Medidas por kWh, las emisiones de CO₂ de la energía nuclear están en la misma banda baja que la eólica y la hidro: sus debates reales son los residuos, el costo y el riesgo de accidente.', 'En Argentina generan Atucha I, Atucha II y Embalse.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.renovables_argentinas', 'energia', 'Viento del sur, sol del norte', 'Argentina tiene dos recursos renovables de primera: el viento constante de la Patagonia y el sol de la Puna, donde está el parque solar de Cauchari, en Jujuy.', 'Son lugares lejos del AMBA, así que la energía también necesita líneas que la traigan hasta acá.', (select id from ac_fuentes where slug = 'iea-energia'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('energia.demanda_pico', 'energia', 'La hora pico de la red', 'La demanda eléctrica no es pareja: tiene picos —las tardes de calor, las noches de frío— y el sistema tiene que estar dimensionado para ese momento, no para el promedio.', 'Por eso el promedio anual de consumo cuenta poco: lo que obliga a construir centrales es el rato más exigente del año.', (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.curva_del_pato', 'energia', 'La curva del pato', 'Con mucha generación solar sobra energía al mediodía y la demanda salta al atardecer, justo cuando el sol se va: dibujada, esa curva parece un pato y describe el desafío de operar una red renovable.', null, (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('energia.intermitencia', 'energia', 'Intermitencia, resuelta con sistema', 'El sol y el viento no están siempre, y por eso una red renovable se arma como sistema: mezcla de fuentes, parques repartidos en el territorio, demanda que se corre de horario y almacenamiento.', 'La pregunta técnica no es "¿qué pasa si se nubla?", es "¿qué pasa si se nubla acá mientras sopla allá?".', (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.almacenamiento', 'energia', 'Guardar electricidad', 'Las baterías de red guardan energía cuando sobra y la devuelven cuando falta: no generan nada, corren la energía en el tiempo.', 'Por eso el almacenamiento no compite con la generación renovable: es lo que la vuelve utilizable a las nueve de la noche.', (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.generacion_distribuida', 'energia', 'Generar desde tu techo', 'Un usuario con paneles puede inyectar a la red lo que le sobra y descontarlo de su factura: eso es generación distribuida con balance neto, habilitada en Argentina por la Ley 27.424.', 'El medidor pasa a contar en los dos sentidos: lo que tomás y lo que entregás.', (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.gas_en_la_matriz', 'energia', 'Por qué acá todo pasa por el gas', 'El gas natural es la fuente principal de la energía argentina: mueve buena parte de la generación eléctrica y además calefacciona y calienta el agua de millones de hogares.', 'Eso explica por qué en Argentina la discusión energética empieza casi siempre por el gas.', (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.1, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.garrafa_y_red', 'energia', 'Garrafa y red no salen lo mismo', 'La misma energía sale bastante más cara comprada en garrafa de GLP que traída por la red de gas natural, y no todos los barrios del conurbano tienen red.', 'Es una desigualdad que no se ve en la tarifa: se ve en quién puede prender la estufa sin hacer cuentas.', (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.pobreza_energetica', 'energia', 'Pobreza energética', 'Hay pobreza energética cuando un hogar no puede acceder a la energía que necesita para estar sano y cómodo, o cuando pagarla le come una parte desproporcionada de sus ingresos.', 'Una casa mal aislada convierte cualquier tarifa en un problema: por eso aislar techos también es política social.', (select id from ac_fuentes where slug = 'iea-energia'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.vaca_muerta_debate', 'energia', 'Vaca Muerta, en discusión', 'Vaca Muerta es un yacimiento de hidrocarburos no convencionales que se explota con fractura hidráulica, y se discuten a la vez su aporte a la energía y a la economía del país y sus impactos sobre el agua, el territorio y las emisiones.', 'No hay veredicto simple. Es un caso para mirar qué evidencia trae cada lado antes de tomar posición.', (select id from ac_fuentes where slug = 'epa'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.co2_equivalente', 'energia', 'CO₂ equivalente y el metano', 'Los gases de efecto invernadero se comparan en CO₂ equivalente según cuánto calientan: el metano calienta bastante más que el CO₂ en las primeras décadas, aunque dure menos tiempo en la atmósfera.', 'Por eso una fuga de gas natural pesa mucho más de lo que sugiere su volumen.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.alcances_123', 'energia', 'Alcances 1, 2 y 3', 'Una huella de carbono se ordena en tres alcances: lo que quemás vos (1), la electricidad que comprás (2) y todo lo demás de tu cadena, de proveedores a productos (3).', 'El alcance 3 suele ser el más grande y el más fácil de dejar afuera de un informe: fijate siempre si está.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.energia_incorporada', 'energia', 'La energía que ya está adentro', 'Fabricar un aparato ya gastó energía y emitió antes de que lo enchufes, así que alargarle la vida al que tenés suele pesar más que afinar cómo lo usás.', 'Es la razón por la que "quedate dos años más con el celular" compite con medidas mucho más vistosas.', (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.presupuesto_carbono', 'energia', 'El presupuesto de carbono', 'El calentamiento depende del total acumulado de CO₂, así que existe un presupuesto: la cantidad que todavía se puede emitir si se quiere quedar cerca de 1,5 °C.', 'Es un stock, no un flujo: por eso la fecha en que se baja importa tanto como el número final.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('energia.palanca_colectiva', 'energia', 'Dónde está la palanca', 'Cambiar las lámparas de tu casa y empujar decisiones colectivas —normas de construcción, tarifas, obras de generación— no compiten: lo primero es la puerta de entrada a lo segundo, que es donde se mueven los kWh en serio.', 'Un consorcio que aísla el techo del edificio mueve más que veinte personas desenchufando cargadores.', (select id from ac_fuentes where slug = 'unesco-ods'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.piramide_movilidad', 'movilidad', 'Quién va primero', 'Cuando se reparte el espacio de una calle, primero está quien camina, después la bici, después el transporte público, y último el auto particular.', 'Se la llama pirámide invertida de la movilidad: al revés de como se diseñaron las ciudades durante casi todo el siglo XX.', (select id from ac_fuentes where slug = 'unep'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.espacio_de_la_calle', 'movilidad', 'Cuánta calle ocupa cada uno', 'Mover a una persona en auto ocupa muchísimo más asfalto que moverla en colectivo, en bici o a pie.', 'Fijate en cualquier avenida en hora pico: la mayoría de los autos lleva una sola persona adentro.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.movilidad_activa', 'movilidad', 'Moverte con tu propio cuerpo', 'Caminar y pedalear también son transporte: mueven gente sin motor y, de paso, hacen que quien se mueve esté más sano.', 'Buena parte de los viajes urbanos son cortos, y son justo los que entran a pie o en bici.', (select id from ac_fuentes where slug = 'unep'), 1, -1.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.pasajero_km', 'movilidad', 'Por pasajero y por kilómetro', 'Para comparar dos formas de viajar hay que mirar la energía y las emisiones por pasajero y por kilómetro, no por vehículo: un auto con una sola persona y un colectivo lleno no se miden igual.', 'Es la misma unidad para todos los modos. Sin ella, cualquier comparación entre auto y colectivo se puede acomodar para el lado que uno quiera.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.material_particulado', 'movilidad', 'Partículas que no se ven', 'El material particulado son partículas tan chicas que el ojo no las registra, y las más finas llegan hasta lo hondo del pulmón.', 'PM10 y PM2.5 son medidas de tamaño: el número es el diámetro en micrones. Cuanto más chica, más adentro llega.', (select id from ac_fuentes where slug = 'epa'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.pm_del_transito', 'movilidad', 'No todo sale del caño de escape', 'Buena parte del material particulado del tránsito no sale del escape: lo aportan los frenos, las cubiertas y el polvo que levantan las ruedas.', 'Por eso un auto eléctrico mejora el aire, pero no lo deja impecable: sigue frenando y sigue teniendo cubiertas.', (select id from ac_fuentes where slug = 'epa'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.nox_y_ozono', 'movilidad', 'Nitrógeno, sol y ozono de abajo', 'Los óxidos de nitrógeno que largan los motores, cocinados por el sol, forman ozono a nivel del suelo, que irrita las vías respiratorias.', 'Ese ozono de abajo no tiene nada que ver con la capa de ozono de la estratósfera, que nos protege del ultravioleta. Mismo gas, dos historias distintas.', (select id from ac_fuentes where slug = 'epa'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.ruido_urbano', 'movilidad', 'El ruido también contamina', 'El ruido del tránsito es contaminación: no deja descansar a las personas y cambia la forma en que se comunican los pájaros de la ciudad.', 'Prestá atención una madrugada de domingo en tu cuadra: esa es la ciudad sin el motor de fondo.', (select id from ac_fuentes where slug = 'unep'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.velocidad_y_riesgo', 'movilidad', 'Despacio se cruza mejor', 'Cuando los autos van más despacio, cruzar la calle se vuelve mucho más seguro: por eso existen las zonas 30 cerca de escuelas y plazas.', 'La velocidad no cambia solo cuánto tarda un choque en pasar: cambia cuánta gente se anima a caminar y a andar en bici por ahí.', (select id from ac_fuentes where slug = 'unep'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.calle_compartida', 'movilidad', 'Una calle para todo el mundo', 'Veredas anchas, cruces cortos y sombra son lo que hace que caminar sea posible para cualquiera: un pibe de siete años y una persona de ochenta.', 'Si una calle solo funciona para alguien que camina rápido y ve bien, esa calle está mal hecha.', (select id from ac_fuentes where slug = 'unep'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.efecto_barrera', 'movilidad', 'Cuando la avenida parte el barrio', 'Una autopista o una avenida muy ancha corta un barrio en dos: lo que queda del otro lado deja de estar cerca aunque esté a cien metros.', 'Se lo llama efecto barrera. La distancia física no cambió; la distancia real, sí.', (select id from ac_fuentes where slug = 'unep'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.red_no_tramo', 'movilidad', 'Vale la red, no el tramo', 'Una ciclovía suelta sirve poco: lo que hace que la gente se anime a la bici es una red continua que conecte de donde salís con adonde vas.', 'La red de ciclovías de CABA y las bicis de Ecobici funcionan con esa lógica: cada tramo vale por lo que conecta.', (select id from ac_fuentes where slug = 'unep'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.pedir_la_calle', 'movilidad', 'Cómo se cambia una calle', 'Cambiar una calle no es solo una decisión técnica: la Ley General del Ambiente reconoce que la gente tiene derecho a informarse y a opinar antes, en instancias de participación como las audiencias públicas.', 'Una vecinal, un centro de estudiantes o un grupo de la cuadra pueden presentarse. Es más común de lo que parece.', (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 1, -0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.masivo_gana', 'movilidad', 'Cuando el colectivo va lleno', 'Un colectivo, un tren o un subte llenos mueven a cada pasajero con mucha menos energía y mucho menos espacio que un auto con una sola persona adentro.', 'La palabra clave es "llenos": el transporte masivo gana cuando lo usa mucha gente, y por eso la ocupación importa tanto como el motor.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.brt_carril_propio', 'movilidad', 'Un carril que es solo del colectivo', 'Un BRT es un colectivo con carril exclusivo y paradas fijas para que deje de estar atrapado en el mismo embotellamiento que los autos.', 'El Metrobus porteño y los del conurbano son eso: la misma flota, pero con la calle ordenada a su favor.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.combinar_modos', 'movilidad', 'Un viaje, varios modos', 'Un viaje no tiene por qué hacerse en un solo modo: caminar hasta la estación, tomar el tren y salir en bici del otro lado es un solo viaje bien armado.', 'Los eslabones débiles suelen ser los extremos: la caminata hasta la parada y el último tramo hasta la puerta.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.frecuencia_manda', 'movilidad', 'Cada cuánto pasa', 'Lo que vuelve usable al transporte público no es solo la tarifa: es la frecuencia, saber cuándo llega y poder caminar tranquilo hasta la parada.', 'Un servicio barato que pasa cada cuarenta minutos pierde contra un auto. Uno que pasa cada cinco, no.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.ciclo_de_vida', 'movilidad', 'Toda la vida del vehículo', 'Para comparar dos autos hay que sumar toda su vida: fabricarlo, moverlo durante años y qué pasa cuando se jubila.', 'Mirar solo una etapa —solo el escape, o solo la fábrica— siempre da la respuesta que uno ya quería escuchar.', (select id from ac_fuentes where slug = 'icct-ev'), 2, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.bateria_y_litio', 'movilidad', 'De dónde sale la batería', 'La batería de un auto eléctrico necesita minerales, y buena parte del litio del mundo está disuelto en la salmuera de los salares de altura: Argentina, Chile y Bolivia comparten el llamado triángulo del litio.', 'Salinas Grandes y el Salar del Hombre Muerto son dos nombres de ese mapa que quedan dentro del país.', (select id from ac_fuentes where slug = 'unep'), 2, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.electrico_sin_tubo_de_escape', 'movilidad', 'Sin humo no es sin huella', 'Un auto eléctrico no emite nada por el caño de escape, pero sí emite al fabricarse —sobre todo la batería— y según con qué se genere la electricidad que lo carga; aun así, a lo largo de toda su vida emite bastante menos que un naftero comparable.', 'Las dos cosas son ciertas al mismo tiempo, y ahí es donde se traba la discusión de sobremesa.', (select id from ac_fuentes where slug = 'icct-ev'), 2, 0.1, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.matriz_electrica_importa', 'movilidad', 'Depende del enchufe', 'Cuánto emite un auto eléctrico depende de la red que lo carga: cuanto más limpia es la generación eléctrica del lugar, más grande se hace la diferencia con el naftero.', 'Y la red no es una foto fija: a medida que entra más renovable, el mismo auto que ya está andando emite menos que el año pasado.', (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.litio_y_agua', 'movilidad', 'Litio, salares y agua', 'Sacar litio de un salar es, antes que nada, un asunto de agua: se bombea salmuera y se evapora en una de las regiones más secas del país, donde viven comunidades que dependen de ese agua.', 'No es una discusión con respuesta obvia: la transición energética necesita baterías y las comunidades de la Puna necesitan su agua. Por eso se decide con información pública y participación, no a puertas cerradas.', (select id from ac_fuentes where slug = 'unep'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.demanda_inducida', 'movilidad', 'El carril que se llena solo', 'Cuando se agrega un carril, al poco tiempo se vuelve a llenar: más capacidad vial termina generando más viajes en auto.', 'Se llama demanda inducida, y es el efecto rebote aplicado al asfalto: la mejora se consume a sí misma.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.estacionamiento_gratis', 'movilidad', 'Lo que parece gratis', 'Estacionar en la calle parece gratis, pero ocupa suelo urbano que se regala; cuando ese espacio se cobra o se reduce, cambian los viajes que se hacen en auto.', 'Cada lugar de estacionamiento es una superficie que podría ser vereda, bicisenda, contenedores o un árbol.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.ciudad_de_distancias_cortas', 'movilidad', 'Todo cerca de la estación', 'Si la vivienda, el trabajo, la escuela y el súper están cerca de una estación, mucha gente deja de necesitar el auto sin habérselo propuesto.', 'Es lo que se llama desarrollo orientado al transporte: no se convence a nadie, se cambia la geografía de la decisión.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.teletrabajo_rebote', 'movilidad', 'Teletrabajo y el viaje que vuelve', 'Teletrabajar borra viajes diarios, pero puede sumar otros —mudarse más lejos, salidas durante el día, más envíos a casa—: el ahorro real hay que medirlo, no darlo por hecho.', 'No es un argumento en contra del teletrabajo: es un recordatorio de que el ahorro se mide en el total, no en el viaje que dejaste de hacer.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.volar_pesa', 'movilidad', 'Un vuelo concentra mucho', 'Un vuelo largo concentra en pocas horas mucha más emisión que casi cualquier decisión de transporte del día a día.', 'No es para dejar de viajar nunca: es para saber en qué renglón de tu año está el número grande antes de discutir los chicos.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, -0.1, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.estelas_y_forzamiento', 'movilidad', 'No solo el CO₂ del avión', 'El efecto de un avión sobre el clima no es solo su CO₂: las estelas de condensación y otros efectos en altura suman calentamiento adicional, con bastante más incertidumbre.', 'Que un número tenga incertidumbre no lo vuelve inventado: lo vuelve un rango en vez de una cifra exacta.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.compensar_no_es_no_emitir', 'movilidad', 'Compensar no es no emitir', 'Comprar una compensación no borra el vuelo: primero está no hacer el viaje, después hacerlo de otra manera, y recién al final compensar lo que quedó.', 'La calidad de las compensaciones varía muchísimo, y varias auditorías encontraron créditos que no representaban emisiones realmente evitadas.', (select id from ac_fuentes where slug = 'carbon-brief'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('movilidad.ultima_milla', 'movilidad', 'La última cuadra del paquete', 'Cada compra online termina en una camioneta haciendo la última cuadra; juntar pedidos en un solo envío o retirarlos en un punto de entrega cambia esos kilómetros.', 'El envío exprés es el que más pesa: obliga a salir con el vehículo medio vacío para llegar a horario.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.fotosintesis', 'plantas', 'La planta se fabrica la comida', 'Una planta no saca su comida del suelo: la fabrica ella misma con luz del sol, agua y el dióxido de carbono que toma del aire.', 'Del suelo saca agua y minerales, nada más. Buena parte del cuerpo de un árbol es carbono que antes andaba dando vueltas en el aire.', (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.planta_guarda_carbono', 'plantas', 'Dónde queda ese carbono', 'Al fabricar su alimento la planta guarda carbono en su madera, sus raíces y el suelo, y ahí se queda mientras la planta siga en pie.', 'Por eso un árbol viejo no es intercambiable por un plantín: lo que acumuló tardó décadas en acumularse.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.suelo_esta_vivo', 'plantas', 'El suelo está vivo', 'El suelo no es tierra muerta: es un ecosistema lleno de hongos, bacterias, lombrices y bichos que desarman lo que cae y dejan los nutrientes a mano.', 'Un puñado de suelo sano tiene más seres vivos que los que ves en toda la cuadra.', (select id from ac_fuentes where slug = 'fao'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.micorrizas', 'plantas', 'Socios bajo tierra', 'La mayoría de las plantas viven asociadas a hongos del suelo: el hongo les acerca agua y nutrientes, y la planta le devuelve azúcares.', 'Esa sociedad se llama micorriza. Es tan común que una planta sola, sin sus hongos, es media planta.', (select id from ac_fuentes where slug = 'fao'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.banco_de_semillas', 'plantas', 'Semillas dormidas', 'Debajo de un pastizal o de un monte hay semillas esperando: se quedan dormidas en el suelo hasta que les llega luz, agua o calor, y ahí germinan.', 'Se lo llama banco de semillas del suelo. Es la memoria del lugar, y es lo primero que se pierde cuando el suelo se raspa o se tapa.', (select id from ac_fuentes where slug = 'inta'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.que_es_nativa', 'plantas', 'Qué es una planta nativa', 'Una planta nativa es la que ya vivía en tu región antes de que la trajéramos nosotros: se hizo ahí, junto con los bichos, los pájaros y el suelo del lugar.', 'Por eso una nativa suele alimentar y alojar a mucha más fauna local que una traída de lejos.', (select id from ac_fuentes where slug = 'plantas-nativas'), 1, -1.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.exotica_no_es_invasora', 'plantas', 'Exótica no es lo mismo que invasora', 'Exótica es la que vino de otro lado; invasora es la exótica que además se escapa del jardín, se reproduce sola y va desplazando a las nativas.', 'El jacarandá que pinta la ciudad de violeta es exótico y está naturalizado hace más de un siglo, y no por eso se comió el monte.', (select id from ac_fuentes where slug = 'invasoras-mayds'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.ceibo_y_compania', 'plantas', 'Ceibo, sauce criollo y compañía', 'La flora nativa rioplatense tiene nombre y apellido: el ceibo —nuestra flor nacional—, el sauce criollo, el aliso de río, el curupí, el laurel blanco y el timbó.', 'Son las que crecen solas en la costa y en las islas del Paraná, sin que nadie las riegue.', (select id from ac_fuentes where slug = 'plantas-nativas'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.ombu_no_es_arbol', 'plantas', 'El ombú no es un árbol', 'El ombú no es un árbol: es una hierba gigante. Su tronco no tiene madera dura, está cargado de agua, y por eso se raja y se dobla como se dobla.', 'Fijate la próxima vez que pases por uno: parece derretido. Esa forma es la pista.', (select id from ac_fuentes where slug = 'plantas-nativas'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.tu_ecorregion', 'plantas', 'En qué ecorregión estás', 'Antes de elegir qué plantar conviene saber en qué ecorregión vivís: el AMBA cae entre el Pastizal Pampeano y el Delta e Islas del Paraná, y cada uno tiene su propia lista de nativas.', '"Nativa de Argentina" no alcanza: una especie de la Selva Paranaense es tan forastera en la Pampa como una traída de otro continente.', (select id from ac_fuentes where slug = 'ecorregiones-pba'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.plantar_la_correcta', 'plantas', 'Plantar bien, no plantar y ya', 'Plantar suma cuando la especie es la que corresponde a esa ecorregión y a ese lugar; con la especie equivocada, la misma pala puede restar.', 'Elegí nativa de tu ecorregión, mirá cuánto sol tiene el lugar y cuánto va a crecer en veinte años. Con eso ya estás jugando bien.', (select id from ac_fuentes where slug = 'plantas-nativas'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.arbolado_urbano', 'plantas', 'El arbolado trabaja para la cuadra', 'El árbol de la vereda hace trabajo para todos: da sombra, frena el viento, intercepta parte del polvo fino del aire y baja la temperatura de la calle.', 'En las veredas porteñas conviven tipa, palo borracho y jacarandá, cada uno con su tamaño y su época de flor.', (select id from ac_fuentes where slug = 'ipbes-global'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.isla_de_calor', 'plantas', 'La isla de calor urbana', 'Una zona con mucho asfalto, techo y cemento y poca vegetación queda más caliente que su entorno: es la isla de calor urbana.', 'El asfalto guarda calor todo el día y lo suelta de noche. Vegetación y sombra son la forma más barata de bajar esa diferencia.', (select id from ac_fuentes where slug = 'epa'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.arboles_y_lluvia', 'plantas', 'Cuando llueve fuerte', 'Las copas frenan la lluvia antes de que toque el piso y las raíces la ayudan a entrar en la tierra: así llega menos agua de golpe a la boca de tormenta.', 'Cada cantero sin baldosa es una entrada de agua. Muchos canteros seguidos son una esquina que se inunda menos.', (select id from ac_fuentes where slug = 'epa'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.techos_y_muros_verdes', 'plantas', 'Verde donde no hay suelo', 'Un techo o un muro verde mete vegetación donde no hay tierra: aísla del calor, retiene parte del agua de lluvia y da de comer a los polinizadores.', 'No reemplaza a un árbol grande, pero en una ciudad con poco suelo libre es metros cuadrados que antes no jugaban.', (select id from ac_fuentes where slug = 'epa'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.huerta_urbana', 'plantas', 'Una huerta entra en un balcón', 'Para arrancar una huerta alcanza con un cajón, unas horas de sol directo, tierra viva y agua: lechuga, acelga, rúcula y aromáticas andan bien en poco espacio.', 'Empezá por lo que ya comés. Una planta que cosechás es una planta que vas a seguir cuidando.', (select id from ac_fuentes where slug = 'inta'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.prohuerta', 'plantas', 'ProHuerta existe y es gratis', 'ProHuerta, del INTA, acompaña huertas familiares, escolares y comunitarias en todo el país con semillas y capacitación sin costo.', 'Si en tu escuela o tu barrio quieren armar una huerta, ese es el teléfono al que conviene llamar primero.', (select id from ac_fuentes where slug = 'inta'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.compost_cierra_ciclo', 'plantas', 'El compost cierra el ciclo', 'Las cáscaras de fruta y verdura no son basura: compostadas vuelven a ser suelo y alimentan a la próxima planta.', 'Es el ciclo de la materia haciéndose en un balde, a la vista, en tu casa.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('plantas.asociacion_y_rotacion', 'plantas', 'Asociar y rotar', 'Poner juntos cultivos que se ayudan, y cambiarlos de cantero cada temporada, corta el ciclo de las plagas y evita que el suelo se agote siempre del mismo nutriente.', 'Es la misma idea que en un ecosistema: la mezcla aguanta mejor que el monocultivo.', (select id from ac_fuentes where slug = 'inta'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.semilla_criolla', 'plantas', 'Criolla, híbrida, transgénica', 'Una semilla criolla la guardás de tu propia cosecha y vuelve a dar una planta parecida; una híbrida no: su descendencia sale despareja, por eso hay que comprarla de nuevo cada año.', 'Transgénica es otra cosa: lleva un gen agregado en laboratorio y se usa sobre todo en cultivos extensivos, no en el cajón del balcón.', (select id from ac_fuentes where slug = 'inta'), 1, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.pastizal_pampeano', 'plantas', 'La Pampa es un pastizal', 'La Pampa no es un campo vacío esperando algo: es un pastizal, un ecosistema hecho de decenas de gramíneas nativas, y ocupa la mayor parte del territorio bonaerense.', 'Como es bajo y sin árboles, cuesta verlo como bosque o como selva. Pero es un ecosistema completo, con sus lagunas y su fauna.', (select id from ac_fuentes where slug = 'ecorregiones-pba'), 2, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.raices_del_pastizal', 'plantas', 'La mitad que está abajo', 'Buena parte del pastizal vive bajo tierra: sus raíces profundas sostienen el suelo, guardan materia orgánica y carbono, y por eso el suelo pampeano es tan rico.', 'Cuando se da vuelta ese suelo, lo que se pierde primero es lo que no se veía.', (select id from ac_fuentes where slug = 'ecorregiones-pba'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.monte_blanco_delta', 'plantas', 'El monte blanco del Delta', 'El "monte blanco" es el bosque ribereño propio del Delta del Paraná: varias capas de nativas —sauce criollo, aliso de río, curupí, laurel blanco— sobre un suelo que se inunda y se seca.', 'Está muy reducido, y donde queda es la mejor referencia de qué plantar cuando se restaura la ribera.', (select id from ac_fuentes where slug = 'ecorregiones-pba'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.sucesion_ecologica', 'plantas', 'Lo que pasa si nadie toca', 'Un terreno que queda quieto no se queda quieto: primero llegan las pioneras, después otras, y la comunidad va cambiando durante años. Eso es la sucesión ecológica.', 'La Reserva Ecológica Costanera Sur es el caso a la vista: un relleno costero al lado del centro que se fue cubriendo de vegetación y hoy es reserva.', (select id from ac_fuentes where slug = 'reserva-costanera-sur'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.ligustro_mora_acacia', 'plantas', 'Ligustro, mora y acacia negra', 'En el Delta y en el AMBA hay tres invasoras que ya conocés de vista aunque no supieras el nombre: el ligustro, la mora y la acacia negra.', 'Crecen rápido, dan muchísima semilla y los pájaros se la llevan lejos. Por eso aparecen solas en cualquier terreno.', (select id from ac_fuentes where slug = 'invasoras-mayds'), 2, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.por_que_invade', 'plantas', 'Por qué una planta invade', 'Una exótica se vuelve invasora cuando llega a un lugar donde no están los hongos, insectos y herbívoros que la mantenían a raya en su tierra: crece sin freno y le va ganando el lugar a las nativas.', 'No es que la planta sea mala: es que le falta la mitad de sus relaciones. La invasión es un problema de red, no de especie.', (select id from ac_fuentes where slug = 'invasoras-mayds'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.restaurar_no_es_deshacer', 'plantas', 'Restaurar no es apretar deshacer', 'Volver a armar un ambiente que se perdió lleva años y nunca queda idéntico: el suelo, sus hongos y las relaciones entre especies no vuelven porque uno plante.', 'Restaurar se hace por etapas y con seguimiento: sacar lo invasor, reponer nativas, volver el año siguiente a ver qué prendió.', (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.corredores_y_polinizadores', 'plantas', 'Canteros que conectan', 'Un cantero con nativas floridas es una parada de comida para abejas nativas y mariposas; varios canteros cerca uno de otro arman un corredor por el que la fauna puede moverse.', 'Un balcón solo alcanza para poco. Un balcón, la plaza y el cantero de la escuela ya son un recorrido.', (select id from ac_fuentes where slug = 'plantas-nativas'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.deforestacion_chaco', 'plantas', 'El Gran Chaco, la frontera abierta', 'El Gran Chaco es la frontera de desmonte más activa de la Argentina: se abre monte xerófilo de quebracho para agricultura y ganadería.', 'Cuando se va el monte no se va solo el árbol: se van el suelo que sostenía, el agua que infiltraba y las especies que vivían ahí.', (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.ley_bosques', 'plantas', 'La Ley de Bosques y sus tres colores', 'La Ley 26.331 fija presupuestos mínimos para los bosques nativos y obliga a cada provincia a clasificarlos en tres categorías: rojo, que no se puede transformar; amarillo, de uso sostenible; y verde, transformable.', 'También creó un fondo nacional para conservar y enriquecer bosque. Es una ley de piso: cada provincia puede ser más exigente, no menos.', (select id from ac_fuentes where slug = 'ley-bosques-26331'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.otbn_es_un_mapa', 'plantas', 'El OTBN es un mapa que podés mirar', 'El Ordenamiento Territorial de Bosques Nativos es el mapa provincial que dice de qué categoría es cada parcela de bosque, y es información pública.', 'Antes de opinar sobre un desmonte se puede mirar el mapa y ver de qué color estaba pintado ese lote. Eso cambia bastante la conversación.', (select id from ac_fuentes where slug = 'ley-bosques-26331'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('plantas.plantar_no_compensa_desmontar', 'plantas', 'Plantar no borra desmontar', 'Una plantación no reemplaza a un bosque nativo: puede dar madera, sombra y algo de carbono guardado, pero no devuelve la trama de especies ni el suelo que había.', 'Por eso "planto mil árboles allá" no cancela "desmonto acá": son ecosistemas distintos, en lugares distintos, con historias distintas.', (select id from ac_fuentes where slug = 'ipbes-global'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.separar_en_origen', 'residuos', 'Separar es cosa de casa', 'Separar pasa en tu casa, no en la planta: una vez que todo se mezcló en la misma bolsa, el material reciclable ya se arruinó.', 'Por eso el sistema se llama "separación en origen". El origen sos vos: la cocina, el aula, la oficina.', (select id from ac_fuentes where slug = 'ley-1854-basura-cero'), 1, -1.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.humedos_y_secos', 'residuos', 'Húmedos y secos', 'En la Ciudad la basura se separa en dos: los secos —papel, cartón, plástico, vidrio y metal, limpios— van a la campana verde, y todo lo demás al contenedor negro.', 'Regla corta para no dudar: si está limpio y seco, es seco. Si tiene comida o líquido, es húmedo.', (select id from ac_fuentes where slug = 'ley-1854-basura-cero'), 1, -1.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.que_es_reciclable', 'residuos', 'Qué se recicla de verdad', 'Que un material sea reciclable en teoría no alcanza: se recicla lo que además llega limpio, se puede separar por tipo y tiene quién lo compre.', 'Papel, cartón, vidrio, metales y algunos plásticos tienen circuito armado. Los envases mezclados y los plásticos livianos, casi nunca.', (select id from ac_fuentes where slug = 'epa'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.contaminacion_cruzada', 'residuos', 'Un frasco sucio arruina la bolsa', 'Un envase con restos de comida o líquido moja y ensucia el papel y el cartón que viajan con él, y un lote contaminado se termina enterrando.', 'Un enjuague rápido con el agua que ya usaste para lavar los platos, y que entre seco a la bolsa. Ahí está la diferencia.', (select id from ac_fuentes where slug = 'epa'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.puntos_verdes', 'residuos', 'Puntos Verdes y campanas', 'Lo que no entra en la campana de la cuadra —aceite vegetal usado, aparatos electrónicos chicos, algunos materiales especiales— tiene su lugar en los Puntos Verdes.', 'Fijate cuál te queda cerca y juntá durante la semana: con una sola vuelta alcanza.', (select id from ac_fuentes where slug = 'ley-1854-basura-cero'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.jerarquia_residuos', 'residuos', 'El orden que rinde', 'Hay un orden: evitar, reducir, reutilizar, reciclar, recuperar energía y —recién al final— disponer. Cuanto más arriba actuás, menos material entra al sistema.', 'Reciclar es el cuarto escalón, no el primero.', (select id from ac_fuentes where slug = 'unep'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.evitar_es_primero', 'residuos', 'El residuo que no existe', 'El envase que no aceptás es el único que después no hay que lavar, trasladar ni procesar: evitar está arriba de la escalera porque ahorra todo lo que viene después.', 'La bolsa que ya tenías en la mochila, el vaso propio, el "sin sorbete, gracias".', (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.reutilizar_alarga_la_vida', 'residuos', 'Usarlo otra vez', 'Reutilizar mantiene el objeto entero: no hay que triturarlo, fundirlo ni volver a fabricarlo, y por eso gasta muchísima menos energía que reciclarlo.', 'Un frasco de mermelada que guarda tornillos ya dio más vueltas que uno que fue a la campana.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.reciclar_no_es_infinito', 'residuos', 'Reciclar baja de categoría', 'El plástico pierde calidad en cada vuelta: una botella no vuelve a ser botella para siempre, termina en productos de menor valor y en algún momento sale del circuito.', 'Por eso el reciclaje funciona como red de contención y no como solución: la palanca grande está más arriba, en evitar y en rediseñar el envase.', (select id from ac_fuentes where slug = 'yale-reciclaje'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.fraccion_organica', 'residuos', 'Lo orgánico no es basura', 'Buena parte de lo que sale de una cocina —cáscaras, yerba, café, restos de verdura— no es basura: es materia orgánica que puede volver a ser tierra.', 'Mezclada con el resto se pudre sin aire y da olor y líquido. Separada, se convierte en compost.', (select id from ac_fuentes where slug = 'fao'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.compostaje_domiciliario', 'residuos', 'Compostar en casa', 'Compostar es dejar que microorganismos, hongos y bichitos coman tus restos de cocina con aire y humedad hasta convertirlos en tierra fértil.', 'Entra en un balcón: una compostera chica, un puñado de tierra para arrancar y revolver cada tanto.', (select id from ac_fuentes where slug = 'inta'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.verdes_y_marrones', 'residuos', 'Verdes y marrones', 'Una compostera necesita las dos cosas mezcladas: húmedos ricos en nitrógeno —cáscaras, yerba, restos de verdura— y secos ricos en carbono —hojas, cartón, aserrín—.', 'Si huele feo, casi siempre falta seco y falta aire: agregá marrones y revolvé.', (select id from ac_fuentes where slug = 'inta'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.vermicompostaje', 'residuos', 'Las lombrices trabajan gratis', 'En una vermicompostera son lombrices las que comen los restos y devuelven humus: ocupa poco, no huele y funciona bien puertas adentro.', 'Quieren sombra, humedad de esponja escurrida y que no las inundes de cítricos ni de cebolla.', (select id from ac_fuentes where slug = 'inta'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.relleno_sanitario', 'residuos', 'El relleno sanitario', 'Lo que va al contenedor negro no desaparece: viaja en camión hasta un relleno sanitario, donde se compacta y se entierra entre capas preparadas para aislarlo del suelo.', 'Un relleno no es un pozo: es una obra de ingeniería con membranas abajo y sistemas para juntar el líquido y el gas.', (select id from ac_fuentes where slug = 'epa'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.ceamse_vida_util', 'residuos', 'El relleno tiene fondo', 'La basura del AMBA termina en los rellenos del CEAMSE, y cada tonelada enterrada ocupa un espacio que no se repone: por eso la ley porteña fija metas para enterrar cada vez menos.', 'Cada bolsa que se evita, se composta o se recicla es lugar que el relleno no usa.', (select id from ac_fuentes where slug = 'ley-1854-basura-cero'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.lixiviados', 'residuos', 'El líquido del relleno', 'Cuando la lluvia atraviesa la basura enterrada arrastra un líquido oscuro y cargado, el lixiviado, que hay que captar y tratar para que no llegue al agua subterránea.', 'Cuanto menos orgánico se entierra, menos lixiviado se genera: el compost también trabaja acá.', (select id from ac_fuentes where slug = 'epa'), 1, -0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.metano_de_relleno', 'residuos', 'El gas que sale de la basura', 'La materia orgánica enterrada se descompone sin oxígeno y libera metano, un gas de efecto invernadero potente; en los rellenos se lo capta para quemarlo o generar energía.', 'La misma cáscara que en una compostera se vuelve tierra, enterrada y sin aire se vuelve gas.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.del_rio_al_mar', 'residuos', 'De la vereda al río', 'La mayor parte de la basura que termina en el mar salió de tierra firme: se la llevan el viento y la lluvia por los desagües y los arroyos hasta los ríos.', 'En el AMBA ese camino tiene nombres conocidos: la boca de tormenta de tu cuadra, el arroyo entubado, el Riachuelo, el Río de la Plata.', (select id from ac_fuentes where slug = 'unep'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.codigos_plasticos', 'residuos', 'Los números del triangulito', 'El número del 1 al 7 adentro del triangulito no dice "esto se recicla": dice de qué plástico está hecho el envase, para poder separarlo por tipo.', '1 PET, 2 HDPE, 3 PVC, 4 LDPE, 5 PP, 6 poliestireno, 7 otros.', (select id from ac_fuentes where slug = 'epa'), 2, -0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.pet_y_hdpe', 'residuos', 'PET y HDPE, los que tienen mercado', 'El PET de las botellas (1) y el HDPE de bidones y envases de limpieza (2) son los plásticos con más circuito de reciclado: se identifican fácil y hay quien los compra.', 'Vacía, enjuagada y aplastada, una botella ocupa menos y viaja mejor.', (select id from ac_fuentes where slug = 'epa'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.telgopor', 'residuos', 'El telgopor es casi todo aire', 'El poliestireno expandido (6) es casi todo aire: pesa poquísimo y ocupa mucho, así que juntarlo y transportarlo cuesta más de lo que vale y casi nunca encuentra circuito.', 'Acá la palanca está arriba de la escalera: pedir la bandeja sin telgopor, llevar tu propio recipiente.', (select id from ac_fuentes where slug = 'unep'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.tetrabrik_multicapa', 'residuos', 'El tetrabrik son tres materiales', 'Un envase de leche o jugo tipo tetrabrik es cartón, plástico y aluminio pegados en capas: reciclarlo exige una planta que sepa separarlas, y no todas pueden.', 'Es el mejor ejemplo de que el diseño del envase decide, mucho antes que vos, si se va a poder reciclar.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.biodegradable_no_es_magia', 'residuos', '"Biodegradable" pide condiciones', 'La mayoría de los plásticos compostables solo se degradan en una planta industrial con temperatura y humedad controladas; en un relleno, en el suelo o en el agua se comportan como plástico común.', 'Los "oxodegradables" son peor: no desaparecen, se parten en pedazos cada vez más chicos.', (select id from ac_fuentes where slug = 'unep'), 2, 0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.recuperadores_urbanos', 'residuos', 'Quién abre la bolsa', 'En el AMBA buena parte del material que se recicla pasa antes por las manos de recuperadores urbanos, que separan en la calle y lo llevan a una planta.', 'Cuando separás bien no solo reciclás: hacés que ese trabajo sea más rápido, más seguro y mejor pago.', (select id from ac_fuentes where slug = 'faccyr'), 2, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.cooperativas_faccyr', 'residuos', 'De changa a servicio', 'Los recuperadores se organizaron en cooperativas y federaciones —FACCyR es la más grande del país— y pasaron de trabajar sueltos a prestar el servicio de recolección de reciclables.', 'Es un caso concreto de lo colectivo: lo que una persona sola no podía negociar, una federación sí.', (select id from ac_fuentes where slug = 'faccyr'), 2, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.ley_basura_cero', 'residuos', 'Basura Cero, la ley porteña', 'La Ley 1854 de la Ciudad, conocida como Basura Cero, fija metas de reducción progresiva de lo que se manda a enterrar y prohíbe la disposición final de materiales reciclables y aprovechables.', '"Basura cero" no promete cero basura mañana: nombra una dirección y le pone metas con fecha.', (select id from ac_fuentes where slug = 'ley-1854-basura-cero'), 2, 0.2, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.rep_envases', 'residuos', 'Quien lo pone en el mercado se hace cargo', 'La Responsabilidad Extendida del Productor pone en cabeza de quien fabrica y vende el envase el costo de gestionarlo después del uso, en vez de dejarlo del lado del vecino y del municipio.', 'En Argentina hay proyectos de ley de envases con REP en debate; la discusión es quién paga, quién controla y qué papel juegan las cooperativas.', (select id from ac_fuentes where slug = 'rep-envases'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.greenwashing_mobius', 'residuos', 'El triangulito no promete nada', 'El símbolo del triángulo de flechas no está certificado ni garantiza que ese envase se recicle donde vivís: muchas veces solo indica de qué material está hecho.', 'Preguntá lo concreto: ¿lo recibe la campana de mi barrio?, ¿hay quién lo compre? Si no, el símbolo es decoración.', (select id from ac_fuentes where slug = 'yale-reciclaje'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.lineal_vs_circular', 'residuos', 'Línea recta o círculo', 'La economía lineal va derecho —extraer, fabricar, usar, tirar— y la circular busca que el material vuelva a entrar: reparación, reutilización, remanufactura y recuperación.', 'En la naturaleza no existe el "tirar": lo que sobra de uno es alimento de otro.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, -0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.diseno_para_desmontaje', 'residuos', 'Diseñado para poder abrirse', 'Si un producto viene pegado, soldado o hecho de materiales mezclados, no se puede reparar ni separar: la decisión que define su final se tomó en la mesa de diseño.', 'Tornillos en vez de pegamento, batería reemplazable y repuestos disponibles: eso es diseño para el desmontaje.', (select id from ac_fuentes where slug = 'ellen-macarthur'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.raee_y_metales', 'residuos', 'Los aparatos tienen mina adentro', 'Un celular guarda cobre, aluminio y metales críticos que salieron de una mina: en el tacho se pierden, y en un punto que recibe RAEE se pueden recuperar.', 'El aparato que más ahorra es el que seguís usando: alargarle la vida pesa más que reciclarlo.', (select id from ac_fuentes where slug = 'unep'), 2, 0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('residuos.peligrosos_domiciliarios', 'residuos', 'Lo que no va al tacho', 'Pilas y baterías, termómetros de mercurio, restos de pintura, aceite de motor y lamparitas no van al contenedor ni a la campana: necesitan un punto de recepción especial.', 'Si sos chico y encontrás una pila suelta o un termómetro roto, no lo toques: avisale a una persona adulta.', (select id from ac_fuentes where slug = 'epa'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.que_es_ecosistema', 'tronco', 'Qué es un ecosistema', 'Un ecosistema son los seres vivos de un lugar, el ambiente físico que los rodea y —sobre todo— las relaciones entre ellos.', 'La palabra clave es "relaciones": un ecosistema no es una lista de especies, es lo que se hacen entre sí.', (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -1.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.todo_esta_conectado', 'tronco', 'Todo está conectado', 'Tocar una parte de un ecosistema mueve otras partes, incluso las que parecen no tener nada que ver.', null, (select id from ac_fuentes where slug = 'ipbes-global'), 1, -1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.servicios_ecosistemicos', 'tronco', 'Lo que la naturaleza hace por nosotros', 'Los ecosistemas hacen trabajo gratis que nos sostiene: filtran agua, polinizan cultivos, dan sombra y guardan carbono.', 'Se los llama servicios ecosistémicos. Se notan sobre todo cuando faltan.', (select id from ac_fuentes where slug = 'ipbes-global'), 1, -0.7, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.escala_local_global', 'tronco', 'Lo local y lo global', 'Un mismo problema ambiental se ve distinto según la escala: lo que resuelve una cuadra puede no mover nada a nivel país, y al revés.', null, (select id from ac_fuentes where slug = 'unesco-ods'), 1, -0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.ciclos_materia', 'tronco', 'La materia da vueltas', 'En la naturaleza la materia no desaparece: circula. El agua, el carbono y los nutrientes hacen ciclos que vuelven a empezar.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 1, -0.8, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.leer_un_numero', 'tronco', 'Unidad, escala y fuente', 'Un número ambiental solo significa algo si sabés su unidad, respecto de qué se mide y quién lo publicó.', '"Reducimos un 40 %" no dice nada hasta que aparece "¿respecto de qué año?".', (select id from ac_fuentes where slug = 'chequeado'), 1, -0.9, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.orden_de_magnitud', 'tronco', 'Orden de magnitud', 'Antes de comparar dos cosas conviene preguntarse si están en la misma escala: diez, mil o un millón cambian la decisión, no el detalle.', null, (select id from ac_fuentes where slug = 'owid-alimentos'), 1, -0.4, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.por_persona_vs_total', 'tronco', 'Por persona o en total', 'El mismo dato cambia de sentido según se exprese en total o por persona: un país grande emite mucho y puede emitir poco por habitante.', null, (select id from ac_fuentes where slug = 'owid-impactos-alimentos'), 2, 0.3, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.promedio_engana', 'tronco', 'Cuándo el promedio engaña', 'Un promedio esconde la distribución: si unos pocos consumen muchísimo, el promedio no describe a casi nadie.', null, (select id from ac_fuentes where slug = 'chequeado'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.stock_vs_flujo', 'tronco', 'Stock y flujo', 'Emitir menos cada año frena la subida pero no la revierte: el CO₂ se acumula, así que lo que importa es el stock, no el caudal.', 'Por eso "reducir emisiones" y "dejar de aumentar la concentración" no son lo mismo.', (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.7, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.observacion_vs_inferencia', 'tronco', 'Observación e inferencia', 'Observar es registrar lo que pasa; inferir es explicar por qué. Confundirlas es la fuente más común de error.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 1, -0.6, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.evidencia_y_fuente', 'tronco', 'De dónde salió el dato', 'Una afirmación ambiental vale lo que vale su fuente: quién midió, cuándo y con qué método.', null, (select id from ac_fuentes where slug = 'chequeado'), 1, -0.5, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.correlacion_causalidad', 'tronco', 'Correlación no es causalidad', 'Que dos cosas suban juntas no prueba que una cause la otra: puede haber una tercera causa, o pura casualidad.', null, (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.incertidumbre', 'tronco', 'La incertidumbre no es ignorancia', 'Un rango de error dice cuánto se sabe, no que no se sepa nada. Un dato con barras de error es más confiable que uno sin ellas.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.6, '{"teen","adult"}'::text[], false, 'aprobado')
on conflict (slug) do update set rama_slug = excluded.rama_slug, titulo_es = excluded.titulo_es,
  enunciado_es = excluded.enunciado_es, detalle_es = excluded.detalle_es, fuente_id = excluded.fuente_id,
  anillo = excluded.anillo, dificultad_base = excluded.dificultad_base,
  age_groups = excluded.age_groups, sensible = excluded.sensible, status = 'aprobado';
insert into ac_conceptos (slug, rama_slug, titulo_es, enunciado_es, detalle_es, fuente_id, anillo, dificultad_base, age_groups, sensible, status) values
  ('tronco.consenso_cientifico', 'tronco', 'Cómo se construye un consenso', 'El consenso científico no es una votación: es lo que queda en pie después de que muchos equipos independientes intentan refutarlo.', null, (select id from ac_fuentes where slug = 'ipcc-ar6'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.no_todo_pesa_igual', 'tronco', 'No todas las acciones pesan igual', 'Dos acciones que se sienten igual de virtuosas pueden diferir cien veces en impacto real. La sensación no es una medida.', null, (select id from ac_fuentes where slug = 'owid-alimentos'), 2, 0.1, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.individual_y_colectivo', 'tronco', 'Lo individual y lo colectivo', 'La acción individual importa sobre todo como puerta de entrada a la acción colectiva: cambia hábitos, mercados y reglas cuando se organiza.', 'Ni "no sirve para nada" ni "con reciclar en casa alcanza". Las dos frases fallan por el mismo lado.', (select id from ac_fuentes where slug = 'naaee-guidelines'), 2, 0.3, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.efecto_rebote', 'tronco', 'El efecto rebote', 'Cuando algo se vuelve más eficiente suele usarse más, y parte del ahorro se pierde. Eficiencia no es lo mismo que reducción.', null, (select id from ac_fuentes where slug = 'iea-energia'), 3, 0.9, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.compensacion_no_es_evitar', 'tronco', 'Compensar no es evitar', 'Pagar una compensación de carbono no borra la emisión: la traslada a un proyecto que puede tardar décadas en absorberla, si la absorbe.', null, (select id from ac_fuentes where slug = 'carbon-brief'), 3, 1, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.jerarquia_decisiones', 'tronco', 'Evitar, reducir, sustituir, compensar', 'Frente a cualquier impacto el orden es siempre el mismo: primero evitarlo, después reducirlo, después sustituirlo y recién al final compensarlo.', null, (select id from ac_fuentes where slug = 'epa'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.derecho_ambiente_sano', 'tronco', 'Derecho a un ambiente sano', 'El artículo 41 de la Constitución argentina reconoce el derecho a un ambiente sano y, en la misma frase, el deber de preservarlo.', null, (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 2, 0, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.presupuestos_minimos', 'tronco', 'Presupuestos mínimos', 'Una ley de presupuestos mínimos fija el piso de protección para todo el país; cada provincia puede exigir más, nunca menos.', null, (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 2, 0.5, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.principio_precautorio', 'tronco', 'El principio precautorio', 'Cuando hay riesgo de daño grave o irreversible, la falta de certeza científica no puede usarse como excusa para no actuar.', null, (select id from ac_fuentes where slug = 'ley-25675-ambiente'), 3, 0.8, '{"teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.educacion_ambiental_ley', 'tronco', 'La educación ambiental es ley', 'La Ley 27.621 hace obligatoria y transversal la educación ambiental integral en todos los niveles, y la extiende a la educación no formal.', null, (select id from ac_fuentes where slug = 'ley-27621-eai'), 2, 0.2, '{"kid","teen","adult"}'::text[], false, 'aprobado'),
  ('tronco.acceso_informacion', 'tronco', 'Podés pedir la información', 'El acceso a la información ambiental es un derecho: cualquier persona puede pedirla al Estado sin explicar para qué la quiere.', null, (select id from ac_fuentes where slug = 'escazu'), 2, 0.4, '{"teen","adult"}'::text[], false, 'aprobado')
