  ('residuos.los-plasticos.3', (select id from ac_gajos where slug = 'residuos.los-plasticos'), 'La palabra biodegradable', 'Dónde se degrada, con qué condiciones y en cuánto tiempo.', 5, 3, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('residuos.los-plasticos.4', (select id from ac_gajos where slug = 'residuos.los-plasticos'), 'Cuál sí, cuál no', 'Tres envases sobre la mesada y una decisión para cada uno.', 5, 4, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('residuos.quien-recicla.1', (select id from ac_gajos where slug = 'residuos.quien-recicla'), 'El trabajo que lo sostiene', 'Quiénes recuperan el material en el AMBA y cómo se organizaron.', 5, 1, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('residuos.quien-recicla.2', (select id from ac_gajos where slug = 'residuos.quien-recicla'), 'Las reglas de juego', 'Basura Cero y la responsabilidad de quien fabrica el envase.', 6, 2, '{"teen","adult"}'::text[], 'aprobado'),
  ('residuos.quien-recicla.3', (select id from ac_gajos where slug = 'residuos.quien-recicla'), 'Leer la etiqueta con lupa', 'Símbolos que prometen, leyes que obligan.', 6, 3, '{"teen","adult"}'::text[], 'aprobado'),
  ('residuos.circular.1', (select id from ac_gajos where slug = 'residuos.circular'), 'Línea recta o círculo', 'Dos formas de pensar el mismo producto.', 5, 1, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('residuos.circular.2', (select id from ac_gajos where slug = 'residuos.circular'), 'Lo que no va al tacho', 'Pilas, pinturas y aparatos: dónde recibe cada uno.', 5, 2, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('residuos.circular.3', (select id from ac_gajos where slug = 'residuos.circular'), 'El aparato que ya tenés', 'Reparar, alargar, y recién después reciclar.', 5, 3, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('residuos.circular.4', (select id from ac_gajos where slug = 'residuos.circular'), 'Cerrar el círculo', 'Del diseño al punto de recepción, la vuelta completa.', 4, 4, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.sistemas-vivos.1', (select id from ac_gajos where slug = 'tronco.sistemas-vivos'), 'Qué es un ecosistema', 'Empezamos por la palabra que sostiene todas las demás.', 4, 1, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.sistemas-vivos.2', (select id from ac_gajos where slug = 'tronco.sistemas-vivos'), 'El trabajo que no se cobra', 'Sombra, agua limpia y polinización: quién los hace.', 4, 2, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.sistemas-vivos.3', (select id from ac_gajos where slug = 'tronco.sistemas-vivos'), 'Vueltas que no terminan', 'El agua y el carbono no se gastan: cambian de lugar.', 4, 3, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.sistemas-vivos.4', (select id from ac_gajos where slug = 'tronco.sistemas-vivos'), 'Tu cuadra y el planeta', 'Cuándo una acción chica alcanza y cuándo no.', 5, 4, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.leer-numeros.1', (select id from ac_gajos where slug = 'tronco.leer-numeros'), 'Con qué unidad', 'Litros, kilos, kilovatios: si no está la unidad, no hay dato.', 4, 1, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.leer-numeros.2', (select id from ac_gajos where slug = 'tronco.leer-numeros'), 'Grande, gigante o enorme', 'Entrenar la intuición de escala vale más que memorizar cifras.', 4, 2, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.leer-numeros.3', (select id from ac_gajos where slug = 'tronco.leer-numeros'), 'Total o por persona', 'La misma tabla, dos conclusiones opuestas.', 5, 3, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.leer-numeros.4', (select id from ac_gajos where slug = 'tronco.leer-numeros'), 'La bañadera y la canilla', 'Por qué bajar emisiones no baja la concentración.', 5, 4, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.como-se-sabe.1', (select id from ac_gajos where slug = 'tronco.como-se-sabe'), 'Lo que viste y lo que pensás', 'Separar el registro de la explicación.', 4, 1, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.como-se-sabe.2', (select id from ac_gajos where slug = 'tronco.como-se-sabe'), 'Pedile la fuente', 'Tres preguntas que desarman casi cualquier dato dudoso.', 4, 2, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.como-se-sabe.3', (select id from ac_gajos where slug = 'tronco.como-se-sabe'), 'Juntos no es por eso', 'La trampa favorita de los gráficos.', 5, 3, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.como-se-sabe.4', (select id from ac_gajos where slug = 'tronco.como-se-sabe'), 'Qué significa "hay consenso"', 'Y por qué no es lo mismo que "todos opinan igual".', 5, 4, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.donde-pesa.1', (select id from ac_gajos where slug = 'tronco.donde-pesa'), 'Cien veces de diferencia', 'Dos acciones que parecen iguales y no lo son.', 5, 1, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.donde-pesa.2', (select id from ac_gajos where slug = 'tronco.donde-pesa'), 'Vos solo y vos con otros', 'Dónde termina lo que podés hacer en tu casa.', 5, 2, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.donde-pesa.3', (select id from ac_gajos where slug = 'tronco.donde-pesa'), 'Cuando ahorrar hace gastar', 'El rebote, explicado con la luz de tu casa.', 5, 3, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.donde-pesa.4', (select id from ac_gajos where slug = 'tronco.donde-pesa'), 'El último recurso', 'Por qué compensar va al final de la lista.', 5, 4, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.reglas-del-juego.1', (select id from ac_gajos where slug = 'tronco.reglas-del-juego'), 'Un derecho y un deber', 'El artículo 41, en criollo.', 4, 1, '{"kid","teen","adult"}'::text[], 'aprobado'),
  ('tronco.reglas-del-juego.2', (select id from ac_gajos where slug = 'tronco.reglas-del-juego'), 'El piso y el techo', 'Qué puede hacer Nación y qué puede hacer tu provincia.', 5, 2, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.reglas-del-juego.3', (select id from ac_gajos where slug = 'tronco.reglas-del-juego'), 'En la duda, cuidar', 'El principio precautorio y por qué existe.', 5, 3, '{"teen","adult"}'::text[], 'aprobado'),
  ('tronco.reglas-del-juego.4', (select id from ac_gajos where slug = 'tronco.reglas-del-juego'), 'Preguntar es gratis', 'Cómo se pide un dato ambiental y quién tiene que dártelo.', 5, 4, '{"teen","adult"}'::text[], 'aprobado')
