  ('residuos.cooperativas_faccyr', 'residuos.recuperadores_urbanos', 1),
  ('residuos.ley_basura_cero', 'residuos.relleno_sanitario', 1),
  ('residuos.ley_basura_cero', 'tronco.presupuestos_minimos', 0.5),
  ('residuos.rep_envases', 'residuos.jerarquia_residuos', 1),
  ('residuos.rep_envases', 'tronco.individual_y_colectivo', 0.5),
  ('residuos.greenwashing_mobius', 'residuos.que_es_reciclable', 1),
  ('residuos.greenwashing_mobius', 'tronco.evidencia_y_fuente', 0.7),
  ('residuos.lineal_vs_circular', 'residuos.jerarquia_residuos', 1),
  ('residuos.lineal_vs_circular', 'tronco.ciclos_materia', 0.6)
) as v(cs, rs, f)
join ac_conceptos c on c.slug = v.cs
join ac_conceptos r on r.slug = v.rs
on conflict (concepto_id, requiere_id) do update set fuerza = excluded.fuerza;
