-- ── Creencias falsas documentadas ──────────────────────────────────────
insert into ac_misconceptions (slug, concepto_id, creencia_es, correccion_es, fuente_id) values
  ('agua.mito_embotellada', (select id from ac_conceptos where slug = 'agua.agua_de_red_controlada'), 'El agua embotellada es más segura que la de la canilla.', 'La botella convence porque viene cerrada, con marca y con una etiqueta que habla de montañas: se ve el envase y no se ve el control. El agua de red se trata y se analiza de forma periódica y esos resultados son públicos; la embotellada agrega plástico, transporte y precio sin ser sistemáticamente más segura.', (select id from ac_fuentes where slug = 'acumar')),
  ('agua_azul.mito_humedal_baldio', (select id from ac_conceptos where slug = 'agua_azul.lo_que_hace_un_humedal'), 'Los humedales son terrenos baldíos, embarrados e inútiles: conviene rellenarlos y construir.', 'Parecen vacíos porque no tienen nada construido encima, y esa es exactamente la trampa. Un humedal amortigua crecidas, filtra agua y guarda carbono; rellenarlo es por lo que las inundaciones del AMBA empeoran cada vez que llueve fuerte.', (select id from ac_fuentes where slug = 'ramsar')),
  ('agua_azul.mito_basura_de_barcos', (select id from ac_conceptos where slug = 'agua_azul.origen_terrestre'), 'El plástico del mar lo tiran sobre todo los barcos.', 'Es cómodo pensarlo así porque deja el problema lejos y en manos de otro. La mayor parte se genera en tierra y viaja por ríos y desagües: la basura que se vuela de una vereda del AMBA tiene camino directo al Río de la Plata.', (select id from ac_fuentes where slug = 'unep')),
  ('aire_suelo.mito_ozono_calentamiento', (select id from ac_conceptos where slug = 'aire_suelo.capa_de_ozono'), 'El agujero de la capa de ozono es lo que causa el calentamiento global.', 'La trampa es que los dos suenan a "problema del cielo" y aparecieron en las noticias en la misma época. Pero son mecanismos separados: el ozono se agota por los CFC, pasa en la estratósfera y afecta la radiación ultravioleta; el calentamiento lo causan los gases de efecto invernadero, pasa en la tropósfera y atrapa calor.', (select id from ac_fuentes where slug = 'ncse-ozono')),
  ('alimentacion.mito_light_es_sano', (select id from ac_conceptos where slug = 'alimentacion.ultraprocesados'), 'Si el frente del envase dice "natural" o "light", es una opción saludable.', 'La trampa es que el frente del envase lo escribe quien vende, y está diseñado para tranquilizarte en dos segundos. La información con reglas está en otro lado: en los octógonos y en la lista de ingredientes. Un producto puede ser light en grasas y tener exceso de azúcares al mismo tiempo.', (select id from ac_fuentes where slug = 'fao')),
  ('alimentacion.mito_fecha_vencida', (select id from ac_conceptos where slug = 'alimentacion.fechas_de_vencimiento'), 'Si pasó la fecha impresa en el envase, el alimento ya no se puede comer.', 'La trampa es que las dos fechas se escriben parecido y en el mismo lugar, así que el cerebro las lee como una sola. Pero "preferentemente antes de" habla de textura, color y sabor, no de seguridad: un paquete de fideos o una lata siguen siendo comida. La que sí es una fecha límite es "consumir antes de", la de los frescos.', (select id from ac_fuentes where slug = 'fao')),
  ('alimentacion.mito_comer_local', (select id from ac_conceptos where slug = 'alimentacion.transporte_es_poco'), 'Comer local siempre reduce más emisiones que cambiar de dieta.', 'La trampa es que la distancia se puede imaginar: un camión cruzando el país es una imagen nítida, y el metano de una vaca o el desmonte de una hectárea no lo son. Pero en la mayoría de los alimentos el transporte es una porción chica de las emisiones y el grueso ya se generó en la producción. Comprar cerca suma por otros motivos; para bajar emisiones pesa más qué ponés en el plato que cuántos kilómetros hizo.', (select id from ac_fuentes where slug = 'owid-alimentos')),
  ('animales.mito_murcielagos', (select id from ac_conceptos where slug = 'animales.murcielagos_urbanos'), 'Los murciélagos son ratas voladoras, se te enredan en el pelo y chupan sangre.', 'La fama viene del cine y de que vuelan de noche, cuando no se los ve bien. Los murciélagos urbanos argentinos son insectívoros y controlan mosquitos; se orientan por ecolocalización con precisión milimétrica, así que enredarse en un pelo es justo lo que no les pasa. De más de 1.400 especies en el mundo, solo tres se alimentan de sangre.', (select id from ac_fuentes where slug = 'sib-apn')),
  ('animales.mito_sapos_aranas', (select id from ac_conceptos where slug = 'animales.sapos_y_aranas'), 'Los sapos causan verrugas y a las arañas de casa hay que matarlas.', 'Son dos creencias viejas que se repiten sin pensarlas. Las verrugas las causa un virus, no un sapo. Y las arañas de casa comen justamente los insectos que sí transmiten enfermedades: matarlas te deja peor que antes.', (select id from ac_fuentes where slug = 'sib-apn')),
  ('animales.mito_cotorra_plaga', (select id from ac_conceptos where slug = 'animales.cotorra_es_nativa'), 'Las cotorras y las palomas son plagas exóticas que invadieron la ciudad.', 'Se las mete en la misma bolsa porque las dos son abundantes y molestan, y ahí está el error: abundante no es lo mismo que exótica. La cotorra es nativa de la Argentina; las introducidas son la paloma doméstica, el gorrión y el estornino.', (select id from ac_fuentes where slug = 'invasoras-mayds')),
  ('animales.mito_alimentar_fauna', (select id from ac_conceptos where slug = 'animales.no_alimentar'), 'Darles de comer a los animales silvestres los ayuda.', 'Nace de un impulso bueno, que es justo lo que la vuelve difícil de discutir. Pero genera dependencia, desnutrición por dieta inadecuada, agrupamientos donde se transmiten enfermedades, y habituación a las personas. Ayudar de verdad es dejar comida disponible en el ambiente, no en la mano.', (select id from ac_fuentes where slug = 'protocolo-fauna-cba')),
  ('animales.mito_pichon_caido', (select id from ac_conceptos where slug = 'animales.volanton_vs_pichon'), 'Si encontrás un pichón en el suelo hay que llevárselo a casa para salvarlo.', 'Parece lo más compasivo y por eso se hace tanto. La mayoría de los pajaritos que se encuentran en el suelo son volantones: están emplumados, están aprendiendo a volar y sus padres los siguen alimentando ahí. Llevárselo es separarlo de su familia. Dejalo donde está o subilo a una rama, alejá a las mascotas y avisale a una persona adulta si está claramente herido.', (select id from ac_fuentes where slug = 'protocolo-fauna-cba')),
  ('animales.mito_viboras_atacan', (select id from ac_conceptos where slug = 'animales.viboras_no_atacan'), 'Las víboras atacan a la gente, así que si ves una hay que matarla.', 'El miedo es real y viejo, pero la conducta que se le atribuye no. Las serpientes muerden defendiéndose, casi siempre cuando alguien las pisa o intenta agarrarlas. La mayoría de las especies argentinas no son venenosas, alejarse resuelve el 100 % de los casos, y matarlas es ilegal para las especies protegidas.', (select id from ac_fuentes where slug = 'ley-22421-fauna')),
  ('animales.mito_apex_maquinas_de_matar', (select id from ac_conceptos where slug = 'animales.apex_no_cazan_gente'), 'Los tiburones, los pumas y los yaguaretés son máquinas de matar humanos.', 'La imagen viene del cine y de que los ataques, cuando ocurren, son noticia mundial. En los hechos evitan a las personas, y son especies clave: cuando desaparecen, la estructura trófica entera se reorganiza y el ecosistema se empobrece.', (select id from ac_fuentes where slug = 'sarem-2019')),
  ('animales.mito_carpinchos_invaden', (select id from ac_conceptos where slug = 'animales.nordelta'), 'Los carpinchos son roedores peligrosos que invadieron los barrios.', 'Suena convincente porque uno ve los animales aparecer "de golpe" en las fotos. Pero el orden fue el inverso: el barrio se levantó sobre su humedal. Son herbívoros, sociales y no agresivos, y lo que hay que discutir es cómo se ocupó ese suelo, no cómo sacarlos.', (select id from ac_fuentes where slug = 'conicet-carpinchos')),
  ('animales.mito_dd_esta_bien', (select id from ac_conceptos where slug = 'animales.dd_no_es_esta_bien'), 'Si una especie figura como "Datos Insuficientes" es porque está bien.', 'La sigla se lee como si fuera una categoría tranquilizadora, y es lo contrario: significa que no hay información para evaluarla. Varias especies DD están entre las más comprometidas precisamente porque nadie fue a mirarlas.', (select id from ac_fuentes where slug = 'iucn-red-list')),
  ('animales.mito_perros_sueltos', (select id from ac_conceptos where slug = 'animales.perros_y_gatos'), 'Los perros sueltos no le hacen nada a la fauna: son animales domésticos.', 'Cuesta verlo porque el perro que uno conoce es el de casa. Pero a escala de país la depredación por perros afecta al 22 % de las especies de mamíferos argentinos, un peso comparable al de los atropellamientos en ruta. Correa en zonas naturales no es un capricho.', (select id from ac_fuentes where slug = 'sarem-2019')),
  ('animales.mito_soltar_es_liberar', (select id from ac_conceptos where slug = 'animales.soltar_no_es_liberar'), 'Si no podés tener más a tu mascota, soltarla en el campo o en un río es devolverle la libertad.', 'La palabra "liberar" es la que engaña. Un animal criado en cautiverio no sabe buscar comida ni evitar depredadores, así que casi siempre muere; y el que sobrevive puede volverse invasor o traer enfermedades a la fauna local. Lo correcto es buscarle un hogar o contactar a la autoridad de fauna.', (select id from ac_fuentes where slug = 'invasoras-mayds')),
  ('animales.mito_comprar_rescata', (select id from ac_conceptos where slug = 'animales.comprar_es_demanda'), 'Si comprás el loro o la tortuga que estaba en una jaula, lo estás rescatando.', 'La intención es genuina y por eso el argumento circula tanto. Pero la compra le confirma al vendedor que hay mercado y financia la próxima captura. Rescatar de verdad es denunciar ante la autoridad de fauna.', (select id from ac_fuentes where slug = 'ley-22421-fauna')),
  ('animales.mito_zoologicos_solo_entretienen', (select id from ac_conceptos where slug = 'animales.zoologicos_debate'), 'Los zoológicos y acuarios existen solo para entretener.', 'Es una simplificación de las dos puntas. Instituciones como el Ecoparque o Temaikèn hacen cría para reintroducción, rescate de fauna decomisada e investigación. Y a la vez la objeción ética al cautiverio es legítima y sigue abierta. Lo correcto es presentarlo como debate, no como veredicto.', (select id from ac_fuentes where slug = 'ecoparque-conservacion')),
  ('ciencia.mito_invierno_frio', (select id from ac_conceptos where slug = 'ciencia.serie_vs_punto'), 'Este invierno hizo muchísimo frío, así que el calentamiento global no puede ser cierto.', 'Es tentador porque se apoya en algo que uno vivió en el cuerpo. Pero tiempo no es clima: una ola de frío es un punto en una serie ruidosa, y la tendencia se mide en décadas y sobre todo el planeta.', (select id from ac_fuentes where slug = 'ipcc-ar6')),
  ('ciencia.mito_clima_siempre_cambio', (select id from ac_conceptos where slug = 'ciencia.atribucion_climatica'), 'El clima siempre cambió, así que lo de ahora también es natural.', 'La primera mitad es cierta y por eso convence: el clima varió muchas veces. Lo que cambia el argumento son la velocidad y la causa. El ritmo actual no tiene precedente en los registros y los estudios de atribución señalan las emisiones humanas, no un ciclo natural.', (select id from ac_fuentes where slug = 'ipcc-ar6')),
  ('consumo.mito_bolsa_papel', (select id from ac_conceptos where slug = 'consumo.cambiar_material_no_alcanza'), 'Las bolsas de papel siempre son mejores que las de plástico.', 'La trampa es tentadora: el papel se ve natural, se rompe solo y no queda flotando en el río. Pero producirlo pide más energía y más agua, y pesa más para transportar, así que la de papel recién empata si la reusás varias veces o la compostás. La que gana de verdad es la reutilizable que usás muchas decenas de veces.', (select id from ac_fuentes where slug = 'unep')),
  ('digital.mito_nube_no_es_fisica', (select id from ac_conceptos where slug = 'digital.que_es_un_centro_de_datos'), 'La nube no es física: los archivos están "en el aire", no en ningún lado.', 'La metáfora es tan buena que tapa la cosa. La nube son galpones con servidores, refrigeración y electricidad, y la IEA proyecta que su demanda eléctrica se duplique hacia 2030, hasta unos 945 TWh.', (select id from ac_fuentes where slug = 'iea-energia')),
  ('digital.mito_menos_emails', (select id from ac_conceptos where slug = 'digital.el_email_no_es_el_problema'), 'Mandar menos correos y borrar los viejos salva el planeta.', 'Es tentador porque es una acción concreta y visible, pero está en el orden de magnitud equivocado. Los impactos digitales que pesan son la fabricación del dispositivo y la electricidad de los centros de datos: alargar dos años la vida de tu teléfono supera un año entero de higiene de correo.', (select id from ac_fuentes where slug = 'carbon-brief')),
  ('energia.mito_kw_es_kwh', (select id from ac_conceptos where slug = 'energia.energia_vs_potencia'), 'kW y kWh son dos maneras de escribir lo mismo.', 'La trampa es que se escriben casi igual y aparecen juntas en la misma boleta. Pero kW es velocidad de consumo y kWh es cantidad consumida: un aparato de 1 kW prendido una hora gasta 1 kWh, y el mismo aparato prendido seis minutos gasta la décima parte.', (select id from ac_fuentes where slug = 'iea-energia')),
  ('energia.mito_cargador_enchufado', (select id from ac_conceptos where slug = 'energia.consumo_fantasma'), 'Dejar el cargador enchufado sin nada conectado no consume nada.', 'Es tentador porque no se ve ni se escucha nada: el cargador no hace ruido, no se calienta casi y parece apagado. Igual sigue tomando un poquito de corriente mientras está enchufado. Chico, sí; cero, no.', (select id from ac_fuentes where slug = 'epa')),
  ('energia.mito_standby_es_el_problema', (select id from ac_conceptos where slug = 'energia.donde_esta_el_grueso'), 'Con desenchufar todo lo que queda en espera alcanza para que baje la factura.', 'Engancha porque es una acción visible, fácil y que se siente virtuosa, así que uno le atribuye un tamaño que no tiene. El standby existe pero es una porción chica: la aguja la mueven la climatización, el agua caliente y los equipos viejos. Desenchufá igual, y además revisá el aire y el termotanque.', (select id from ac_fuentes where slug = 'iea-energia')),
  ('energia.mito_nuclear_emisora', (select id from ac_conceptos where slug = 'energia.nuclear_bajas_emisiones'), 'La energía nuclear es una de las que más CO₂ emite.', 'La imagen ayuda a la confusión: las torres de refrigeración largan una columna blanca enorme que parece humo y es vapor de agua. Y como el tema nuclear pesa, uno tiende a colgarle todos los problemas juntos. Por kWh, sus emisiones están en la banda baja, con la eólica y la hidro. Discutir residuos, costo y riesgo tiene sentido; discutir su CO₂, no.', (select id from ac_fuentes where slug = 'ipcc-ar6')),
  ('energia.mito_sol_no_siempre_brilla', (select id from ac_conceptos where slug = 'energia.intermitencia'), 'Las renovables no funcionan porque el sol no siempre brilla y el viento no siempre sopla.', 'La intuición arranca bien —de verdad no están siempre— pero se queda mirando un panel solo en vez de la red entera. No está nublado en toda la Argentina al mismo tiempo, en la Patagonia el viento sopla también de noche, parte de la demanda se puede correr de horario y las baterías guardan el excedente del mediodía. La intermitencia es un problema de ingeniería que se administra, no un veredicto sobre la tecnología.', (select id from ac_fuentes where slug = 'iea-energia')),
  ('movilidad.mito_electrico_no_contamina', (select id from ac_conceptos where slug = 'movilidad.electrico_sin_tubo_de_escape'), 'Los autos eléctricos no contaminan.', 'La trampa es tentadora porque una parte es verdad y encima es la parte que se ve: en la esquina no hay humo ni olor a nafta, y el aire del barrio mejora de verdad. Lo que no se ve queda lejos —la fábrica de la batería y la usina que genera la electricidad— y ahí sí hay emisiones. Sumando toda la vida del auto, el eléctrico emite bastante menos que un naftero comparable, pero no cero.', (select id from ac_fuentes where slug = 'icct-ev')),
  ('movilidad.mito_electrico_igual_o_peor', (select id from ac_conceptos where slug = 'movilidad.matriz_electrica_importa'), 'Total el eléctrico contamina igual o más, porque la electricidad también sale de quemar algo.', 'Es la sobrecorrección del mito anterior y suena sofisticada, porque señala algo real: la generación eléctrica emite. Pero el motor eléctrico aprovecha mucho mejor la energía, y las comparaciones de ciclo de vida dan a favor del eléctrico en prácticamente todas las redes estudiadas, incluso en las bastante sucias. La diferencia es de cuánto, no de para qué lado.', (select id from ac_fuentes where slug = 'carbon-brief')),
  ('movilidad.mito_mas_carriles', (select id from ac_conceptos where slug = 'movilidad.demanda_inducida'), 'Si ensanchan la avenida, se destraba el tránsito.', 'Es tentador porque las primeras semanas es cierto y se siente en el cuerpo: se viaja más rápido. Eso mismo es lo que atrae viajes nuevos —gente que antes tomaba el colectivo, salía a otra hora o no viajaba— hasta que la avenida vuelve a estar igual, ahora con más autos. Lo que cambia el tiempo de viaje en serio es mover gente en menos vehículos.', (select id from ac_fuentes where slug = 'ipcc-ar6')),
  ('movilidad.mito_compensar_vuelo', (select id from ac_conceptos where slug = 'movilidad.compensar_no_es_no_emitir'), 'Si pago la compensación del pasaje, el vuelo queda en cero.', 'Es tentador porque el checkbox aparece justo cuando estás incómodo y cuesta poca plata: resuelve la culpa en un clic. Pero el CO₂ ya se emite igual, y la compensación es una promesa de que en otro lado se evita o se captura una cantidad parecida, con calidad muy despareja. Compensar va después de evitar y de reducir, nunca en lugar de ellos.', (select id from ac_fuentes where slug = 'carbon-brief')),
  ('plantas.mito_cualquier_arbol', (select id from ac_conceptos where slug = 'plantas.plantar_la_correcta'), 'Sembrar cualquier árbol es bueno para el ambiente.', 'Es tentador porque plantar se siente siempre como sumar, y un árbol es un árbol. Pero plantar exóticas como el ligustro o la acacia negra puede terminar invadiendo ecosistemas nativos y bajando la biodiversidad del lugar: lo que decide el resultado es la especie, no el gesto.', (select id from ac_fuentes where slug = 'invasoras-mayds')),
  ('plantas.mito_replantar_queda_igual', (select id from ac_conceptos where slug = 'plantas.restaurar_no_es_deshacer'), 'Si un ecosistema se destruye, después se replanta y queda igual.', 'La trampa es que las plantas se ven y vuelven: en dos años hay verde otra vez y parece resuelto. Lo que no vuelve a pedido es lo que no se ve — el banco de semillas, los hongos del suelo, quién poliniza a quién. La restauración es lenta, parcial y cara, y por eso cuidar lo que sigue en pie rinde muchísimo más que repararlo después.', (select id from ac_fuentes where slug = 'ipbes-global')),
  ('plantas.mito_deforestacion_frenada', (select id from ac_conceptos where slug = 'plantas.ley_bosques'), 'La deforestación en Argentina ya se frenó con la Ley de Bosques.', 'Es tentador porque la ley existe, es buena y efectivamente hizo caer el ritmo de desmonte: parece un problema con la casilla ya tildada. Pero una ley sancionada no es una ley cumplida: sigue habiendo desmonte ilegal, sobre todo en el Chaco, y las recategorizaciones del OTBN provincial se discuten caso por caso. Que exista la norma es el principio del control, no el final.', (select id from ac_fuentes where slug = 'ley-bosques-26331')),
  ('residuos.mito_contenedor_recicla', (select id from ac_conceptos where slug = 'residuos.contaminacion_cruzada'), 'Lo que tiro en el contenedor de reciclables se recicla.', 'La trampa es buena porque desde la vereda el gesto se ve idéntico: la tapa se cierra igual con el frasco enjuagado que con el sucio, y la sensación de haber hecho lo correcto es la misma. Lo que decide viene después: la grasa, los restos de comida y el papel mojado bajan la calidad de todo el lote y pueden mandarlo entero a enterramiento. Seco y limpio es lo que convierte el gesto en reciclado.', (select id from ac_fuentes where slug = 'epa')),
  ('residuos.mito_reciclaje_resuelve', (select id from ac_conceptos where slug = 'residuos.reciclar_no_es_infinito'), 'Reciclando bien el plástico, el problema del plástico está resuelto.', 'Es tentador porque el reciclaje es lo único de toda la cadena que se ve y se hace con las manos: separás, dejás la bolsa y sentís que el círculo se cerró. Pero la mayor parte del plástico que se fabricó nunca se recicló, y el que sí baja de calidad en cada vuelta hasta salir del circuito. El reciclaje llega tarde, cuando el envase ya existe; lo que mueve la aguja es que se fabriquen menos envases y se diseñen mejor.', (select id from ac_fuentes where slug = 'yale-reciclaje')),
  ('residuos.mito_biodegradable', (select id from ac_conceptos where slug = 'residuos.biodegradable_no_es_magia'), 'Si dice biodegradable, se deshace solo en cualquier lado.', 'La palabra es tentadora porque suena a que la naturaleza se ocupa sola, y en el laboratorio es cierta: el material efectivamente se degrada, con temperatura, humedad y tiempo controlados. Enterrado sin oxígeno, tirado en la vereda o flotando en el río no tiene nada de eso y se queda ahí igual que cualquier plástico. La pregunta útil no es si es biodegradable, sino dónde termina.', (select id from ac_fuentes where slug = 'unep'))
on conflict (slug) do update set concepto_id = excluded.concepto_id, creencia_es = excluded.creencia_es,
  correccion_es = excluded.correccion_es, fuente_id = excluded.fuente_id;
insert into ac_misconceptions (slug, concepto_id, creencia_es, correccion_es, fuente_id) values
  ('tronco.mito_individual_no_sirve', (select id from ac_conceptos where slug = 'tronco.individual_y_colectivo'), 'El impacto individual no sirve para nada (o, al revés: con reciclar en casa alcanza).', 'Las dos versiones fallan igual. La conducta individual pesa sobre todo como entrada a la acción colectiva, política y de consumo, que es donde cambian las reglas.', (select id from ac_fuentes where slug = 'naaee-guidelines'))
on conflict (slug) do update set concepto_id = excluded.concepto_id, creencia_es = excluded.creencia_es,
  correccion_es = excluded.correccion_es, fuente_id = excluded.fuente_id;

