  ((select id from ac_plantillas where generator_hash = 'plantas.cestos.nativa_exotica'), 96823186031713936, '{"tipo":"clasificar_en_cestos","enunciado":"Clasificá cada especie.","ayuda":null,"cestos":[{"id":"c1","nombre":"Nativa","color":null},{"id":"c2","nombre":"Exótica invasora","color":null}],"fichas":[{"id":"h6","texto":"Mora"},{"id":"h3","texto":"Aliso de río"},{"id":"h4","texto":"Palo borracho"},{"id":"h1","texto":"Ceibo"},{"id":"h7","texto":"Acacia negra"},{"id":"h5","texto":"Ligustro"},{"id":"h2","texto":"Sauce criollo"}]}'::jsonb, '{"explicacion":"El ligustro, la mora y la acacia negra están entre las invasoras que más presionan al monte blanco del Delta: crecen rápido, desplazan a las nativas y bajan la biodiversidad local. \"Crece en cualquier lado\" no es una virtud, es la definición del problema.","clave":{"h1":"c1","h2":"c1","h3":"c1","h4":"c1","h5":"c2","h6":"c2","h7":"c2"}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'invasoras-mayds')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.400, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'plantas.cestos.nativa_exotica'), 96824285543342147, '{"tipo":"clasificar_en_cestos","enunciado":"Clasificá cada especie. Pensá en el monte del Delta.","ayuda":null,"cestos":[{"id":"c1","nombre":"Nativa","color":null},{"id":"c2","nombre":"Exótica invasora","color":null}],"fichas":[{"id":"h1","texto":"Ceibo"},{"id":"h4","texto":"Palo borracho"},{"id":"h3","texto":"Aliso de río"},{"id":"h6","texto":"Mora"},{"id":"h5","texto":"Ligustro"},{"id":"h7","texto":"Acacia negra"},{"id":"h2","texto":"Sauce criollo"}]}'::jsonb, '{"explicacion":"El ligustro, la mora y la acacia negra están entre las invasoras que más presionan al monte blanco del Delta: crecen rápido, desplazan a las nativas y bajan la biodiversidad local. \"Crece en cualquier lado\" no es una virtud, es la definición del problema.","clave":{"h1":"c1","h2":"c1","h3":"c1","h4":"c1","h5":"c2","h6":"c2","h7":"c2"}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'invasoras-mayds')), '{"variante":0,"marco":"delta","region":"delta"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.400, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua.cestos.huella_colores'), 1779243235141590057, '{"tipo":"clasificar_en_cestos","enunciado":"Ubicá cada caso en su color.","ayuda":null,"cestos":[{"id":"c1","nombre":"Verde","color":null},{"id":"c2","nombre":"Azul","color":null},{"id":"c3","nombre":"Gris","color":null}],"fichas":[{"id":"h6","texto":"La necesaria para diluir fertilizante lixiviado"},{"id":"h4","texto":"Agua tomada de un río para una fábrica"},{"id":"h2","texto":"Humedad que la pastura consume sin riego"},{"id":"h3","texto":"Agua bombeada de una napa para regar"},{"id":"h5","texto":"La que haría falta para diluir un vertido"},{"id":"h1","texto":"Lluvia que el cultivo toma del suelo"}]}'::jsonb, '{"explicacion":"Verde es lluvia almacenada en el suelo, azul es agua superficial o subterránea que se extrae, y gris es la que haría falta para diluir la contaminación generada. No son intercambiables: un litro azul en una zona con estrés hídrico no vale lo mismo que uno verde.","clave":{"h1":"c1","h2":"c1","h3":"c2","h4":"c2","h5":"c3","h6":"c3"}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 2, 1.050, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'plantas.emparejar.ley_bosques'), 3750909598631998080, '{"tipo":"emparejar","enunciado":"Emparejá cada categoría con lo que permite.","ayuda":null,"izquierda":[{"id":"i1","texto":"Categoría I (rojo)"},{"id":"i2","texto":"Categoría II (amarillo)"},{"id":"i3","texto":"Categoría III (verde)"},{"id":"i4","texto":"OTBN"}],"derecha":[{"id":"d1","texto":"Muy alto valor de conservación: no se transforma"},{"id":"d3","texto":"Puede transformarse para otros usos"},{"id":"d2","texto":"Valor medio: uso sostenible, sin desmonte"},{"id":"d4","texto":"El mapa provincial que asigna las categorías"}]}'::jsonb, '{"explicacion":"La Ley 26.331 obliga a cada provincia a hacer su Ordenamiento Territorial de Bosques Nativos. El color no es una opinión: define qué se puede y qué no en cada parcela, y por eso las recategorizaciones se discuten tanto.","clave":{"i1":"d1","i2":"d2","i3":"d3","i4":"d4"}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ley-bosques-26331')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 2, 1.050, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.emparejar.leyes'), 6318295894559422503, '{"tipo":"emparejar","enunciado":"Emparejá cada norma con lo que hace.","ayuda":null,"izquierda":[{"id":"i1","texto":"Ley 26.331"},{"id":"i2","texto":"Ley 27.621"},{"id":"i3","texto":"Ley 22.421"},{"id":"i4","texto":"Acuerdo de Escazú"}],"derecha":[{"id":"d2","texto":"Educación ambiental integral"},{"id":"d3","texto":"Fauna silvestre"},{"id":"d1","texto":"Bosques nativos"},{"id":"d4","texto":"Información, participación y justicia ambiental"}]}'::jsonb, '{"explicacion":"Cuatro normas de alcance muy distinto: una protege un ecosistema, otra manda enseñar, otra regula el uso de la fauna y la cuarta garantiza que puedas enterarte y participar. Las cuatro se apoyan en el artículo 41 de la Constitución.","clave":{"i1":"d1","i2":"d2","i3":"d3","i4":"d4"}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ley-25675-ambiente')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 2, 1.300, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.emparejar.leyes'), 5785961842349385948, '{"tipo":"emparejar","enunciado":"Emparejá cada norma con lo que hace.","ayuda":null,"izquierda":[{"id":"i1","texto":"Artículo 41 de la Constitución"},{"id":"i2","texto":"Presupuestos mínimos"},{"id":"i3","texto":"Principio precautorio"},{"id":"i4","texto":"Ley 25.675"}],"derecha":[{"id":"d3","texto":"La falta de certeza no justifica no actuar"},{"id":"d1","texto":"Derecho a un ambiente sano y deber de preservarlo"},{"id":"d2","texto":"El piso de protección para todo el país"},{"id":"d4","texto":"Ley marco: principios y evaluación de impacto"}]}'::jsonb, '{"explicacion":"Los presupuestos mínimos fijan un piso: cada provincia puede exigir más, nunca menos. Y el principio precautorio es el que permite actuar frente a un riesgo grave antes de tener certeza científica completa.","clave":{"i1":"d1","i2":"d2","i3":"d3","i4":"d4"}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ley-25675-ambiente')), '{"variante":1,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 2, 1.500, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.emparejar.materiales'), 2058828363761682549, '{"tipo":"emparejar","enunciado":"Emparejá cada material con lo que le pasa.","ayuda":null,"izquierda":[{"id":"i1","texto":"Vidrio"},{"id":"i2","texto":"Plástico"},{"id":"i3","texto":"Tetrabrik"},{"id":"i4","texto":"Telgopor"}],"derecha":[{"id":"d1","texto":"Se recicla indefinidamente sin perder calidad"},{"id":"d2","texto":"Pierde calidad en cada ciclo de reciclado"},{"id":"d3","texto":"Multicapa: hay que separar cartón, aluminio y plástico"},{"id":"d4","texto":"Muy liviano y voluminoso: rara vez se recicla"}]}'::jsonb, '{"explicacion":"No todos los materiales se reciclan igual. Al plástico conviene evitarlo antes que reciclarlo, justamente porque cada ciclo lo degrada y termina en productos de menor valor.","clave":{"i1":"d1","i2":"d2","i3":"d3","i4":"d4"}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'yale-reciclaje')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.600, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua.om.huella_alimento'), 1127488231508674938, '{"tipo":"opcion_multiple","enunciado":"Aproximadamente, ¿cuánta agua hace falta para producir 1 kg de carne vacuna?","ayuda":"Pensá en toda la cadena, no en el agua que le das de tomar al animal.","opciones":[{"id":"o1","texto":"15.000 litros"},{"id":"o2","texto":"150.000 litros"},{"id":"o3","texto":"150 litros"},{"id":"o4","texto":"1.500 litros"}]}'::jsonb, '{"explicacion":"Del orden de 15.000 litros por kilo, contando el agua de la pastura y del forraje que el animal comió durante años. El agua que bebe el animal es una fracción mínima del total.","clave":["o1"],"por_opcion":{"o3":{"nota":"Esa es, más o menos, el agua de beber del animal. La cadena entera es mil veces más."}}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":0,"marco":"general","contexto":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.350, 'aprobado'),
