  ((select id from ac_plantillas where generator_hash = 'agua.om.huella_alimento'), 1897088096946691805, '{"tipo":"opcion_multiple","enunciado":"Aproximadamente, ¿cuánta agua hace falta para producir 1 kg de algodón, para una remera?","ayuda":"Pensá en toda la cadena, no en el agua que le das de tomar al animal.","opciones":[{"id":"o1","texto":"2.700 litros"},{"id":"o2","texto":"27 litros"},{"id":"o3","texto":"270 litros"},{"id":"o4","texto":"27.000 litros"}]}'::jsonb, '{"explicacion":"Una remera de algodón se lleva alrededor de 2.700 litros. Por eso usar la ropa que ya tenés mueve más el número que acortar la ducha.","clave":["o1"],"por_opcion":{}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":1,"marco":"general","contexto":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.250, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua.om.huella_alimento'), 1897086997435063594, '{"tipo":"opcion_multiple","enunciado":"Cuando lo ponés en el changuito, ¿cuánta agua hace falta para producir 1 kg de algodón, para una remera?","ayuda":"Pensá en toda la cadena, no en el agua que le das de tomar al animal.","opciones":[{"id":"o1","texto":"270 litros"},{"id":"o2","texto":"2.700 litros"},{"id":"o3","texto":"27 litros"},{"id":"o4","texto":"27.000 litros"}]}'::jsonb, '{"explicacion":"Una remera de algodón se lleva alrededor de 2.700 litros. Por eso usar la ropa que ya tenés mueve más el número que acortar la ducha.","clave":["o2"],"por_opcion":{}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":1,"marco":"compra","contexto":"compra"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.250, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.om.jerarquia'), 8675346360088883353, '{"tipo":"opcion_multiple","enunciado":"Situación: Comprás algo que viene con mucho envase. ¿Cuál es la mejor decisión?","ayuda":null,"opciones":[{"id":"o1","texto":"Reciclar el envase"},{"id":"o2","texto":"Separarlo bien y llevarlo a un Punto Verde"},{"id":"o3","texto":"Elegir, la próxima vez, una opción con menos envase"},{"id":"o4","texto":"Reutilizarlo como recipiente"}]}'::jsonb, '{"explicacion":"Evitar está antes que reutilizar y mucho antes que reciclar. Las otras tres opciones están bien, pero todas actúan cuando el residuo YA existe.","clave":["o3"],"por_opcion":{"o1":{"nota":"Es lo que casi todo el mundo contesta. La trampa está en que reciclar es la cuarta opción de la jerarquía, no la primera."}}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.000, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.om.jerarquia'), 8675345260577255142, '{"tipo":"opcion_multiple","enunciado":"En tu casa, en el AMBA: Comprás algo que viene con mucho envase. ¿Cuál es la mejor decisión?","ayuda":null,"opciones":[{"id":"o1","texto":"Elegir, la próxima vez, una opción con menos envase"},{"id":"o2","texto":"Reutilizarlo como recipiente"},{"id":"o3","texto":"Separarlo bien y llevarlo a un Punto Verde"},{"id":"o4","texto":"Reciclar el envase"}]}'::jsonb, '{"explicacion":"Evitar está antes que reutilizar y mucho antes que reciclar. Las otras tres opciones están bien, pero todas actúan cuando el residuo YA existe.","clave":["o1"],"por_opcion":{"o4":{"nota":"Es lo que casi todo el mundo contesta. La trampa está en que reciclar es la cuarta opción de la jerarquía, no la primera."}}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":0,"marco":"caba","region":"rioplatense"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.000, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.om.jerarquia'), 8150770461925989814, '{"tipo":"opcion_multiple","enunciado":"Situación: Se te rompió el cierre de una campera que todavía está entera. ¿Cuál es la mejor decisión?","ayuda":null,"opciones":[{"id":"o1","texto":"Comprar una nueva y donar esta"},{"id":"o2","texto":"Llevarla a un contenedor de textiles"},{"id":"o3","texto":"Arreglar el cierre y seguir usándola"},{"id":"o4","texto":"Cortarla para usar de trapo"}]}'::jsonb, '{"explicacion":"Alargar la vida útil conserva mucho más valor que cualquier reciclado: no hay que fundir, rehacer ni transportar nada. Reparar es la forma más barata de circularidad.","clave":["o3"],"por_opcion":{}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":1,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.300, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.om.jerarquia'), 8150771561437618025, '{"tipo":"opcion_multiple","enunciado":"En tu casa, en el AMBA: Se te rompió el cierre de una campera que todavía está entera. ¿Cuál es la mejor decisión?","ayuda":null,"opciones":[{"id":"o1","texto":"Llevarla a un contenedor de textiles"},{"id":"o2","texto":"Arreglar el cierre y seguir usándola"},{"id":"o3","texto":"Comprar una nueva y donar esta"},{"id":"o4","texto":"Cortarla para usar de trapo"}]}'::jsonb, '{"explicacion":"Alargar la vida útil conserva mucho más valor que cualquier reciclado: no hay que fundir, rehacer ni transportar nada. Reparar es la forma más barata de circularidad.","clave":["o2"],"por_opcion":{}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":1,"marco":"caba","region":"rioplatense"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.300, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'alimentacion.om.huella_comida'), 1444335287620251128, '{"tipo":"opcion_multiple","enunciado":"¿Qué cambio reduce más la huella de carbono de lo que comés?","ayuda":null,"opciones":[{"id":"o1","texto":"Evitar los productos con envase plástico"},{"id":"o2","texto":"Comprar todo de producción local"},{"id":"o3","texto":"Reemplazar algunas comidas con carne por legumbres"},{"id":"o4","texto":"Elegir siempre la marca con sello verde"}]}'::jsonb, '{"explicacion":"El transporte es una fracción chica de las emisiones de la mayoría de los alimentos. QUÉ comés pesa mucho más que cuánto viajó: la carne vacuna ronda los 27 kg de CO₂ equivalente por kilo y las legumbres andan por 0,9.","clave":["o3"],"por_opcion":{"o2":{"nota":"Es la respuesta más intuitiva y es la que más se repite. Comprar local tiene otras ventajas reales, pero en emisiones el transporte casi nunca es lo que define."}}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'owid-alimentos')), '{"variante":0,"marco":"general","contexto":"general"}'::jsonb, '{"teen","adult"}'::text[], 1, 0.450, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'alimentacion.om.huella_comida'), 1444336387131879339, '{"tipo":"opcion_multiple","enunciado":"Estás armando la compra de la semana. ¿Qué cambio reduce más la huella de carbono de lo que comés?","ayuda":null,"opciones":[{"id":"o1","texto":"Evitar los productos con envase plástico"},{"id":"o2","texto":"Reemplazar algunas comidas con carne por legumbres"},{"id":"o3","texto":"Comprar todo de producción local"},{"id":"o4","texto":"Elegir siempre la marca con sello verde"}]}'::jsonb, '{"explicacion":"El transporte es una fracción chica de las emisiones de la mayoría de los alimentos. QUÉ comés pesa mucho más que cuánto viajó: la carne vacuna ronda los 27 kg de CO₂ equivalente por kilo y las legumbres andan por 0,9.","clave":["o2"],"por_opcion":{"o3":{"nota":"Es la respuesta más intuitiva y es la que más se repite. Comprar local tiene otras ventajas reales, pero en emisiones el transporte casi nunca es lo que define."}}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'owid-alimentos')), '{"variante":0,"marco":"compra","contexto":"compra"}'::jsonb, '{"teen","adult"}'::text[], 1, 0.450, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.om.stock_flujo'), 4549123155892215391, '{"tipo":"opcion_multiple","enunciado":"Un país baja sus emisiones un 20 % y las mantiene ahí durante años. ¿Qué pasa con la concentración de CO₂ en la atmósfera?","ayuda":null,"opciones":[{"id":"o1","texto":"Baja, pero más despacio"},{"id":"o2","texto":"Se mantiene igual"},{"id":"o3","texto":"Baja un 20 %"},{"id":"o4","texto":"Sigue subiendo, un poco más lento"}]}'::jsonb, '{"explicacion":"El CO₂ se acumula. Mientras se siga emitiendo más de lo que el planeta absorbe, la concentración sigue creciendo: emitir menos frena la subida, no la revierte. Es un stock, no un caudal.","clave":["o4"],"por_opcion":{"o2":{"nota":"Sería cierto si la atmósfera fuera un caudal. Es una bañadera: mientras entre más de lo que sale, el nivel sube igual aunque abras menos la canilla."}}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ipcc-ar6')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 2, 1.500, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.om.stock_flujo'), 4016824288054281588, '{"tipo":"opcion_multiple","enunciado":"Un país baja sus emisiones un 50 % y las mantiene ahí durante años. ¿Qué pasa con la concentración de CO₂ en la atmósfera?","ayuda":null,"opciones":[{"id":"o1","texto":"Se mantiene igual"},{"id":"o2","texto":"Baja a la mitad"},{"id":"o3","texto":"Baja lentamente"},{"id":"o4","texto":"Sigue subiendo, bastante más lento"}]}'::jsonb, '{"explicacion":"Aunque el recorte sea grande, mientras las emisiones netas sean positivas la concentración sigue subiendo. Solo se estabiliza cuando se emite tanto como se absorbe.","clave":["o4"],"por_opcion":{}}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ipcc-ar6')), '{"variante":1,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 2, 1.700, 'aprobado'),
