  ((select id from ac_plantillas where generator_hash = 'movilidad.mito.electricos'), 1833735836951184432, '{"tipo":"mito_o_dato","enunciado":"¿Mito o dato?","ayuda":null,"afirmacion":"Los autos eléctricos no contaminan."}'::jsonb, '{"explicacion":"No tienen emisiones por el caño de escape, que no es lo mismo que no tener emisiones: fabricar la batería y generar la electricidad sí emiten. Aun así, en el ciclo de vida completo emiten bastante menos que un auto de combustión comparable en prácticamente toda red estudiada.","es_dato":false}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'icct-ev')), '{"variante":0,"marco":"general","contexto":"general"}'::jsonb, '{"teen","adult"}'::text[], 1, 0.300, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'movilidad.mito.electricos'), 1833736936462812643, '{"tipo":"mito_o_dato","enunciado":"Vos que manejás: ¿mito o dato?","ayuda":null,"afirmacion":"Los autos eléctricos no contaminan."}'::jsonb, '{"explicacion":"No tienen emisiones por el caño de escape, que no es lo mismo que no tener emisiones: fabricar la batería y generar la electricidad sí emiten. Aun así, en el ciclo de vida completo emiten bastante menos que un auto de combustión comparable en prácticamente toda red estudiada.","es_dato":false}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'icct-ev')), '{"variante":0,"marco":"auto","contexto":"auto"}'::jsonb, '{"teen","adult"}'::text[], 1, 0.300, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'movilidad.mito.electricos'), 2366069889161220987, '{"tipo":"mito_o_dato","enunciado":"¿Mito o dato?","ayuda":null,"afirmacion":"Aun contando la fabricación de la batería, un auto eléctrico emite menos que uno naftero comparable a lo largo de su vida."}'::jsonb, '{"explicacion":"Es la conclusión de los análisis de ciclo de vida: la desventaja inicial de fabricar la batería se compensa durante el uso, y cuanto más limpia la red, más rápido se compensa.","es_dato":true}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'icct-ev')), '{"variante":1,"marco":"general","contexto":"general"}'::jsonb, '{"teen","adult"}'::text[], 1, 0.600, 'aprobado'),
