  ((select id from ac_plantillas where generator_hash = 'tronco.mito.ozono_clima'), 4178381656217117193, '{"tipo":"mito_o_dato","enunciado":"¿Mito o dato?","ayuda":null,"afirmacion":"El agujero de la capa de ozono es lo que causa el calentamiento global."}'::jsonb, '{"explicacion":"Son dos problemas distintos. El ozono se agota por los CFC, pasa en la estratósfera y afecta la radiación ultravioleta que llega a la superficie. El calentamiento lo causan los gases de efecto invernadero, pasa en la tropósfera y atrapa calor. Es la confusión más persistente que hay en la enseñanza de temas ambientales.","es_dato":false}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ncse-ozono')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.300, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.mito.ozono_clima'), 3653665020565812646, '{"tipo":"mito_o_dato","enunciado":"¿Mito o dato?","ayuda":null,"afirmacion":"Un invierno muy frío pone en duda el calentamiento global."}'::jsonb, '{"explicacion":"Tiempo no es clima. Una ola de frío es un dato en una serie ruidosa; la tendencia se mide en décadas y sobre todo el planeta, no en una semana y en tu ciudad.","es_dato":false}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ncse-ozono')), '{"variante":1,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.100, 'aprobado'),
