  ((select id from ac_plantillas where generator_hash = 'residuos.greenwashing.mobius'), 7186013386353155176, '{"tipo":"detectar_greenwashing","enunciado":"Marcá lo que NO tiene respaldo.","ayuda":null,"claim":"Lleva el símbolo de las flechitas · Fabricado con plástico PET número 1 · Se recicla en todo el país · Biodegradable","spans":[{"id":"s1","texto":"Lleva el símbolo de las flechitas"},{"id":"s2","texto":"Fabricado con plástico PET número 1"},{"id":"s3","texto":"Se recicla en todo el país"},{"id":"s4","texto":"Biodegradable"}]}'::jsonb, '{"explicacion":"El símbolo de Möbius no garantiza nada: muchas veces solo identifica el tipo de plástico. \"Se recicla en todo el país\" depende de que cada municipio tenga el sistema, y \"biodegradable\" sin decir en qué condiciones no significa casi nada. Lo único verificable es el tipo de resina.","clave":["s1","s3","s4"]}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'yale-reciclaje')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 1, 0.800, 'aprobado'),
