  ((select id from ac_plantillas where generator_hash = 'agua.mapa.cuenca'), 622700153771250855, '{"tipo":"mapa_localizar","enunciado":"En el mapa del AMBA: ¿Cuál es la cuenca que dio lugar al fallo Mendoza y a la creación de ACUMAR?","ayuda":null,"centro":[-34.7,-58.5],"zoom":10,"capa":"ecorregiones","alternativas":[{"id":"a1","texto":"Delta del Paraná"},{"id":"a2","texto":"Cuenca Matanza-Riachuelo"},{"id":"a3","texto":"Cuenca del Río Reconquista"},{"id":"a4","texto":"Bahía de Samborombón"}]}'::jsonb, '{"explicacion":"La Cuenca Matanza-Riachuelo. Viven alrededor de dos millones de personas en ella, y tras el fallo de la Corte Suprema en 2008 se creó ACUMAR, un organismo tripartito entre Nación, Provincia y Ciudad.","clave":["a2"],"region":"Cuenca Matanza-Riachuelo"}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'acumar')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 1, 0.600, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua_azul.mapa.reserva'), 4452374746297266759, '{"tipo":"mapa_localizar","enunciado":"En el mapa de la Ciudad: ¿Cuál es el sitio Ramsar urbano de 350 hectáreas sobre la costa del Río de la Plata?","ayuda":null,"centro":[-34.61,-58.35],"zoom":13,"capa":"ecorregiones","alternativas":[{"id":"a1","texto":"Reserva Ecológica Costanera Sur"},{"id":"a2","texto":"Parque Nacional Ciervo de los Pantanos"},{"id":"a3","texto":"Reserva Natural Lago Lugano"},{"id":"a4","texto":"Bosques de Palermo"}]}'::jsonb, '{"explicacion":"La Reserva Ecológica Costanera Sur, sitio Ramsar desde 2005 y protegida desde 1986. Se armó sola sobre un relleno de escombros: es la mejor historia local de \"la naturaleza vuelve si la dejás\".","clave":["a1"],"region":"Reserva Ecológica Costanera Sur"}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'reserva-costanera-sur')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.400, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.frase.jerarquia'), 2067969326725617936, '{"tipo":"completar_frase","enunciado":"Completá la frase:","ayuda":null,"frase":"En la jerarquía de residuos, {{0}} viene antes que reciclar, y el mejor residuo es {{1}}.","banco":[{"id":"b1","texto":"el que no existe"},{"id":"b2","texto":"separar"},{"id":"b3","texto":"evitar"},{"id":"b4","texto":"el que se recicla"},{"id":"b5","texto":"enterrar"},{"id":"b6","texto":"compostar"}]}'::jsonb, '{"explicacion":"Evitar, reducir, reutilizar y recién después reciclar. El residuo que no se genera no hay que transportarlo, ni clasificarlo, ni fundirlo.","clave":["b3","b1"]}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.400, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'plantas.frase.ombu'), 6093796031851147834, '{"tipo":"completar_frase","enunciado":"Completá la frase:","ayuda":null,"frase":"El {{0}} es la flor nacional argentina, y el {{1}} no es técnicamente un árbol sino una hierba gigante.","banco":[{"id":"b1","texto":"jacarandá"},{"id":"b2","texto":"ombú"},{"id":"b3","texto":"palo borracho"},{"id":"b4","texto":"sauce criollo"},{"id":"b5","texto":"ceibo"},{"id":"b6","texto":"timbó"}]}'::jsonb, '{"explicacion":"El ceibo (Erythrina crista-galli) es la flor nacional. El ombú (Phytolacca dioica) tiene tronco blando y sin anillos de crecimiento: es una hierba gigante, no un árbol.","clave":["b5","b2"]}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'plantas-nativas')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.100, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'plantas.frase.ombu'), 6618512667502452381, '{"tipo":"completar_frase","enunciado":"Completá la frase:","ayuda":null,"frase":"Una especie {{0}} es la que evolucionó en el lugar, y una {{1}} es la exótica que además desplaza a las nativas.","banco":[{"id":"b1","texto":"ornamental"},{"id":"b2","texto":"naturalizada"},{"id":"b3","texto":"nativa"},{"id":"b4","texto":"endémica"},{"id":"b5","texto":"exótica"},{"id":"b6","texto":"invasora"}]}'::jsonb, '{"explicacion":"No toda exótica es invasora: muchas conviven sin problema. Invasora es la que se expande sola y desplaza a las nativas, como el ligustro o la acacia negra en el Delta.","clave":["b3","b6"]}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'plantas-nativas')), '{"variante":1,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, 0.300, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.frase.stock'), 6514680430464690229, '{"tipo":"completar_frase","enunciado":"Completá la frase:","ayuda":null,"frase":"El CO₂ se {{0}} en la atmósfera, así que bajar las emisiones {{1}} la subida pero no la revierte.","banco":[{"id":"b1","texto":"acumula"},{"id":"b2","texto":"frena"},{"id":"b3","texto":"revierte"},{"id":"b4","texto":"evapora"},{"id":"b5","texto":"multiplica"},{"id":"b6","texto":"disuelve"}]}'::jsonb, '{"explicacion":"Es un stock, no un caudal. La concentración solo se estabiliza cuando se emite tanto como se absorbe: hasta ahí, sigue subiendo aunque más despacio.","clave":["b1","b2"]}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'ipcc-ar6')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"teen","adult"}'::text[], 2, 1.000, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.microlectura.sistemas'), 7821618571844305535, '{"tipo":"microlectura","enunciado":"Antes de arrancar","ayuda":null,"cuerpo":"Cuando mirás una plaza ves pasto, árboles y algún bicho. Un ecosistema no es esa lista: es lo que se hacen entre sí. El árbol da sombra y baja la temperatura, la sombra deja que crezcan otras plantas, esas plantas alimentan insectos, los insectos polinizan y traen pájaros. Sacá una pieza y se mueven las otras.","destacado":"Un ecosistema no es una colección. Es una red."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'naaee-guidelines')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -1.200, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.microlectura.sistemas'), 7821617472332677324, '{"tipo":"microlectura","enunciado":"Pensalo con la plaza de tu barrio","ayuda":null,"cuerpo":"Cuando mirás una plaza ves pasto, árboles y algún bicho. Un ecosistema no es esa lista: es lo que se hacen entre sí. El árbol da sombra y baja la temperatura, la sombra deja que crezcan otras plantas, esas plantas alimentan insectos, los insectos polinizan y traen pájaros. Sacá una pieza y se mueven las otras.","destacado":"Un ecosistema no es una colección. Es una red."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'naaee-guidelines')), '{"variante":0,"marco":"plaza","region":"rioplatense"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -1.200, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.microlectura.sistemas'), 7044436474219659412, '{"tipo":"microlectura","enunciado":"Antes de arrancar","ayuda":null,"cuerpo":"Los ecosistemas hacen trabajo que nadie factura: filtran agua, polinizan lo que comés, guardan carbono, bajan la temperatura de una cuadra. Se llaman servicios ecosistémicos y tienen una característica incómoda: casi siempre se notan cuando faltan, no cuando están.","destacado":"El trabajo mejor hecho es el que no se ve."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'naaee-guidelines')), '{"variante":1,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -1.200, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'tronco.microlectura.sistemas'), 7044437573731287623, '{"tipo":"microlectura","enunciado":"Pensalo con la plaza de tu barrio","ayuda":null,"cuerpo":"Los ecosistemas hacen trabajo que nadie factura: filtran agua, polinizan lo que comés, guardan carbono, bajan la temperatura de una cuadra. Se llaman servicios ecosistémicos y tienen una característica incómoda: casi siempre se notan cuando faltan, no cuando están.","destacado":"El trabajo mejor hecho es el que no se ve."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'naaee-guidelines')), '{"variante":1,"marco":"plaza","region":"rioplatense"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -1.200, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua.microlectura.virtual'), 723122622173949692, '{"tipo":"microlectura","enunciado":"Para empezar","ayuda":null,"cuerpo":"El agua que usás no es la que sale de tu canilla. La mayor parte se gastó antes, en otro lado, para producir lo que comprás y comés: se llama agua virtual. Un kilo de carne vacuna se lleva del orden de 15.000 litros contando toda la cadena. Una remera de algodón, unos 2.700.","destacado":"La ducha se ve. Los 2.700 litros de la remera, no."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":0,"marco":"general","contexto":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.600, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua.microlectura.virtual'), 723123721685577903, '{"tipo":"microlectura","enunciado":"La próxima vez que estés en la góndola","ayuda":null,"cuerpo":"El agua que usás no es la que sale de tu canilla. La mayor parte se gastó antes, en otro lado, para producir lo que comprás y comés: se llama agua virtual. Un kilo de carne vacuna se lleva del orden de 15.000 litros contando toda la cadena. Una remera de algodón, unos 2.700.","destacado":"La ducha se ve. Los 2.700 litros de la remera, no."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":0,"marco":"compra","contexto":"compra"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.600, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua.microlectura.virtual'), 1255456674383986247, '{"tipo":"microlectura","enunciado":"Para empezar","ayuda":null,"cuerpo":"La huella hídrica se parte en tres colores. La verde es agua de lluvia que el cultivo se toma del suelo. La azul es la que se saca de un río o de una napa. La gris es la que haría falta para diluir la contaminación que se generó. No son intercambiables: un litro azul en una zona seca no vale lo mismo que uno verde.","destacado":"Verde, azul y gris. Un litro no vale igual que otro."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":1,"marco":"general","contexto":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.600, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'agua.microlectura.virtual'), 1255455574872358036, '{"tipo":"microlectura","enunciado":"La próxima vez que estés en la góndola","ayuda":null,"cuerpo":"La huella hídrica se parte en tres colores. La verde es agua de lluvia que el cultivo se toma del suelo. La azul es la que se saca de un río o de una napa. La gris es la que haría falta para diluir la contaminación que se generó. No son intercambiables: un litro azul en una zona seca no vale lo mismo que uno verde.","destacado":"Verde, azul y gris. Un litro no vale igual que otro."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'huella-hidrica')), '{"variante":1,"marco":"compra","contexto":"compra"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.600, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.microlectura.jerarquia'), 4903124621068467887, '{"tipo":"microlectura","enunciado":"Una idea para arrancar","ayuda":null,"cuerpo":"El orden importa y casi nunca se dice completo. Primero evitar que el residuo exista. Después reducir. Después reutilizar. Recién ahí reciclar y compostar. Después recuperar energía. Y al final, enterrar. Reciclar no es el primer paso: es el cuarto, y llega cuando las tres decisiones anteriores ya se perdieron.","destacado":"El mejor residuo es el que no existe."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":0,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.800, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.microlectura.jerarquia'), 4903123521556839676, '{"tipo":"microlectura","enunciado":"Acá, en el AMBA","ayuda":null,"cuerpo":"El orden importa y casi nunca se dice completo. Primero evitar que el residuo exista. Después reducir. Después reutilizar. Recién ahí reciclar y compostar. Después recuperar energía. Y al final, enterrar. Reciclar no es el primer paso: es el cuarto, y llega cuando las tres decisiones anteriores ya se perdieron.","destacado":"El mejor residuo es el que no existe."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":0,"marco":"caba","region":"rioplatense"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.800, 'aprobado')
