  ((select id from ac_plantillas where generator_hash = 'residuos.microlectura.jerarquia'), 4370825753230534084, '{"tipo":"microlectura","enunciado":"Una idea para arrancar","ayuda":null,"cuerpo":"En un relleno sanitario la basura queda enterrada durante décadas, y la parte orgánica se pudre sin oxígeno. Eso genera metano, un gas de efecto invernadero mucho más potente que el CO₂ en el corto plazo. Por eso compostar en casa no es un gesto decorativo: saca del relleno la fracción que más pesa.","destacado":"Lo orgánico enterrado no desaparece: se convierte en metano."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":1,"marco":"general","region":"general"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.800, 'aprobado'),
  ((select id from ac_plantillas where generator_hash = 'residuos.microlectura.jerarquia'), 4370826852742162295, '{"tipo":"microlectura","enunciado":"Acá, en el AMBA","ayuda":null,"cuerpo":"En un relleno sanitario la basura queda enterrada durante décadas, y la parte orgánica se pudre sin oxígeno. Eso genera metano, un gas de efecto invernadero mucho más potente que el CO₂ en el corto plazo. Por eso compostar en casa no es un gesto decorativo: saca del relleno la fracción que más pesa.","destacado":"Lo orgánico enterrado no desaparece: se convierte en metano."}'::jsonb, '{}'::jsonb || jsonb_build_object('fuente_id', (select id from ac_fuentes where slug = 'epa')), '{"variante":1,"marco":"caba","region":"rioplatense"}'::jsonb, '{"kid","teen","adult"}'::text[], 1, -0.800, 'aprobado'),
